/* Déclic — Notions fondamentales : analyse (6) — autres bases, différentielle, parties, substitution, fonctions réciproques */
(()=>{
/* ---------- helpers locaux ---------- */
const E=s=>`e<sup>${s}</sup>`;
const B=(c,h)=>`<div class="${c}">${h}</div>`;
const DEF=h=>B('def',h), THM=h=>B('thm',h), PROP=h=>B('prop',h), IDEA=h=>B('idea',h), WHY=h=>B('why',h), EX=h=>B('ex',h), WARN=h=>B('warn',h), KEEP=h=>B('keep',h);
const BLK=(t,h)=>`<div class="blk" data-t="${t}">${h}</div>`;
const RAP=h=>BLK('Rappel',h);
const tab=(head,rows)=>`<table style="border-collapse:collapse;margin:6px auto"><tr>${head.map(h=>`<th style="border-bottom:2px solid var(--line);padding:4px 9px">${h}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td style="padding:4px 9px;text-align:center;border-bottom:1px solid var(--line)">${c}</td>`).join('')}</tr>`).join('')}</table>`;
const ch=Math.cosh, sh=Math.sinh, th=Math.tanh;
const asinh=x=>Math.log(x+Math.sqrt(x*x+1)), acosh=x=>Math.log(x+Math.sqrt(x*x-1)), atanh=x=>.5*Math.log((1+x)/(1-x));
// repère avec étiquettes d'axes
const axes=(P,xr,yr,lx='x',ly='y')=>{ P.text(xr[1],0,lx,{a:'end',dy:-6,c:'var(--muted)',s:11}).text(0,yr[1],ly,{dx:6,dy:10,c:'var(--muted)',s:11}); return P; };

COURS.push(
/* ===================== 1. AUTRES BASES ET LIMITES CLASSIQUES ===================== */
{subj:'gred',sem:'ana',id:'gred-bases-limites',h:'Autres bases et limites classiques',p:'Définir aˣ, logₐ et x^α pour tous les réels grâce à exp et ln, puis démontrer les limites qui classent les infinis : logarithme, puissances, exponentielle.',steps:[
  {h:'De la racine à l’exponentielle de base a',p:`<p>Tu sais ce que vaut 2³ (trois facteurs 2) et 2<sup>1/2</sup> (la racine carrée de 2). Mais que vaut 2<sup>√2</sup> ? Aucune multiplication répétée, aucune racine ne le définit : l’exposant n’est pas une fraction. Il faut une définition qui marche pour <b>tout</b> exposant réel, et qui redonne les anciennes valeurs quand l’exposant est rationnel.</p>
${RAP('<p>Le logarithme ln est défini sur ]0 ; +∞[ par ln <i>x</i> = ∫₁ˣ d<i>t</i>/<i>t</i>, et exp est sa réciproque : e<sup>ln <i>x</i></sup> = <i>x</i> pour <i>x</i> &gt; 0, ln(e<sup><i>y</i></sup>) = <i>y</i> pour tout <i>y</i>. On a ln(<i>ab</i>) = ln <i>a</i> + ln <i>b</i>, donc ln(<i>a</i><sup><i>n</i></sup>) = <i>n</i> ln <i>a</i> pour <i>n</i> entier.</p>')}
${DEF(`<p>Pour <i>a</i> &gt; 0 et <i>x</i> ∈ ℝ, on pose <b><i>a</i><sup><i>x</i></sup> = ${E('<i>x</i> ln <i>a</i>')}</b>. La fonction <i>x</i> ↦ <i>a</i><sup><i>x</i></sup> est l’<b>exponentielle de base <i>a</i></b>.</p>`)}
${IDEA(`<p>Comme <i>a</i> = ${E('ln <i>a</i>')}, écrire <i>a</i><sup><i>x</i></sup> = (${E('ln <i>a</i>')})<sup><i>x</i></sup> = ${E('<i>x</i> ln <i>a</i>')} est la seule façon raisonnable de prolonger la règle (e<sup><i>u</i></sup>)<sup><i>v</i></sup> = e<sup><i>uv</i></sup>. Toute la théorie des puissances se ramène ainsi à une seule fonction, exp, et à une seule constante par base, ln <i>a</i>.</p>`)}
${WHY(`<p>La définition est <b>cohérente</b> avec les racines. Prenons <i>x</i> = <i>p</i>/<i>q</i> avec <i>q</i> ≥ 1. Le nombre <i>y</i> = ${E('(<i>p</i>/<i>q</i>) ln <i>a</i>')} est positif et vérifie <i>y</i><sup><i>q</i></sup> = ${E('<i>p</i> ln <i>a</i>')} = <i>a</i><sup><i>p</i></sup>. C’est donc l’unique racine <i>q</i>-ième positive de <i>a</i><sup><i>p</i></sup>, exactement ce qu’on appelait <i>a</i><sup><i>p</i>/<i>q</i></sup>.</p>`)}
${EX(`<p>2³ = ${E('3 ln 2')} = ${E('ln 8')} = 8. Et 2<sup>√2</sup> = ${E('√2 · ln 2')} ≈ ${E('0,980')} ≈ 2,665 : un nombre bien défini, qu’on peut encadrer par 2<sup>1,4</sup> et 2<sup>1,5</sup>.</p>`)}
${WARN('<p>La base doit être strictement positive : (−2)<sup><i>x</i></sup> n’a pas de sens pour <i>x</i> réel quelconque, car ln(−2) n’existe pas. Et 1<sup><i>x</i></sup> = e<sup>0</sup> = 1 pour tout <i>x</i>.</p>')}
<p>Fais varier la base <i>a</i> : toutes les courbes passent par (0 ; 1), montent si <i>a</i> &gt; 1, descendent si <i>a</i> &lt; 1.</p>`,
   params:[{id:'a',l:'base a',min:.25,max:4,step:.25,v:2}],
   draw:v=>{ const P=plane({x:[-3,3],y:[-1,8],h:300,lab:1}); P.fn(Math.exp,{c:'var(--muted)',w:1.5,dash:true}).fn(x=>Math.exp(x*Math.log(v.a)),{c:'var(--math)'}).dot(0,1,{l:'(0 ; 1)'}).dot(1,v.a,{c:'var(--spark)',l:'(1 ; a)'}); return axes(P,[-3,3],[-1,8]).svg(); },
   info:v=>`<i>a</i> = ${fmt(v.a)} : <i>a</i><sup><i>x</i></sup> = e<sup>${fmt(Math.log(v.a),3)} <i>x</i></sup> (ln <i>a</i> ≈ ${fmt(Math.log(v.a),3)}). En pointillé : e<sup><i>x</i></sup>.`},
  {h:'Règles de calcul et dérivée de aˣ',p:`<p>Puisque <i>a</i><sup><i>x</i></sup> n’est qu’une exponentielle déguisée, toutes ses propriétés se déduisent de celles de exp. Il n’y a rien de nouveau à apprendre par cœur : il suffit de traduire.</p>
${PROP(`<p>Pour <i>a</i>, <i>b</i> &gt; 0 et <i>x</i>, <i>y</i> réels : <b><i>a</i><sup><i>x</i>+<i>y</i></sup> = <i>a</i><sup><i>x</i></sup><i>a</i><sup><i>y</i></sup></b>, <b>(<i>a</i><sup><i>x</i></sup>)<sup><i>y</i></sup> = <i>a</i><sup><i>xy</i></sup></b>, <b>(<i>ab</i>)<sup><i>x</i></sup> = <i>a</i><sup><i>x</i></sup><i>b</i><sup><i>x</i></sup></b>, <i>a</i><sup>−<i>x</i></sup> = 1/<i>a</i><sup><i>x</i></sup>, et <b>ln(<i>a</i><sup><i>x</i></sup>) = <i>x</i> ln <i>a</i></b>.</p>`)}
${WHY(`<p>Chaque règle est une règle de exp : <i>a</i><sup><i>x</i></sup><i>a</i><sup><i>y</i></sup> = ${E('<i>x</i> ln <i>a</i>')}${E('<i>y</i> ln <i>a</i>')} = ${E('(<i>x</i>+<i>y</i>) ln <i>a</i>')} = <i>a</i><sup><i>x</i>+<i>y</i></sup>. Pour la deuxième : ln(<i>a</i><sup><i>x</i></sup>) = <i>x</i> ln <i>a</i>, donc (<i>a</i><sup><i>x</i></sup>)<sup><i>y</i></sup> = ${E('<i>y</i> · <i>x</i> ln <i>a</i>')} = <i>a</i><sup><i>xy</i></sup>.</p>`)}
${THM(`<p>La fonction <i>x</i> ↦ <i>a</i><sup><i>x</i></sup> est dérivable sur ℝ et <b>(<i>a</i><sup><i>x</i></sup>)′ = ln <i>a</i> · <i>a</i><sup><i>x</i></sup></b>. Elle est strictement croissante si <i>a</i> &gt; 1, strictement décroissante si 0 &lt; <i>a</i> &lt; 1.</p>`)}
${WHY(`<p>On dérive la composée <i>x</i> ↦ ${E('<i>x</i> ln <i>a</i>')} : la dérivée de l’intérieur est la constante ln <i>a</i>, celle de exp est exp elle-même. Le signe de la dérivée est celui de ln <i>a</i> : positif si <i>a</i> &gt; 1, négatif si <i>a</i> &lt; 1. C’est pour ça que seule la base e a une dérivée égale à elle-même : ln e = 1.</p>`)}
${EX('<p>(2<sup><i>x</i></sup>)′ = 2<sup><i>x</i></sup> ln 2. En <i>x</i> = 0, la pente de la courbe de 2<sup><i>x</i></sup> vaut ln 2 ≈ 0,693. Pour (1/2)<sup><i>x</i></sup> = 2<sup>−<i>x</i></sup>, la pente en 0 vaut −ln 2.</p>')}
${WARN('<p>Ne confonds pas <i>a</i><sup><i>x</i></sup> (la variable est en haut) et <i>x</i><sup><i>a</i></sup> (la variable est en bas). Leurs dérivées n’ont rien à voir : (2<sup><i>x</i></sup>)′ = 2<sup><i>x</i></sup> ln 2, mais (<i>x</i>²)′ = 2<i>x</i>.</p>')}`,
   note:'Toute exponentielle de base a s’écrit aussi e<sup>kx</sup> avec k = ln a. Les physiciens préfèrent souvent e<sup>kx</sup>, les biologistes 2<sup>t/T</sup> (temps de doublement T) : c’est la même famille de fonctions.'},
  {h:'La pente de 2ˣ',p:'Quelle est la pente de la tangente à la courbe de <i>f</i>(<i>x</i>) = 2<sup><i>x</i></sup> au point d’abscisse 3 ? Arrondis au millième.',lab:'f′(3) =',ans:8*Math.log(2),tol:.002,
   why:'f′(x) = 2ˣ ln 2, donc f′(3) = 8 ln 2 ≈ 5,545. La pente est proportionnelle à la hauteur, avec le facteur ln 2.'},
  {h:'Le logarithme de base a',p:`<p>Pour <i>a</i> &gt; 1, la fonction <i>x</i> ↦ <i>a</i><sup><i>x</i></sup> est continue, strictement croissante, tend vers 0 en −∞ et vers +∞ en +∞ : c’est une bijection de ℝ sur ]0 ; +∞[. L’équation <i>a</i><sup><i>y</i></sup> = <i>x</i> a donc une unique solution pour chaque <i>x</i> &gt; 0. Comment la calculer ?</p>
${DEF(`<p>Pour <i>a</i> &gt; 0, <i>a</i> ≠ 1 et <i>x</i> &gt; 0, le <b>logarithme de base <i>a</i></b> de <i>x</i> est <b>log<sub><i>a</i></sub> <i>x</i> = ${F('ln <i>x</i>','ln <i>a</i>')}</b>. C’est l’unique réel <i>y</i> tel que <i>a</i><sup><i>y</i></sup> = <i>x</i>.</p>`)}
${WHY(`<p><i>a</i><sup><i>y</i></sup> = <i>x</i> ⇔ ${E('<i>y</i> ln <i>a</i>')} = <i>x</i> ⇔ <i>y</i> ln <i>a</i> = ln <i>x</i> ⇔ <i>y</i> = ln <i>x</i>/ln <i>a</i>, en appliquant ln (qui est bijective) puis en divisant par ln <i>a</i> ≠ 0. Le logarithme de base <i>a</i> est donc la réciproque de l’exponentielle de base <i>a</i>, et ce n’est que ln à un facteur constant près.</p>`)}
${PROP(`<p>log<sub><i>a</i></sub>(<i>xy</i>) = log<sub><i>a</i></sub> <i>x</i> + log<sub><i>a</i></sub> <i>y</i>, log<sub><i>a</i></sub>(<i>x</i><sup><i>r</i></sup>) = <i>r</i> log<sub><i>a</i></sub> <i>x</i>, log<sub><i>a</i></sub> <i>a</i> = 1, log<sub><i>a</i></sub> 1 = 0, et <b>(log<sub><i>a</i></sub> <i>x</i>)′ = ${F(1,'<i>x</i> ln <i>a</i>')}</b>. Changement de base : log<sub><i>b</i></sub> <i>x</i> = ${F('log<sub><i>a</i></sub> <i>x</i>','log<sub><i>a</i></sub> <i>b</i>')}.</p>`)}
${EX('<p>log<sub>2</sub> 32 = ln 32/ln 2 = 5 ln 2/ln 2 = 5, et en effet 2⁵ = 32. log<sub>10</sub> 1000 = 3. log<sub>2</sub>(1/8) = −3. Le logarithme décimal log<sub>10</sub> compte les chiffres : un nombre à 7 chiffres a un log<sub>10</sub> entre 6 et 7. Le logarithme binaire log<sub>2</sub> compte les doublements.</p>')}
${WARN('<p>Toutes les courbes de logarithmes passent par (1 ; 0) et sont proportionnelles entre elles : log<sub>2</sub> <i>x</i> = ln <i>x</i>/ln 2 ≈ 1,443 ln <i>x</i>. Si <i>a</i> &lt; 1, ln <i>a</i> &lt; 0 et log<sub><i>a</i></sub> est décroissante.</p>')}`,
   fig:(()=>{ const P=plane({x:[-.5,8],y:[-3.5,3.5],h:260,lab:1}); P.fn(x=>Math.log(x)/Math.log(2),{c:'var(--spark)'}).fn(Math.log,{c:'var(--math)'}).fn(x=>Math.log10(x),{c:'var(--accent)'}).text(7.8,3,'log₂',{a:'end',c:'var(--spark)'}).text(7.8,2,'ln',{a:'end',c:'var(--math)'}).text(7.8,.9,'log₁₀',{a:'end',c:'var(--accent)'}).dot(1,0,{l:'(1 ; 0)'}); return P.svg(); })()},
  {h:'Un logarithme de base 4',p:'Calcule log<sub>4</sub> 32 (valeur exacte, écrite en décimal).',lab:'log₄ 32 =',ans:2.5,tol:.001,
   why:'log₄ 32 = ln 32/ln 4 = 5 ln 2/(2 ln 2) = 5/2. Contrôle : 4^(5/2) = (√4)⁵ = 2⁵ = 32.'},
  {h:'Puissances d’exposant réel : x^α',p:`<p>On sait dériver <i>x</i>ⁿ pour <i>n</i> entier, et √<i>x</i> ou 1/<i>x</i> à part. La même idée que pour <i>a</i><sup><i>x</i></sup> définit <i>x</i><sup>α</sup> pour n’importe quel exposant réel α, et unifie toutes ces formules.</p>
${DEF(`<p>Pour <i>x</i> &gt; 0 et α ∈ ℝ, on pose <b><i>x</i><sup>α</sup> = ${E('α ln <i>x</i>')}</b>. La fonction <i>x</i> ↦ <i>x</i><sup>α</sup> sur ]0 ; +∞[ est la <b>fonction puissance</b> d’exposant α.</p>`)}
${THM(`<p>La fonction puissance est dérivable sur ]0 ; +∞[ et <b>(<i>x</i><sup>α</sup>)′ = α <i>x</i><sup>α−1</sup></b>, pour tout α réel. Elle est strictement croissante si α &gt; 0, décroissante si α &lt; 0, et <i>x</i><sup>α</sup> <i>x</i><sup>β</sup> = <i>x</i><sup>α+β</sup>, (<i>x</i><sup>α</sup>)<sup>β</sup> = <i>x</i><sup>αβ</sup>.</p>`)}
${WHY(`<p>Dérivée d’une composée : (${E('α ln <i>x</i>')})′ = ${E('α ln <i>x</i>')} · α/<i>x</i> = α <i>x</i><sup>α</sup>/<i>x</i> = α <i>x</i><sup>α−1</sup>, en utilisant <i>x</i><sup>α</sup>/<i>x</i> = <i>x</i><sup>α−1</sup>. La formule connue pour les entiers reste donc vraie pour tous les réels, avec une seule preuve.</p>`)}
${EX(`<p>√<i>x</i> = <i>x</i><sup>1/2</sup> donne (√<i>x</i>)′ = ½ <i>x</i><sup>−1/2</sup> = 1/(2√<i>x</i>). Et (<i>x</i><sup>√2</sup>)′ = √2 <i>x</i><sup>√2−1</sup>, (<i>x</i><sup>π</sup>)′ = π <i>x</i><sup>π−1</sup>. Pour <i>x</i><sup>−3</sup> = 1/<i>x</i>³ : (<i>x</i><sup>−3</sup>)′ = −3<i>x</i><sup>−4</sup>.</p>`)}
${WARN(`<p>Une fonction comme <i>x</i><sup><i>x</i></sup> n’est ni une puissance (l’exposant varie), ni une exponentielle (la base varie). Aucune des deux formules ne s’applique : il faut revenir à ${E('<i>x</i> ln <i>x</i>')}, ce que la méthode suivante explique.</p>`)}
<p>Règle le curseur α et observe la pente en <i>x</i> = 1 : elle vaut toujours α, puisque (<i>x</i><sup>α</sup>)′ = α <i>x</i><sup>α−1</sup> et 1<sup>α−1</sup> = 1.</p>`,
   params:[{id:'al',l:'exposant α',min:-2,max:3,step:.25,v:.5}],
   draw:v=>{ const P=plane({x:[-.3,4],y:[-1,5],h:280,lab:1}); P.fn(x=>x>0?Math.exp(v.al*Math.log(x)):NaN,{c:'var(--math)',from:.001}).seg(.3,1+v.al*(.3-1),1.9,1+v.al*(1.9-1),{c:'var(--spark)',w:2,dash:true}).dot(1,1,{l:'(1 ; 1)'}); return axes(P,[-.3,4],[-1,5]).svg(); },
   info:v=>`α = ${fmt(v.al)} : <i>x</i><sup>α</sup> a pour pente α = ${fmt(v.al)} en <i>x</i> = 1 (tangente en pointillé). ${v.al>0?'Croissante.':v.al<0?'Décroissante.':'Constante égale à 1.'}`},
  {h:'Trouve l’exposant',p:'La courbe de <i>x</i><sup>α</sup> passe par (1 ; 1) et sa tangente en ce point est tracée. Règle α pour que cette tangente passe aussi par le point (3 ; 4).',
   params:[{id:'al',l:'exposant α',min:-2,max:3,step:.25,v:1}],
   draw:v=>{ const P=plane({x:[-.3,4],y:[-1,5],h:280,lab:1}); P.fn(x=>x>0?Math.exp(v.al*Math.log(x)):NaN,{c:'var(--math)',from:.001}).seg(-.3,1+v.al*(-1.3),4,1+v.al*3,{c:'var(--spark)',w:2,dash:true}).dot(1,1,{l:'(1 ; 1)'}).dot(3,4,{c:'var(--bad)',l:'(3 ; 4)'}); return axes(P,[-.3,4],[-1,5]).svg(); },
   info:v=>`Pente de la tangente en 1 : α = ${fmt(v.al)}. La tangente passe par (3 ; ${fmt(1+2*v.al)}).`,
   ok:v=>Math.abs(v.al-1.5)<1e-9,
   why:'La tangente en (1 ; 1) a pour pente α. Pour atteindre (3 ; 4), il faut monter de 3 sur 2 unités : α = 3/2. Vérifie : (x^1,5)′ = 1,5 x^0,5 vaut 1,5 en x = 1.'},
  {kind:'Méthode',h:'Dériver u(x)^v(x) en passant par l’exponentielle',
   p:`<p><b>Quand :</b> la variable est à la fois dans la base et dans l’exposant (<i>x</i><sup><i>x</i></sup>, (1 + 1/<i>x</i>)<sup><i>x</i></sup>, (sin <i>x</i>)<sup><i>x</i></sup>), ou dès qu’une formule de dérivation ne s’applique pas directement. <b>Pourquoi ça marche :</b> par définition, <i>u</i><sup><i>v</i></sup> = ${E('<i>v</i> ln <i>u</i>')} (il faut <i>u</i> &gt; 0), et on sait dériver une exponentielle composée : (${E('<i>w</i>')})′ = <i>w</i>′ ${E('<i>w</i>')}. <b>Comment :</b></p><ol><li>écris <i>f</i>(<i>x</i>) = ${E('<i>v</i>(<i>x</i>) ln <i>u</i>(<i>x</i>)')} ;</li><li>dérive l’exposant <i>w</i> = <i>v</i> ln <i>u</i> avec la règle du produit : <i>w</i>′ = <i>v</i>′ ln <i>u</i> + <i>v</i> <i>u</i>′/<i>u</i> ;</li><li>conclus <i>f</i>′ = <i>w</i>′ · <i>f</i>, et remplace ${E('<i>w</i>')} par <i>u</i><sup><i>v</i></sup> dans le résultat.</li></ol>`,
   demo:{enonce:'Dérive <i>f</i>(<i>x</i>) = <i>x</i><sup><i>x</i></sup> sur ]0 ; +∞[ et trouve son minimum.',
    etapes:[{f:`<i>f</i>(<i>x</i>) = ${E('<i>x</i> ln <i>x</i>')}`,w:'Définition de la puissance : la base x est positive, on peut prendre son logarithme.'},
     {f:'<i>w</i>(<i>x</i>) = <i>x</i> ln <i>x</i>, donc <i>w</i>′(<i>x</i>) = 1 · ln <i>x</i> + <i>x</i> · 1/<i>x</i> = ln <i>x</i> + 1.',w:'Règle du produit sur l’exposant.'},
     {f:`<i>f</i>′(<i>x</i>) = (ln <i>x</i> + 1) ${E('<i>x</i> ln <i>x</i>')} = (ln <i>x</i> + 1) <i>x</i><sup><i>x</i></sup>.`,w:'Dérivée de e^w : w′ e^w, puis on revient à l’écriture de départ.'},
     {f:'<i>f</i>′(<i>x</i>) = 0 ⇔ ln <i>x</i> = −1 ⇔ <i>x</i> = 1/e ≈ 0,368.',w:'x^x est toujours strictement positif : le signe de f′ est celui de ln x + 1, négatif avant 1/e, positif après.'}],
    conclusion:'<i>f</i> décroît sur ]0 ; 1/e] puis croît : son minimum vaut <i>f</i>(1/e) = e<sup>−1/e</sup> ≈ 0,692. Ni la formule (<i>x</i><sup>α</sup>)′ = α<i>x</i><sup>α−1</sup> ni (<i>a</i><sup><i>x</i></sup>)′ = <i>a</i><sup><i>x</i></sup> ln <i>a</i> n’aurait donné ce résultat : chacune oublie la moitié de la variation.'},
   note:'Même recette pour une limite : x^x = e^(x ln x), et on étudie l’exposant. Le chapitre montre plus bas que x ln x → 0 en 0⁺, donc x^x → 1.'},
  {h:'Dérivée de xˣ en 2',p:'On a vu que (<i>x</i><sup><i>x</i></sup>)′ = (ln <i>x</i> + 1) <i>x</i><sup><i>x</i></sup>. Calcule la dérivée de <i>x</i><sup><i>x</i></sup> en <i>x</i> = 2, arrondie au millième.',lab:'f′(2) =',ans:4*(Math.log(2)+1),tol:.002,
   why:'f′(2) = (ln 2 + 1) · 2² = 4(ln 2 + 1) ≈ 4 · 1,693 ≈ 6,773.'},
  {h:'L’encadrement fondamental de ln',p:`<p>Pour comparer ln <i>x</i> aux puissances de <i>x</i> quand <i>x</i> devient grand, il faut une inégalité concrète. La courbe de ln est au-dessous de sa tangente en 1 : c’est tout ce dont on a besoin.</p>
${THM('<p>Pour tout <i>x</i> &gt; 0 : <b>ln <i>x</i> ≤ <i>x</i> − 1</b>, avec égalité seulement en <i>x</i> = 1.</p>')}
${WHY('<p>Pose <i>g</i>(<i>x</i>) = <i>x</i> − 1 − ln <i>x</i> sur ]0 ; +∞[. Alors <i>g</i>′(<i>x</i>) = 1 − 1/<i>x</i>, négative sur ]0 ; 1[, positive sur ]1 ; +∞[. Donc <i>g</i> décroît puis croît, et son minimum est <i>g</i>(1) = 0. Ainsi <i>g</i>(<i>x</i>) ≥ 0 partout, c’est-à-dire ln <i>x</i> ≤ <i>x</i> − 1.</p>')}
${IDEA('<p>La droite <i>y</i> = <i>x</i> − 1 est la tangente à ln en (1 ; 0). Comme ln est concave (sa dérivée 1/<i>x</i> décroît), la courbe reste sous chacune de ses tangentes. L’inégalité dit que ln croît moins vite qu’une fonction affine. On va la renforcer : appliquée à √<i>x</i> au lieu de <i>x</i>, elle montre que ln croît moins vite que <b>n’importe quelle</b> racine.</p>')}
${EX('<p>Pour <i>x</i> &gt; 1, écris ln <i>x</i> = 2 ln √<i>x</i> ≤ 2(√<i>x</i> − 1) &lt; 2√<i>x</i>. D’où <b>0 &lt; ln <i>x</i>/<i>x</i> &lt; 2/√<i>x</i></b>. En <i>x</i> = 10 000 : ln <i>x</i>/<i>x</i> ≈ 0,00092, et la borne 2/√<i>x</i> vaut 0,02. Les deux tendent vers 0.</p>')}
${WARN('<p>L’inégalité ln <i>x</i> ≤ <i>x</i> − 1 vaut pour <b>tout</b> <i>x</i> &gt; 0, y compris entre 0 et 1 où les deux membres sont négatifs. Avec <i>x</i> = 1 + <i>h</i>, elle devient ln(1 + <i>h</i>) ≤ <i>h</i>, et avec <i>x</i> = e<sup><i>t</i></sup> : <i>t</i> ≤ e<sup><i>t</i></sup> − 1, soit e<sup><i>t</i></sup> ≥ 1 + <i>t</i>.</p>')}`,
   fig:(()=>{ const P=plane({x:[-.5,5],y:[-3,4.5],h:270,lab:1}); P.fn(x=>x-1,{c:'var(--spark)',w:2,dash:true}).fn(Math.log,{c:'var(--math)'}).dot(1,0,{l:'(1 ; 0)'}).text(4.6,3.6,'y = x − 1',{a:'end',c:'var(--spark)',s:12}).text(4.6,1.3,'ln x',{a:'end',c:'var(--math)',s:12}); return P.svg(); })()},
  {h:'Croissances comparées',p:`<p>Beaucoup de limites opposent un logarithme, une puissance et une exponentielle. Qui gagne ? L’encadrement précédent permet de trancher une fois pour toutes.</p>
${THM(`<p><b>lim<sub><i>x</i>→+∞</sub> ${F('ln <i>x</i>','<i>x</i>')} = 0</b>, &nbsp; <b>lim<sub><i>x</i>→+∞</sub> ${F(E('<i>x</i>'),'<i>x</i><sup><i>n</i></sup>')} = +∞</b> pour tout entier <i>n</i>, &nbsp; <b>lim<sub><i>x</i>→0⁺</sub> <i>x</i> ln <i>x</i> = 0</b>, et plus généralement <i>x</i><sup>α</sup>/ln <i>x</i> → +∞ et ${E('<i>x</i>')}/<i>x</i><sup>α</sup> → +∞ pour tout α &gt; 0.</p>`)}
${WHY(`<p><b>Première limite</b> : 0 &lt; ln <i>x</i>/<i>x</i> &lt; 2/√<i>x</i> pour <i>x</i> &gt; 1, et 2/√<i>x</i> → 0 : théorème des gendarmes. <b>Deuxième</b> : pose <i>t</i> = ${E('<i>x</i>')}, alors <i>x</i> = ln <i>t</i> et ${E('<i>x</i>')}/<i>x</i> = <i>t</i>/ln <i>t</i> → +∞ quand <i>t</i> → +∞ (inverse de la première). Pour <i>x</i><sup><i>n</i></sup> : ${E('<i>x</i>')}/<i>x</i><sup><i>n</i></sup> = (${E('<i>x</i>/<i>n</i>')}/(<i>x</i>/<i>n</i>))<sup><i>n</i></sup>/<i>n</i><sup><i>n</i></sup>, et la parenthèse tend vers +∞. <b>Troisième</b> : pose <i>x</i> = 1/<i>t</i> ; alors <i>x</i> ln <i>x</i> = −ln <i>t</i>/<i>t</i> → 0 quand <i>t</i> → +∞.</p>`)}
${IDEA('<p>On retient la <b>hiérarchie des infinis</b> : <b>ln <i>x</i> ≪ <i>x</i><sup>α</sup> ≪ e<sup><i>x</i></sup></b> (α &gt; 0). Chaque étage l’emporte sur le précédent, quel que soit l’exposant : <i>x</i><sup>0,01</sup> finit par dépasser (ln <i>x</i>)¹⁰⁰, et e<sup><i>x</i></sup> finit par dépasser <i>x</i>¹⁰⁰⁰. « Finit par » est le mot clé : au début, la puissance peut gagner largement.</p>')}
${EX('<p>Pour <i>x</i> = 10 : e<sup><i>x</i></sup> ≈ 22 026 et <i>x</i>⁴ = 10 000, l’exponentielle est déjà devant. Pour <i>x</i>¹⁰, il faut attendre <i>x</i> ≈ 35 pour qu’elle passe devant, mais elle passe.</p>')}
<p>Le curseur règle <i>n</i> : la courbe de e<sup><i>x</i></sup>/<i>x</i><sup><i>n</i></sup> commence par descendre, puis remonte toujours vers +∞.</p>`,
   params:[{id:'n',l:'exposant n',min:1,max:6,step:1,v:2}],
   draw:v=>{ const P=plane({x:[0,16],y:[-1,12],h:240,grid:false,lx:4,ly:4}); P.fn(x=>Math.exp(x)/x**v.n,{c:'var(--math)',from:.05,n:400}).seg(0,1,16,1,{c:'var(--muted)',w:1,dash:true}).text(15.8,1,'y = 1',{a:'end',dy:-5,c:'var(--muted)',s:11}); return axes(P,[0,16],[-1,12]).svg(); },
   info:v=>{ const m=Math.exp(v.n)/v.n**v.n; return `<i>n</i> = ${v.n} : e<sup><i>x</i></sup>/<i>x</i><sup>${v.n}</sup> est minimal en <i>x</i> = ${v.n}, où il vaut (e/${v.n})<sup>${v.n}</sup> ≈ ${m<.001?fmt(m,5):fmt(m,3)}. Ensuite il croît vers +∞ : en <i>x</i> = 30, il vaut déjà ≈ ${fmt(Math.exp(30)/30**v.n,0)}.`; }},
  {h:'Deux limites par le taux d’accroissement',p:`<p>Près de 0, (e<sup><i>x</i></sup> − 1)/<i>x</i> et ln(1 + <i>x</i>)/<i>x</i> sont des formes 0/0. Pas besoin d’encadrement : ce sont des taux d’accroissement, et on connaît les dérivées.</p>
${THM(`<p><b>lim<sub><i>x</i>→0</sub> ${F(E('<i>x</i>')+' − 1','<i>x</i>')} = 1</b> &nbsp; et &nbsp; <b>lim<sub><i>x</i>→0</sub> ${F('ln(1 + <i>x</i>)','<i>x</i>')} = 1</b>. Plus généralement, (<i>a</i><sup><i>x</i></sup> − 1)/<i>x</i> → ln <i>a</i>.</p>`)}
${WHY(`<p>(${E('<i>x</i>')} − 1)/<i>x</i> = (exp(<i>x</i>) − exp(0))/(<i>x</i> − 0) est le taux d’accroissement de exp entre 0 et <i>x</i> : sa limite est exp′(0) = e<sup>0</sup> = 1. De même ln(1 + <i>x</i>)/<i>x</i> = (ln(1 + <i>x</i>) − ln 1)/<i>x</i> tend vers la dérivée de <i>t</i> ↦ ln(1 + <i>t</i>) en 0, soit 1/(1 + 0) = 1. Pour <i>a</i><sup><i>x</i></sup> = ${E('<i>x</i> ln <i>a</i>')}, la dérivée en 0 vaut ln <i>a</i>.</p>`)}
${IDEA('<p>Près de 0, e<sup><i>x</i></sup> ≈ 1 + <i>x</i> et ln(1 + <i>x</i>) ≈ <i>x</i> : chaque fonction se confond avec sa tangente. C’est le même fait que l’encadrement e<sup><i>x</i></sup> ≥ 1 + <i>x</i>, vu de près.</p>')}
${EX(`<p>lim<sub><i>x</i>→0</sub> (${E('2<i>x</i>')} − 1)/<i>x</i> : pose <i>h</i> = 2<i>x</i>. Alors (${E('<i>h</i>')} − 1)/(<i>h</i>/2) = 2 · (${E('<i>h</i>')} − 1)/<i>h</i> → 2. Autre conséquence : <i>n</i> ln(1 + 1/<i>n</i>) = ln(1 + 1/<i>n</i>)/(1/<i>n</i>) → 1, donc (1 + 1/<i>n</i>)<sup><i>n</i></sup> = e<sup><i>n</i> ln(1 + 1/<i>n</i>)</sup> → e.</p>`)}
${WARN('<p>Ces limites sont valables <b>en 0</b> seulement. En +∞, (e<sup><i>x</i></sup> − 1)/<i>x</i> tend vers +∞ (croissances comparées) et ln(1 + <i>x</i>)/<i>x</i> tend vers 0.</p>')}`,
   note:'Même raisonnement pour sin x/x → 1 (dérivée de sin en 0) : tout taux d’accroissement d’une fonction dérivable est une limite connue.'},
  {kind:'Méthode',h:'Lever une forme indéterminée avec les croissances comparées',
   p:`<p><b>Quand :</b> une limite en ±∞ mélange exponentielle, puissances et logarithme (formes ∞/∞ ou ∞ − ∞), ou une limite en 0 fait apparaître <i>x</i> ln <i>x</i>, (e<sup><i>x</i></sup> − 1)/<i>x</i>, ln(1 + <i>x</i>)/<i>x</i>. <b>Pourquoi ça marche :</b> le terme dominant impose la limite ; une fois mis en facteur, les autres termes deviennent des quotients de la forme ln <i>x</i>/<i>x</i><sup>α</sup> ou <i>x</i><sup><i>n</i></sup>/e<sup><i>x</i></sup>, qui tendent vers 0. <b>Comment :</b></p><ol><li>repère l’étage le plus haut dans la hiérarchie ln ≪ puissances ≪ exp ;</li><li>mets ce terme en facteur, au numérateur et au dénominateur ;</li><li>chaque quotient restant tend vers 0 par croissances comparées ;</li><li>en 0 ou en un point fini, change de variable (<i>h</i> = <i>x</i> − <i>a</i>, <i>t</i> = 1/<i>x</i>…) pour retrouver une limite du cours.</li></ol>`,
   demo:{enonce:`Calcule lim<sub><i>x</i>→+∞</sub> ${F(E('<i>x</i>')+' − <i>x</i>³',E('<i>x</i>')+' + <i>x</i>²')} puis lim<sub><i>x</i>→0⁺</sub> <i>x</i>² ln <i>x</i>.`,
    etapes:[{f:'Au numérateur comme au dénominateur, le terme dominant est e<sup><i>x</i></sup> (étage exponentiel).',w:'Forme ∞ − ∞ en haut, ∞ + ∞ en bas : on ne peut pas conclure directement.'},
     {f:`${F(E('<i>x</i>')+' − <i>x</i>³',E('<i>x</i>')+' + <i>x</i>²')} = ${F('1 − <i>x</i>³/'+E('<i>x</i>'),'1 + <i>x</i>²/'+E('<i>x</i>'))}`,w:'On met e^x en facteur en haut et en bas, puis on simplifie.'},
     {f:`<i>x</i>³/${E('<i>x</i>')} → 0 et <i>x</i>²/${E('<i>x</i>')} → 0, donc la limite vaut ${F(1,1)} = 1.`,w:'Croissances comparées : e^x l’emporte sur toute puissance.'},
     {f:'<i>x</i>² ln <i>x</i> = <i>x</i> · (<i>x</i> ln <i>x</i>) → 0 · 0 = 0 quand <i>x</i> → 0⁺.',w:'On isole la limite connue x ln x → 0 ; le facteur x restant tend aussi vers 0.'}],
    conclusion:'La première limite vaut <b>1</b>, la seconde <b>0</b>. Sans mise en facteur, « ∞ − ∞ » ou « 0 · (−∞) » ne disent rien : c’est la hiérarchie des infinis qui décide.'},
   note:'En +∞, e^x − x³ = e^x (1 − x³/e^x) → +∞ : le même procédé règle les formes ∞ − ∞.'},
  {h:'Une forme 0/0',p:`Calcule lim<sub><i>x</i>→0</sub> ${F(E('3<i>x</i>')+' − 1','ln(1 + 2<i>x</i>)')}.`,lab:'limite =',ans:1.5,tol:.001,
   why:'Divise haut et bas par x : (e^(3x) − 1)/x → 3 (poser h = 3x) et ln(1 + 2x)/x → 2 (poser h = 2x). Le quotient tend vers 3/2.'},
  {h:'Qui tend vers 0 ?',p:'Une seule de ces expressions tend vers 0 quand <i>x</i> → +∞. Laquelle ?',
   opts:['<i>x</i>/ln <i>x</i>',E('<i>x</i>')+'/<i>x</i>¹⁰⁰','<i>x</i>² '+E('−<i>x</i>'),'√<i>x</i> − ln <i>x</i>'],ans:2,
   why:'x² e^(−x) = x²/e^x → 0 : l’exponentielle gagne. x/ln x → +∞, e^x/x¹⁰⁰ → +∞ (même avec l’exposant 100), et √x − ln x = √x (1 − ln x/√x) → +∞.'},
  {h:'En 0⁺, qui gagne ?',p:'Quelle est la limite de <i>x</i><sup><i>x</i></sup> = e<sup><i>x</i> ln <i>x</i></sup> quand <i>x</i> → 0⁺ ?',
   opts:['0','1','+∞','e'],ans:1,
   why:'x ln x → 0 en 0⁺ (le facteur x gagne sur ln x), donc x^x = e^(x ln x) → e⁰ = 1. La courbe de x^x part de la hauteur 1, descend jusqu’à e^(−1/e) ≈ 0,69 en 1/e, puis remonte.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`${KEEP(`<ul><li><b><i>a</i><sup><i>x</i></sup> = ${E('<i>x</i> ln <i>a</i>')}</b> (<i>a</i> &gt; 0) : cohérent avec les racines, (<i>a</i><sup><i>x</i></sup>)′ = ln <i>a</i> · <i>a</i><sup><i>x</i></sup>, croissante si <i>a</i> &gt; 1.</li><li><b>log<sub><i>a</i></sub> <i>x</i> = ln <i>x</i>/ln <i>a</i></b>, réciproque de <i>a</i><sup><i>x</i></sup> ; (log<sub><i>a</i></sub> <i>x</i>)′ = 1/(<i>x</i> ln <i>a</i>).</li><li><b><i>x</i><sup>α</sup> = ${E('α ln <i>x</i>')}</b> (<i>x</i> &gt; 0) : (<i>x</i><sup>α</sup>)′ = α<i>x</i><sup>α−1</sup> pour tout α réel.</li><li><i>u</i><sup><i>v</i></sup> se dérive en passant par ${E('<i>v</i> ln <i>u</i>')} : (<i>x</i><sup><i>x</i></sup>)′ = (ln <i>x</i> + 1)<i>x</i><sup><i>x</i></sup>.</li><li><b>ln <i>x</i> ≤ <i>x</i> − 1</b>, d’où 0 &lt; ln <i>x</i>/<i>x</i> &lt; 2/√<i>x</i> pour <i>x</i> &gt; 1.</li><li>Croissances comparées : ln <i>x</i>/<i>x</i> → 0, e<sup><i>x</i></sup>/<i>x</i><sup><i>n</i></sup> → +∞, <i>x</i> ln <i>x</i> → 0 en 0⁺. Hiérarchie <b>ln ≪ <i>x</i><sup>α</sup> ≪ e<sup><i>x</i></sup></b>.</li><li>En 0 : (e<sup><i>x</i></sup> − 1)/<i>x</i> → 1 et ln(1 + <i>x</i>)/<i>x</i> → 1 (taux d’accroissement).</li><li>Méthode : mettre le terme dominant en facteur, puis utiliser les limites du cours.</li></ul>`)}`,
   note:'Toutes ces limites découlent de deux faits : ln x ≤ x − 1 et la définition des dérivées de exp et ln. Rien à apprendre par cœur si tu sais les retrouver.'},
  {kind:'Problème',h:'Le temps de doublement',
   p:`Une culture de bactéries double de population toutes les 3 heures. En notant <i>N</i>₀ la population initiale, on a donc <i>N</i>(<i>t</i>) = <i>N</i>₀ · 2<sup><i>t</i>/3</sup>, où <i>t</i> est en heures. On veut réécrire ce modèle avec la base e, connaître la vitesse de croissance relative et prévoir le moment où la population est multipliée par 10.`,
   fig:(()=>{ const P=plane({x:[-.5,12],y:[-1,17],h:220,grid:false,lx:3,ly:4}); P.fn(t=>Math.pow(2,t/3),{from:0,c:'var(--math)'}).seg(0,10,12,10,{c:'var(--bad)',w:1,dash:true}).dot(3,2,{r:4,l:'×2',dx:6,dy:14}).dot(6,4,{r:4,l:'×4',dx:6,dy:14}).dot(9,8,{r:4,l:'×8',dx:6,dy:14}).text(11.8,10,'×10',{a:'end',dy:-5,c:'var(--bad)',s:11}); return axes(P,[-.5,12],[-1,17],'t (h)','N/N₀').svg(); })(),
   parts:[
    {q:'a) On écrit <i>N</i>(<i>t</i>) = <i>N</i>₀ e<sup><i>kt</i></sup>. Que vaut <i>k</i> (en h⁻¹, arrondi au millième) ?',lab:'k =',ans:Math.log(2)/3,tol:.001,hint:'2^(t/3) = e^((t/3) ln 2) par définition de la puissance.',why:'2^(t/3) = e^((t ln 2)/3), donc k = ln 2/3 ≈ 0,231 h⁻¹.'},
    {q:'b) La vitesse de croissance relative <i>N</i>′(<i>t</i>)/<i>N</i>(<i>t</i>) vaut…',opts:['<i>t</i>/3, elle augmente avec le temps','ln 2/3 ≈ 0,231 à chaque instant','2<sup><i>t</i>/3</sup> ln 2','3/ln 2'],ans:1,hint:'Dérive N₀ e^(kt) et divise par N(t).',why:'N′(t) = k N₀ e^(kt) = k N(t), donc N′/N = k = ln 2/3 : la croissance relative est constante, c’est la marque d’une exponentielle.'},
    {q:'c) Au bout de combien d’heures la population est-elle multipliée par 10 ? Arrondis au centième.',lab:'t =',unit:'h',ans:3*Math.log(10)/Math.log(2),tol:.01,hint:'Résous 2^(t/3) = 10 en prenant le logarithme, ou utilise log₂ 10.',why:'2^(t/3) = 10 ⇔ t/3 = log₂ 10 = ln 10/ln 2 ≈ 3,322 ⇔ t ≈ 9,97 h.'},
    {q:'d) Combien de doublements correspondent à une multiplication par 1000 ? Arrondis au centième.',lab:'n =',ans:3*Math.log(10)/Math.log(2),tol:.01,hint:'On cherche n tel que 2ⁿ = 1000, c’est-à-dire log₂ 1000.',why:'log₂ 1000 = 3 log₂ 10 ≈ 9,97 doublements, soit environ 29,9 heures. Un facteur 1000 ne coûte que trois fois plus de temps qu’un facteur 10.'},
   ],
   sol:'<p>Par définition de la puissance, 2<sup><i>t</i>/3</sup> = e<sup>(<i>t</i>/3) ln 2</sup>, donc <i>N</i>(<i>t</i>) = <i>N</i>₀e<sup><i>kt</i></sup> avec <i>k</i> = ln 2/3 ≈ 0,231 h⁻¹. En dérivant, <i>N</i>′ = <i>kN</i> : la croissance relative est la constante <i>k</i>, et le temps de doublement <i>T</i> et <i>k</i> sont liés par <i>k</i> = ln 2/<i>T</i>.</p><p>Pour un facteur 10 : 2<sup><i>t</i>/3</sup> = 10 donne <i>t</i> = 3 log₂ 10 = 3 ln 10/ln 2 ≈ 9,97 h. Pour un facteur 1000 = 10³, il faut log₂ 1000 = 3 log₂ 10 ≈ 9,97 doublements, soit environ 29,9 h : les facteurs multiplicatifs s’additionnent en temps, c’est la propriété du logarithme.</p>'},
  {kind:'Problème',h:'La fonction x^(1/x) et le plus grand des n^(1/n)',
   p:`On étudie <i>f</i>(<i>x</i>) = <i>x</i><sup>1/<i>x</i></sup> sur ]0 ; +∞[. Lequel est le plus grand : √2 = 2<sup>1/2</sup>, ∛3 = 3<sup>1/3</sup>, ∜4 = 4<sup>1/4</sup> ? Les racines successives des entiers semblent d’abord grandir, puis diminuer. Pour comprendre, on écrit <i>f</i>(<i>x</i>) = e<sup>ln <i>x</i>/<i>x</i></sup> et on étudie l’exposant <i>g</i>(<i>x</i>) = ln <i>x</i>/<i>x</i>.`,
   fig:(()=>{ const P=plane({x:[-.5,10],y:[-.2,1.7],h:200,grid:false,lx:2,ly:.5}); P.fn(x=>Math.exp(Math.log(x)/x),{from:.02,c:'var(--math)',n:500}).seg(0,1,10,1,{c:'var(--muted)',w:1,dash:true}); for(let n=1;n<=9;n++) P.dot(n,Math.pow(n,1/n),{r:4,c:'var(--spark)'}); P.dot(Math.E,Math.exp(1/Math.E),{r:5,c:'var(--bad)',l:'x = e',dy:-10}); return axes(P,[-.5,10],[-.2,1.7]).svg(); })(),
   parts:[
    {q:'a) Quelle est la limite de <i>f</i> en +∞ ?',opts:['+∞','1','0','e'],ans:1,hint:'Que fait ln x/x en +∞ ?',why:'ln x/x → 0 par croissances comparées, donc f(x) = e^(ln x/x) → e⁰ = 1.'},
    {q:'b) Quelle est la limite de <i>f</i> en 0⁺ ?',opts:['1','+∞','0','e'],ans:2,hint:'En 0⁺, ln x → −∞ et on divise par un x très petit et positif.',why:'ln x/x → −∞ en 0⁺ (numérateur vers −∞, dénominateur vers 0⁺), donc f(x) = e^(ln x/x) → 0.'},
    {q:'c) En quel point <i>f</i> atteint-elle son maximum ? Arrondis au millième.',lab:'x =',ans:Math.E,tol:.002,hint:'Dérive g(x) = ln x/x avec la règle du quotient ; f et g ont les mêmes variations.',why:'g′(x) = (1 − ln x)/x², positive avant e et négative après : g, donc f = e^g, est maximale en x = e. Le maximum vaut e^(1/e) ≈ 1,445.'},
    {q:'d) Parmi les entiers <i>n</i> ≥ 1, lequel rend <i>n</i><sup>1/<i>n</i></sup> maximal ?',lab:'n =',ans:3,hint:'f croît avant e ≈ 2,718 et décroît après : les candidats sont les entiers voisins de e.',why:'f croît sur ]0 ; e] et décroît ensuite, donc le maximum entier est en n = 2 ou n = 3. Or 2^(1/2) ≈ 1,414 et 3^(1/3) ≈ 1,442 : c’est n = 3. Et 4^(1/4) = 2^(1/2) : la racine quatrième de 4 égale la racine carrée de 2.'},
   ],
   sol:'<p><i>f</i>(<i>x</i>) = e<sup><i>g</i>(<i>x</i>)</sup> avec <i>g</i>(<i>x</i>) = ln <i>x</i>/<i>x</i>. En +∞, <i>g</i> → 0 donc <i>f</i> → 1 ; en 0⁺, <i>g</i> → −∞ donc <i>f</i> → 0. La dérivée <i>g</i>′(<i>x</i>) = (1 − ln <i>x</i>)/<i>x</i>² s’annule en <i>x</i> = e, positive avant, négative après : <i>g</i> et <i>f</i> sont maximales en e, avec <i>f</i>(e) = e<sup>1/e</sup> ≈ 1,445.</p><p>Comme <i>f</i> croît puis décroît autour de e ≈ 2,72, le plus grand des <i>n</i><sup>1/<i>n</i></sup> est atteint en <i>n</i> = 2 ou 3 : 3<sup>1/3</sup> ≈ 1,442 l’emporte sur 2<sup>1/2</sup> ≈ 1,414. Ensuite les valeurs décroissent vers 1, et 4<sup>1/4</sup> = (2²)<sup>1/4</sup> = 2<sup>1/2</sup> retombe exactement sur √2.</p>'},
]},
);

COURS.push(
/* ===================== 2. DIFFÉRENTIELLE ET INTÉGRATION PAR PARTIES ===================== */
{subj:'gred',sem:'ana',id:'gred-differentielle-parties',h:'Différentielle et intégration par parties',p:'La différentielle df = f′(x) dx comme variation approchée et notation de Leibniz, puis la formule des parties, lue dans la dérivée d’un produit.',steps:[
  {h:'La variation approchée d’une fonction',p:`<p>Un disque de rayon 10 cm voit son rayon augmenter de 0,1 cm. De combien son aire augmente-t-elle, à peu près ? On peut calculer exactement, mais la dérivée donne une réponse immédiate et une idée plus profonde : près d’un point, une fonction dérivable se comporte comme une fonction affine.</p>
${RAP('<p><i>f</i> est dérivable en <i>x</i> si le taux d’accroissement (<i>f</i>(<i>x</i> + <i>h</i>) − <i>f</i>(<i>x</i>))/<i>h</i> a une limite finie quand <i>h</i> → 0 ; cette limite est <i>f</i>′(<i>x</i>), la pente de la tangente.</p>')}
${PROP('<p>Si <i>f</i> est dérivable en <i>x</i>, alors pour <i>h</i> petit : <b><i>f</i>(<i>x</i> + <i>h</i>) − <i>f</i>(<i>x</i>) ≈ <i>f</i>′(<i>x</i>) · <i>h</i></b>. Plus précisément, <i>f</i>(<i>x</i> + <i>h</i>) − <i>f</i>(<i>x</i>) = <i>f</i>′(<i>x</i>) <i>h</i> + <i>h</i> ε(<i>h</i>) avec ε(<i>h</i>) → 0.</p>')}
${WHY('<p>C’est la définition de la dérivée réécrite : le taux (<i>f</i>(<i>x</i> + <i>h</i>) − <i>f</i>(<i>x</i>))/<i>h</i> vaut <i>f</i>′(<i>x</i>) + ε(<i>h</i>) avec ε(<i>h</i>) → 0. En multipliant par <i>h</i>, l’erreur <i>h</i> ε(<i>h</i>) est <b>négligeable devant <i>h</i></b> : elle tend vers 0 plus vite que <i>h</i>.</p>')}
${IDEA('<p>Remplacer la courbe par sa tangente : la variation réelle Δ<i>f</i> est remplacée par la variation le long de la tangente, <i>f</i>′(<i>x</i>) Δ<i>x</i>. L’erreur est la petite distance verticale entre la courbe et la tangente, qui s’écrase quand on zoome.</p>')}
${EX('<p>Aire du disque <i>A</i>(<i>r</i>) = π<i>r</i>², <i>A</i>′(<i>r</i>) = 2π<i>r</i>. Pour <i>r</i> = 10 et <i>h</i> = 0,1 : Δ<i>A</i> ≈ 2π · 10 · 0,1 = 2π ≈ 6,283 cm². Valeur exacte : π(10,1² − 10²) = π · 2,01 ≈ 6,315 cm². L’erreur est π · 0,01, le terme en <i>h</i>² oublié.</p>')}
<p>Déplace <i>h</i> : la variation le long de la tangente (en couleur) et la variation réelle se confondent quand <i>h</i> devient petit.</p>`,
   params:[{id:'h',l:'h',min:.1,max:1.5,step:.1,v:1}],
   draw:v=>{ const f=x=>x*x/2, x0=1, P=plane({x:[-.3,3],y:[-.5,4.5],h:300,lab:1}); P.fn(f,{c:'var(--math)'}).fn(x=>f(x0)+x0*(x-x0),{c:'var(--muted)',w:1.5,dash:true}).seg(x0,f(x0),x0+v.h,f(x0),{c:'var(--muted)',w:1.5}).seg(x0+v.h,f(x0),x0+v.h,f(x0)+x0*v.h,{c:'var(--spark)',w:4}).seg(x0+v.h,f(x0)+x0*v.h,x0+v.h,f(x0+v.h),{c:'var(--bad)',w:4}).dot(x0,f(x0),{l:'(x ; f(x))',dy:-10}).dot(x0+v.h,f(x0+v.h),{c:'var(--bad)',r:4}); return axes(P,[-.3,3],[-.5,4.5]).svg(); },
   info:v=>`<i>f</i>(<i>x</i>) = <i>x</i>²/2 en <i>x</i> = 1, pente 1. Variation approchée <i>f</i>′(1) <i>h</i> = ${fmt(v.h)} ; variation réelle Δ<i>f</i> = ${fmt(v.h+v.h*v.h/2,3)} ; erreur <i>h</i>²/2 = ${fmt(v.h*v.h/2,3)}.`},
  {h:'La différentielle et la notation de Leibniz',p:`<p>On donne un nom et une écriture à cette variation approchée. L’écriture est ancienne (Leibniz, XVIIᵉ siècle) et reste la plus pratique pour les calculs d’intégrales.</p>
${DEF('<p>Soit <i>f</i> dérivable en <i>x</i>. La <b>différentielle</b> de <i>f</i> en <i>x</i> est l’application linéaire <i>h</i> ↦ <i>f</i>′(<i>x</i>) <i>h</i>. On la note <b>d<i>f</i> = <i>f</i>′(<i>x</i>) d<i>x</i></b>, où d<i>x</i> désigne l’accroissement <i>h</i> de la variable.</p>')}
${IDEA('<p>d<i>x</i> est une variable ordinaire (l’accroissement qu’on donne à <i>x</i>), et d<i>f</i> est la partie linéaire de la variation correspondante. La dérivée apparaît alors comme un vrai quotient : <b><i>f</i>′(<i>x</i>) = d<i>f</i>/d<i>x</i></b>. Pour <i>y</i> = <i>x</i>², on écrit d<i>y</i> = 2<i>x</i> d<i>x</i> ; pour <i>y</i> = sin <i>x</i>, d<i>y</i> = cos <i>x</i> d<i>x</i>.</p>')}
${PROP('<p><b>Différentielle d’une composée.</b> Si <i>y</i> = <i>f</i>(<i>u</i>) et <i>u</i> = <i>g</i>(<i>x</i>), alors d<i>y</i> = <i>f</i>′(<i>u</i>) d<i>u</i> et d<i>u</i> = <i>g</i>′(<i>x</i>) d<i>x</i>, donc <b>d<i>y</i> = <i>f</i>′(<i>g</i>(<i>x</i>)) <i>g</i>′(<i>x</i>) d<i>x</i></b>. En notation de Leibniz : d<i>y</i>/d<i>x</i> = (d<i>y</i>/d<i>u</i>) · (d<i>u</i>/d<i>x</i>).</p>')}
${WHY('<p>C’est la règle de dérivation des composées, (<i>f</i>∘<i>g</i>)′ = <i>f</i>′(<i>g</i>) · <i>g</i>′, écrite avec des différentielles. L’intérêt : la formule d<i>y</i> = <i>f</i>′(<i>u</i>) d<i>u</i> garde la <b>même forme</b> que <i>u</i> soit la variable elle-même ou une fonction d’une autre variable. On dit que la différentielle est invariante par changement de variable.</p>')}
${EX('<p><i>y</i> = sin(<i>x</i>²). Pose <i>u</i> = <i>x</i>² : d<i>u</i> = 2<i>x</i> d<i>x</i> et d<i>y</i> = cos <i>u</i> d<i>u</i> = cos(<i>x</i>²) · 2<i>x</i> d<i>x</i>. Donc <i>y</i>′ = 2<i>x</i> cos(<i>x</i>²). Dans ce calcul, « d<i>u</i> » a servi de pivot : on l’a remplacé par son expression en d<i>x</i>.</p>')}
${WARN('<p>d<i>x</i> n’est pas un « nombre infiniment petit » : c’est une variable réelle quelconque. Les manipulations comme « simplifier les d<i>u</i> » dans (d<i>y</i>/d<i>u</i>)(d<i>u</i>/d<i>x</i>) sont justes parce qu’elles traduisent la règle de la composée, pas parce que d<i>u</i> serait une quantité qu’on divise.</p>')}`,
   note:'On lit « d f » ou « différentielle de f ». Dans ∫ f(x) dx, le dx rappelle la variable d’intégration : c’est la même notation, et elle n’est pas décorative, comme le montre le changement de variable.'},
  {kind:'Méthode',h:'Estimer une erreur avec la différentielle',
   p:`<p><b>Quand :</b> une grandeur <i>y</i> = <i>f</i>(<i>x</i>) est calculée à partir d’une mesure <i>x</i> connue à ±Δ<i>x</i> près, et on veut l’incertitude sur <i>y</i>. <b>Pourquoi ça marche :</b> pour une petite erreur, Δ<i>y</i> ≈ <i>f</i>′(<i>x</i>) Δ<i>x</i> : la différentielle transporte l’erreur, et la dérivée joue le rôle de facteur d’amplification. <b>Comment :</b></p><ol><li>écris la formule <i>y</i> = <i>f</i>(<i>x</i>) et calcule <i>f</i>′(<i>x</i>) ;</li><li>erreur absolue : |Δ<i>y</i>| ≈ |<i>f</i>′(<i>x</i>)| Δ<i>x</i> ;</li><li>erreur relative : Δ<i>y</i>/<i>y</i> ≈ <i>f</i>′(<i>x</i>) Δ<i>x</i>/<i>f</i>(<i>x</i>). Pour une puissance <i>y</i> = <i>c</i> <i>x</i><sup><i>n</i></sup>, elle vaut <i>n</i> · Δ<i>x</i>/<i>x</i> : l’exposant multiplie l’erreur relative.</li></ol>`,
   demo:{enonce:'On mesure le rayon d’une boule : <i>r</i> = 10 cm à ±0,1 cm près. Quelle incertitude sur le volume <i>V</i> = (4/3)π<i>r</i>³ ?',
    etapes:[{f:'<i>V</i>′(<i>r</i>) = 4π<i>r</i>², donc d<i>V</i> = 4π<i>r</i>² d<i>r</i>.',w:'La dérivée du volume est l’aire de la sphère : une pelure d’épaisseur dr a pour volume aire × épaisseur.'},
     {f:'Δ<i>V</i> ≈ 4π · 100 · 0,1 = 40π ≈ 125,7 cm³.',w:'On remplace r par 10 et dr par 0,1.'},
     {f:`Δ<i>V</i>/<i>V</i> ≈ ${F('4π<i>r</i>² Δ<i>r</i>','(4/3)π<i>r</i>³')} = 3 · ${F('Δ<i>r</i>','<i>r</i>')} = 3 · 1 % = 3 %.`,w:'Le cube triple l’erreur relative : 1 % sur le rayon, 3 % sur le volume.'},
     {f:'Contrôle : <i>V</i>(10,1) − <i>V</i>(10) ≈ 4315,7 − 4188,8 ≈ 126,9 cm³.',w:'L’écart avec 125,7 vient des termes en dr² et dr³ négligés : environ 1 %.'}],
    conclusion:'<i>V</i> ≈ 4189 ± 126 cm³, soit une incertitude relative de 3 %. La différentielle donne l’ordre de grandeur de l’erreur sans recalculer la fonction.'},
   note:'Si plusieurs mesures interviennent, on ajoute les contributions : pour y = x·z, dy/y = dx/x + dz/z.'},
  {h:'L’arête d’un cube',p:'L’arête d’un cube mesure 5 cm à ±0,02 cm près. Quelle incertitude (en cm³) la différentielle donne-t-elle sur le volume <i>V</i> = <i>a</i>³ ?',lab:'ΔV ≈',unit:'cm³',ans:1.5,tol:.01,
   why:'dV = 3a² da = 3 · 25 · 0,02 = 1,5 cm³. En relatif : 3 · 0,02/5 = 1,2 %.'},
  {h:'Une différentielle composée',p:'Quelle est la différentielle de <i>y</i> = ln(1 + <i>x</i>²) ?',
   opts:['d<i>y</i> = '+F(1,'1 + <i>x</i>²')+' d<i>x</i>','d<i>y</i> = '+F('2<i>x</i>','1 + <i>x</i>²')+' d<i>x</i>','d<i>y</i> = 2<i>x</i> ln(1 + <i>x</i>²) d<i>x</i>','d<i>y</i> = '+F(1,'2<i>x</i>')+' d<i>x</i>'],ans:1,
   why:'Pose u = 1 + x² : du = 2x dx et dy = du/u = 2x dx/(1 + x²).'},
  {h:'Jusqu’où l’approximation tient-elle ?',p:'Pour <i>f</i>(<i>x</i>) = e<sup><i>x</i></sup> en <i>x</i> = 0, la variation approchée vaut <i>f</i>′(0) <i>h</i> = <i>h</i>, alors que la variation réelle est e<sup><i>h</i></sup> − 1. Règle <i>h</i> pour que l’erreur commise soit inférieure à 0,015.',
   params:[{id:'h',l:'h',min:.05,max:.6,step:.05,v:.5}],
   draw:v=>{ const P=plane({x:[-.2,.8],y:[-.2,1.4],h:260,grid:false,lx:.2,ly:.2}); P.fn(x=>Math.exp(x)-1,{c:'var(--math)'}).fn(x=>x,{c:'var(--muted)',w:1.5,dash:true}).seg(v.h,v.h,v.h,Math.exp(v.h)-1,{c:'var(--bad)',w:4}).dot(v.h,Math.exp(v.h)-1,{c:'var(--bad)',r:4}).text(.78,.78,'y = h',{a:'end',dy:-5,c:'var(--muted)',s:11}).text(.4,1.2,'y = eʰ − 1',{c:'var(--math)',s:12}); return axes(P,[-.2,.8],[-.2,1.4],'h','').svg(); },
   info:v=>`<i>h</i> = ${fmt(v.h)} : variation réelle e<sup><i>h</i></sup> − 1 ≈ ${fmt(Math.exp(v.h)-1,4)}, approchée ${fmt(v.h)}, erreur ≈ ${fmt(Math.exp(v.h)-1-v.h,4)}.`,
   ok:v=>Math.exp(v.h)-1-v.h<.015,
   why:'L’erreur vaut e^h − 1 − h ≈ h²/2. Elle est inférieure à 0,015 pour h ≤ 0,15 (h = 0,15 donne 0,0118 ; h = 0,2 donne déjà 0,0214). L’erreur est du second ordre : diviser h par 2 la divise par 4.'},
  {h:'L’intégration par parties : d’où vient la formule',p:`<p>On sait primitiver <i>x</i> et e<sup><i>x</i></sup>, mais pas leur produit <i>x</i>e<sup><i>x</i></sup> : il n’existe aucune règle « primitive d’un produit ». Pourtant on connaît la dérivée d’un produit, et il suffit de la lire à l’envers.</p>
${THM('<p>Si <i>u</i> et <i>v</i> sont dérivables, de dérivées continues, sur un intervalle contenant <i>a</i> et <i>b</i> : <b>∫ <i>u</i>(<i>x</i>) <i>v</i>′(<i>x</i>) d<i>x</i> = <i>u</i>(<i>x</i>) <i>v</i>(<i>x</i>) − ∫ <i>u</i>′(<i>x</i>) <i>v</i>(<i>x</i>) d<i>x</i></b>, et pour une intégrale définie : <b>∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>u</i> <i>v</i>′ d<i>x</i> = [<i>u</i> <i>v</i>]<sub><i>a</i></sub><sup><i>b</i></sup> − ∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>u</i>′ <i>v</i> d<i>x</i></b>.</p>')}
${WHY('<p>(<i>uv</i>)′ = <i>u</i>′<i>v</i> + <i>uv</i>′, donc <i>uv</i>′ = (<i>uv</i>)′ − <i>u</i>′<i>v</i>. On intègre : la primitive de (<i>uv</i>)′ est <i>uv</i>, et il reste ∫ <i>uv</i>′ = <i>uv</i> − ∫ <i>u</i>′<i>v</i>. Pour l’intégrale définie, le théorème fondamental donne ∫<sub><i>a</i></sub><sup><i>b</i></sup> (<i>uv</i>)′ = <i>u</i>(<i>b</i>)<i>v</i>(<i>b</i>) − <i>u</i>(<i>a</i>)<i>v</i>(<i>a</i>), qu’on note [<i>uv</i>]<sub><i>a</i></sub><sup><i>b</i></sup>.</p>')}
${IDEA('<p>On échange une intégrale contre une autre : la dérivée passe de <i>v</i> à <i>u</i>. Le pari est que ∫ <i>u</i>′<i>v</i> soit plus simple que ∫ <i>uv</i>′, par exemple parce que <i>u</i>′ est plus simple que <i>u</i>. En différentielles, la formule se lit <b>∫ <i>u</i> d<i>v</i> = <i>uv</i> − ∫ <i>v</i> d<i>u</i></b>.</p>')}
${EX('<p>∫ <i>x</i>e<sup><i>x</i></sup> d<i>x</i> avec <i>u</i> = <i>x</i>, <i>v</i>′ = e<sup><i>x</i></sup> : <i>u</i>′ = 1, <i>v</i> = e<sup><i>x</i></sup>. Donc ∫ <i>x</i>e<sup><i>x</i></sup> d<i>x</i> = <i>x</i>e<sup><i>x</i></sup> − ∫ e<sup><i>x</i></sup> d<i>x</i> = <i>x</i>e<sup><i>x</i></sup> − e<sup><i>x</i></sup> + <i>C</i> = (<i>x</i> − 1)e<sup><i>x</i></sup> + <i>C</i>. Contrôle : ((<i>x</i> − 1)e<sup><i>x</i></sup>)′ = e<sup><i>x</i></sup> + (<i>x</i> − 1)e<sup><i>x</i></sup> = <i>x</i>e<sup><i>x</i></sup>.</p>')}
${WARN('<p>Il n’y a qu’un seul + <i>C</i> à la fin, et pas de constante à ajouter dans <i>v</i> : n’importe quelle primitive <i>v</i> convient, le résultat ne change pas (la constante se simplifie entre <i>uv</i> et ∫ <i>u</i>′<i>v</i>).</p>')}`,
   note:'Le nom vient de l’écriture ∫ u dv : on intègre « par parties », une partie u qu’on dérive, une partie dv qu’on intègre.'},
  {kind:'Méthode',h:'Choisir u et v′ dans une intégration par parties',
   p:`<p><b>Quand :</b> on intègre un produit de deux fonctions de natures différentes (polynôme × exponentielle, polynôme × sinus ou cosinus, polynôme × logarithme), et aucune substitution évidente ne s’applique. <b>Pourquoi ça marche :</b> la formule remplace ∫ <i>uv</i>′ par ∫ <i>u</i>′<i>v</i>. Elle est utile si <i>u</i>′ est plus simple que <i>u</i>, et si <i>v</i>′ se primitive sans difficulté. <b>Comment :</b></p><ol><li><b>repère classique</b> : prends pour <i>u</i>, par ordre de préférence, le logarithme, puis le polynôme, puis l’exponentielle ou la fonction trigonométrique. Le logarithme s’intègre mal mais se dérive bien ; le polynôme perd un degré à chaque dérivation ; exp, sin, cos se primitivent sans changer de nature ;</li><li>écris le tableau <i>u</i>, <i>u</i>′, <i>v</i>′, <i>v</i> ;</li><li>applique la formule, calcule la nouvelle intégrale, vérifie en dérivant.</li></ol>`,
   demo:{enonce:'Calcule ∫ <i>x</i> sin <i>x</i> d<i>x</i>.',
    etapes:[{f:'<i>u</i> = <i>x</i>, <i>v</i>′ = sin <i>x</i> ; donc <i>u</i>′ = 1 et <i>v</i> = −cos <i>x</i>.',w:'Polynôme avant fonction trigonométrique : x se simplifie en dérivant, sin x se primitive sans peine.'},
     {f:'∫ <i>x</i> sin <i>x</i> d<i>x</i> = <i>x</i> · (−cos <i>x</i>) − ∫ 1 · (−cos <i>x</i>) d<i>x</i>',w:'Formule ∫ uv′ = uv − ∫ u′v. Attention aux deux signes moins.'},
     {f:'= −<i>x</i> cos <i>x</i> + ∫ cos <i>x</i> d<i>x</i> = −<i>x</i> cos <i>x</i> + sin <i>x</i> + <i>C</i>.',w:'La nouvelle intégrale est immédiate.'},
     {f:'Contrôle : (−<i>x</i> cos <i>x</i> + sin <i>x</i>)′ = −cos <i>x</i> + <i>x</i> sin <i>x</i> + cos <i>x</i> = <i>x</i> sin <i>x</i>.',w:'On redérive : les cos x se compensent.'},
     {f:'Mauvais choix : <i>u</i> = sin <i>x</i>, <i>v</i>′ = <i>x</i> donnerait (<i>x</i>²/2) sin <i>x</i> − ∫ (<i>x</i>²/2) cos <i>x</i> d<i>x</i>.',w:'Le degré du polynôme a augmenté : l’intégrale est plus difficile qu’au départ.'}],
    conclusion:'∫ <i>x</i> sin <i>x</i> d<i>x</i> = −<i>x</i> cos <i>x</i> + sin <i>x</i> + <i>C</i>. Le bon choix fait baisser le degré du polynôme ; le mauvais le fait monter.'},
   note:'Pour une intégrale définie, remplace uv par [uv] entre les bornes : ∫₀^π x sin x dx = [−x cos x]₀^π + [sin x]₀^π = π.'},
  {h:'Polynôme × exponentielle',p:'Calcule ∫₀¹ <i>x</i> e<sup>2<i>x</i></sup> d<i>x</i>, arrondi au millième.',lab:'I =',ans:(Math.exp(2)+1)/4,tol:.002,
   why:'u = x, v′ = e^(2x), v = e^(2x)/2. I = [x e^(2x)/2]₀¹ − ∫₀¹ e^(2x)/2 dx = e²/2 − [e^(2x)/4]₀¹ = e²/2 − (e² − 1)/4 = (e² + 1)/4 ≈ 2,097.'},
  {kind:'Méthode',h:'Une seule fonction : le facteur 1 caché',
   p:`<p><b>Quand :</b> on doit primitiver une fonction seule qu’on sait dériver mais pas intégrer : ln <i>x</i>, et plus tard arctan <i>x</i>, arcsin <i>x</i>. <b>Pourquoi ça marche :</b> on écrit ln <i>x</i> = 1 · ln <i>x</i>, produit de <i>v</i>′ = 1 (dont la primitive est <i>v</i> = <i>x</i>) par <i>u</i> = ln <i>x</i> (dont la dérivée 1/<i>x</i> est simple). La formule des parties transforme alors ∫ ln <i>x</i> en ∫ <i>x</i> · 1/<i>x</i> = ∫ 1, qui est triviale. <b>Comment :</b></p><ol><li>pose <i>u</i> = la fonction, <i>v</i>′ = 1, donc <i>v</i> = <i>x</i> ;</li><li>∫ <i>u</i> d<i>x</i> = <i>x</i> <i>u</i>(<i>x</i>) − ∫ <i>x</i> <i>u</i>′(<i>x</i>) d<i>x</i> ;</li><li>la nouvelle intégrale est souvent une fonction rationnelle simple.</li></ol>`,
   demo:{enonce:'Calcule ∫ ln <i>x</i> d<i>x</i>, puis ∫₁<sup>e</sup> ln <i>x</i> d<i>x</i>.',
    etapes:[{f:'<i>u</i> = ln <i>x</i>, <i>v</i>′ = 1 ; <i>u</i>′ = 1/<i>x</i>, <i>v</i> = <i>x</i>.',w:'Le facteur 1 devient v′ : c’est l’astuce.'},
     {f:'∫ ln <i>x</i> d<i>x</i> = <i>x</i> ln <i>x</i> − ∫ <i>x</i> · (1/<i>x</i>) d<i>x</i> = <i>x</i> ln <i>x</i> − ∫ 1 d<i>x</i>',w:'Les x se simplifient dans la nouvelle intégrale.'},
     {f:'= <i>x</i> ln <i>x</i> − <i>x</i> + <i>C</i>.',w:'Contrôle : (x ln x − x)′ = ln x + 1 − 1 = ln x.'},
     {f:'∫₁<sup>e</sup> ln <i>x</i> d<i>x</i> = [<i>x</i> ln <i>x</i> − <i>x</i>]₁<sup>e</sup> = (e · 1 − e) − (0 − 1) = 1.',w:'ln e = 1 et ln 1 = 0.'}],
    conclusion:'∫ ln <i>x</i> d<i>x</i> = <i>x</i> ln <i>x</i> − <i>x</i> + <i>C</i>, et l’aire sous ln entre 1 et e vaut exactement 1.'},
   note:'Même recette pour ∫ (ln x)² dx : u = (ln x)², v′ = 1, et on retombe sur ∫ 2 ln x dx qu’on vient de calculer.'},
  {h:'Aire sous le logarithme',p:'Calcule ∫₁⁴ ln <i>x</i> d<i>x</i>, arrondi au millième.',lab:'I =',ans:4*Math.log(4)-3,tol:.002,
   why:'[x ln x − x]₁⁴ = (4 ln 4 − 4) − (0 − 1) = 4 ln 4 − 3 = 8 ln 2 − 3 ≈ 2,545.'},
  {kind:'Méthode',h:'Deux intégrations par parties de suite',
   p:`<p><b>Quand :</b> le polynôme est de degré 2 ou plus : <i>x</i>² e<sup><i>x</i></sup>, <i>x</i>² cos <i>x</i>, <i>x</i>³ e<sup>−<i>x</i></sup>. <b>Pourquoi ça marche :</b> chaque intégration par parties, avec <i>u</i> = le polynôme, fait baisser son degré de 1. Au bout de <i>n</i> étapes, il ne reste qu’une exponentielle ou une fonction trigonométrique seule. <b>Comment :</b></p><ol><li>première intégration par parties avec <i>u</i> = polynôme ;</li><li>la nouvelle intégrale a un polynôme de degré inférieur : recommence avec le même type de choix ;</li><li>garde les signes et les facteurs : écris chaque étape sur sa ligne ;</li><li>regroupe et vérifie en dérivant.</li></ol>`,
   demo:{enonce:'Calcule ∫ <i>x</i>² e<sup><i>x</i></sup> d<i>x</i>.',
    etapes:[{f:'<i>u</i> = <i>x</i>², <i>v</i>′ = e<sup><i>x</i></sup> : ∫ <i>x</i>² e<sup><i>x</i></sup> d<i>x</i> = <i>x</i>² e<sup><i>x</i></sup> − ∫ 2<i>x</i> e<sup><i>x</i></sup> d<i>x</i>.',w:'Première étape : le degré passe de 2 à 1.'},
     {f:'∫ 2<i>x</i> e<sup><i>x</i></sup> d<i>x</i> = 2(<i>x</i>e<sup><i>x</i></sup> − ∫ e<sup><i>x</i></sup> d<i>x</i>) = 2(<i>x</i> − 1)e<sup><i>x</i></sup>.',w:'Deuxième étape avec u = 2x, v′ = e^x : c’est l’exemple du cours.'},
     {f:'∫ <i>x</i>² e<sup><i>x</i></sup> d<i>x</i> = <i>x</i>² e<sup><i>x</i></sup> − 2(<i>x</i> − 1)e<sup><i>x</i></sup> + <i>C</i> = (<i>x</i>² − 2<i>x</i> + 2)e<sup><i>x</i></sup> + <i>C</i>.',w:'On regroupe en mettant e^x en facteur.'},
     {f:'Contrôle : ((<i>x</i>² − 2<i>x</i> + 2)e<sup><i>x</i></sup>)′ = (2<i>x</i> − 2)e<sup><i>x</i></sup> + (<i>x</i>² − 2<i>x</i> + 2)e<sup><i>x</i></sup> = <i>x</i>² e<sup><i>x</i></sup>.',w:'La vérification est rapide et évite les erreurs de signe.'}],
    conclusion:'∫ <i>x</i>² e<sup><i>x</i></sup> d<i>x</i> = (<i>x</i>² − 2<i>x</i> + 2)e<sup><i>x</i></sup> + <i>C</i>. Pour <i>x</i><sup><i>n</i></sup> e<sup><i>x</i></sup>, il faudrait <i>n</i> étapes.'},
   note:'Avec sin ou cos, les signes alternent : surveille-les. ∫ x² cos x dx = x² sin x + 2x cos x − 2 sin x + C.'},
  {h:'Degré 2 et cosinus',p:'Calcule ∫₀<sup>π</sup> <i>x</i>² cos <i>x</i> d<i>x</i>, arrondi au millième.',lab:'I =',ans:-2*Math.PI,tol:.002,
   why:'Une primitive est x² sin x + 2x cos x − 2 sin x. En π : 0 + 2π(−1) − 0 = −2π ; en 0 : 0. Donc I = −2π ≈ −6,283.'},
  {kind:'Méthode',h:'Le retour à l’intégrale de départ',
   p:`<p><b>Quand :</b> le produit mêle exponentielle et sinus ou cosinus (e<sup><i>x</i></sup> sin <i>x</i>, e<sup>−<i>x</i></sup> cos 2<i>x</i>) : aucun des deux facteurs ne se simplifie en dérivant. <b>Pourquoi ça marche :</b> après <b>deux</b> intégrations par parties, sin redevient −sin et l’exponentielle est inchangée : on retrouve l’intégrale de départ <i>I</i>, avec un coefficient. On obtient une <b>équation</b> en <i>I</i>, qu’on résout. <b>Comment :</b></p><ol><li>nomme l’intégrale <i>I</i> ;</li><li>fais deux intégrations par parties de suite, <b>en dérivant toujours le même type de facteur</b> (deux fois la fonction trigonométrique, ou deux fois l’exponentielle) ;</li><li>reconnais <i>I</i> dans le résultat, écris <i>I</i> = (termes) − <i>k</i> <i>I</i> et isole <i>I</i>.</li></ol>`,
   demo:{enonce:'Calcule <i>I</i> = ∫ e<sup><i>x</i></sup> sin <i>x</i> d<i>x</i>.',
    etapes:[{f:'<i>u</i> = sin <i>x</i>, <i>v</i>′ = e<sup><i>x</i></sup> : <i>I</i> = e<sup><i>x</i></sup> sin <i>x</i> − ∫ e<sup><i>x</i></sup> cos <i>x</i> d<i>x</i>.',w:'On dérive la fonction trigonométrique et on primitive l’exponentielle.'},
     {f:'<i>u</i> = cos <i>x</i>, <i>v</i>′ = e<sup><i>x</i></sup> : ∫ e<sup><i>x</i></sup> cos <i>x</i> d<i>x</i> = e<sup><i>x</i></sup> cos <i>x</i> + ∫ e<sup><i>x</i></sup> sin <i>x</i> d<i>x</i> = e<sup><i>x</i></sup> cos <i>x</i> + <i>I</i>.',w:'Même type de choix. L’intégrale de départ réapparaît.'},
     {f:'<i>I</i> = e<sup><i>x</i></sup> sin <i>x</i> − e<sup><i>x</i></sup> cos <i>x</i> − <i>I</i>, donc 2<i>I</i> = e<sup><i>x</i></sup>(sin <i>x</i> − cos <i>x</i>).',w:'On remplace, puis on fait passer I à gauche.'},
     {f:`<i>I</i> = ${F('e<sup><i>x</i></sup>(sin <i>x</i> − cos <i>x</i>)',2)} + <i>C</i>.`,w:'Contrôle : la dérivée de e^x(sin x − cos x)/2 est e^x(sin x − cos x + cos x + sin x)/2 = e^x sin x.'}],
    conclusion:'∫ e<sup><i>x</i></sup> sin <i>x</i> d<i>x</i> = e<sup><i>x</i></sup>(sin <i>x</i> − cos <i>x</i>)/2 + <i>C</i>. Si on avait changé de type de choix à la deuxième étape, on aurait obtenu <i>I</i> = <i>I</i> : vrai, mais inutile.'},
   note:'Même procédé : ∫ e^x cos x dx = e^x(sin x + cos x)/2 + C.'},
  {h:'Exponentielle et sinus',p:'Calcule ∫₀<sup>π</sup> e<sup><i>x</i></sup> sin <i>x</i> d<i>x</i>, arrondi au centième.',lab:'I =',ans:(Math.exp(Math.PI)+1)/2,tol:.01,
   why:'[e^x(sin x − cos x)/2]₀^π = e^π(0 + 1)/2 − (0 − 1)/2 = (e^π + 1)/2 ≈ 12,07.'},
  {h:'Le bon choix',p:'Pour calculer ∫ <i>x</i>³ ln <i>x</i> d<i>x</i> par parties, quel choix est le bon ?',
   opts:['<i>u</i> = <i>x</i>³, <i>v</i>′ = ln <i>x</i>','<i>u</i> = ln <i>x</i>, <i>v</i>′ = <i>x</i>³','<i>u</i> = <i>x</i>³ ln <i>x</i>, <i>v</i>′ = 1','Impossible : il faut une substitution'],ans:1,
   why:'Le logarithme passe avant le polynôme : u = ln x (u′ = 1/x), v′ = x³ (v = x⁴/4). On obtient (x⁴/4) ln x − ∫ x³/4 dx = (x⁴/4) ln x − x⁴/16 + C. Prendre v′ = ln x demanderait d’abord de savoir primitiver ln x, et u = x³ ln x ne simplifie rien.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`${KEEP('<ul><li><b>Variation approchée</b> : <i>f</i>(<i>x</i> + <i>h</i>) − <i>f</i>(<i>x</i>) ≈ <i>f</i>′(<i>x</i>) <i>h</i>, erreur négligeable devant <i>h</i>.</li><li><b>Différentielle</b> : d<i>f</i> = <i>f</i>′(<i>x</i>) d<i>x</i>, d’où <i>f</i>′ = d<i>f</i>/d<i>x</i> ; composée : d<i>y</i> = <i>f</i>′(<i>u</i>) d<i>u</i>, d<i>u</i> = <i>g</i>′(<i>x</i>) d<i>x</i>.</li><li><b>Erreur</b> : Δ<i>y</i> ≈ |<i>f</i>′(<i>x</i>)| Δ<i>x</i> ; pour <i>y</i> = <i>c</i><i>x</i><sup><i>n</i></sup>, erreur relative multipliée par <i>n</i>.</li><li><b>Parties</b> : ∫ <i>u</i> <i>v</i>′ = <i>uv</i> − ∫ <i>u</i>′ <i>v</i>, ou [<i>uv</i>]<sub><i>a</i></sub><sup><i>b</i></sup> − ∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>u</i>′<i>v</i> ; vient de (<i>uv</i>)′ = <i>u</i>′<i>v</i> + <i>uv</i>′.</li><li><b>Choix de <i>u</i></b> : logarithme, puis polynôme, puis exp ou trigo. Une fonction seule : <i>v</i>′ = 1.</li><li>Polynôme de degré <i>n</i> : <i>n</i> intégrations de suite. e<sup><i>x</i></sup> × sin ou cos : deux étapes puis équation en <i>I</i>.</li><li>Résultats à connaître : ∫ <i>x</i>e<sup><i>x</i></sup> = (<i>x</i> − 1)e<sup><i>x</i></sup>, ∫ ln <i>x</i> = <i>x</i> ln <i>x</i> − <i>x</i>, ∫ <i>x</i> sin <i>x</i> = −<i>x</i> cos <i>x</i> + sin <i>x</i>.</li><li>Toujours vérifier en dérivant.</li></ul>')}`,
   note:'La formule des parties n’est jamais obligatoire : elle est un pari sur une intégrale plus simple. Si la nouvelle intégrale est pire, change de choix.'},
  {kind:'Problème',h:'La concentration d’un médicament',
   p:`Après une injection, la concentration d’un médicament dans le sang (en mg/L) suit <i>c</i>(<i>t</i>) = 2<i>t</i> e<sup>−<i>t</i>/2</sup>, où <i>t</i> est en heures. La concentration monte d’abord, puis le médicament est éliminé. L’« exposition totale » sur une durée <i>T</i> est l’aire ∫₀<sup><i>T</i></sup> <i>c</i>(<i>t</i>) d<i>t</i>. On cherche le pic de concentration, l’exposition sur les 6 premières heures, puis l’exposition totale quand <i>T</i> devient très grand.`,
   fig:(()=>{ const f=t=>2*t*Math.exp(-t/2), P=plane({x:[-.5,12],y:[-.2,1.8],h:200,grid:false,lx:2,ly:.5}); P.area(f,0,6,{fill:'var(--accent)',fo:.25}).fn(f,{from:0,c:'var(--math)'}).dot(2,f(2),{l:'pic',dy:-10}); return axes(P,[-.5,12],[-.2,1.8],'t (h)','c').svg(); })(),
   parts:[
    {q:'a) À quel instant la concentration est-elle maximale ?',lab:'t =',unit:'h',ans:2,hint:'Dérive 2t e^(−t/2) avec la règle du produit et cherche où c′ s’annule.',why:'c′(t) = 2e^(−t/2) − t e^(−t/2) = (2 − t)e^(−t/2), nulle en t = 2, positive avant, négative après.'},
    {q:'b) Quelle est la concentration maximale ? Arrondis au millième.',lab:'c(2) =',unit:'mg/L',ans:4/Math.E,tol:.002,hint:'Remplace t par 2.',why:'c(2) = 4e^(−1) = 4/e ≈ 1,472 mg/L.'},
    {q:'c) Pour calculer ∫ 2<i>t</i> e<sup>−<i>t</i>/2</sup> d<i>t</i> par parties, on choisit…',opts:['<i>u</i> = e<sup>−<i>t</i>/2</sup>, <i>v</i>′ = 2<i>t</i>','<i>u</i> = 2<i>t</i>, <i>v</i>′ = e<sup>−<i>t</i>/2</sup>, donc <i>v</i> = −2e<sup>−<i>t</i>/2</sup>','<i>u</i> = 2<i>t</i>, <i>v</i>′ = e<sup>−<i>t</i>/2</sup>, donc <i>v</i> = e<sup>−<i>t</i>/2</sup>/2','<i>u</i> = 2<i>t</i> e<sup>−<i>t</i>/2</sup>, <i>v</i>′ = 1'],ans:1,hint:'Polynôme avant exponentielle, et (e^(at))′ = a e^(at) : il faut diviser par a = −1/2.',why:'u = 2t se simplifie en dérivant. La primitive de e^(−t/2) est e^(−t/2)/(−1/2) = −2e^(−t/2).'},
    {q:'d) Quelle est l’exposition sur les 6 premières heures, ∫₀⁶ <i>c</i>(<i>t</i>) d<i>t</i> ? Arrondis au centième.',lab:'I =',ans:8-32*Math.exp(-3),tol:.01,hint:'∫ 2t e^(−t/2) dt = −4t e^(−t/2) − 8e^(−t/2) + C. Évalue entre 0 et 6.',why:'[−4t e^(−t/2) − 8e^(−t/2)]₀⁶ = (−24 − 8)e^(−3) − (−8) = 8 − 32e^(−3) ≈ 6,41.'},
    {q:'e) Quand <i>T</i> → +∞, l’exposition totale ∫₀<sup><i>T</i></sup> <i>c</i>(<i>t</i>) d<i>t</i> tend vers…',lab:'limite =',ans:8,hint:'L’intégrale vaut 8 − (4T + 8)e^(−T/2). Que fait T e^(−T/2) en +∞ ?',why:'(4T + 8)e^(−T/2) → 0 par croissances comparées (l’exponentielle gagne sur le polynôme). L’exposition totale tend vers 8 mg·h/L.'},
   ],
   sol:'<p><i>c</i>′(<i>t</i>) = (2 − <i>t</i>)e<sup>−<i>t</i>/2</sup> : la concentration croît jusqu’à <i>t</i> = 2 h, où elle vaut 4/e ≈ 1,47 mg/L, puis décroît vers 0.</p><p>Par parties avec <i>u</i> = 2<i>t</i>, <i>v</i>′ = e<sup>−<i>t</i>/2</sup>, <i>v</i> = −2e<sup>−<i>t</i>/2</sup> : ∫ 2<i>t</i>e<sup>−<i>t</i>/2</sup> d<i>t</i> = −4<i>t</i>e<sup>−<i>t</i>/2</sup> + ∫ 4e<sup>−<i>t</i>/2</sup> d<i>t</i> = −4<i>t</i>e<sup>−<i>t</i>/2</sup> − 8e<sup>−<i>t</i>/2</sup> + <i>C</i>. Entre 0 et <i>T</i> : 8 − (4<i>T</i> + 8)e<sup>−<i>T</i>/2</sup>. Pour <i>T</i> = 6 : 8 − 32e<sup>−3</sup> ≈ 6,41.</p><p>Quand <i>T</i> → +∞, (4<i>T</i> + 8)e<sup>−<i>T</i>/2</sup> → 0 (croissances comparées) : l’exposition totale vaut 8. Après 6 heures, 80 % de l’exposition totale est déjà passée.</p>'},
  {kind:'Problème',h:'Une suite d’intégrales par récurrence',
   p:`Pour <i>n</i> ∈ ℕ, on pose <i>I</i><sub><i>n</i></sub> = ∫₀¹ <i>x</i><sup><i>n</i></sup> e<sup><i>x</i></sup> d<i>x</i>. Calculer <i>I</i><sub>5</sub> directement demanderait cinq intégrations par parties. On cherche plutôt une relation entre <i>I</i><sub><i>n</i></sub> et <i>I</i><sub><i>n</i>−1</sub>, obtenue par une seule intégration par parties, puis on l’exploite de proche en proche et on étudie la limite de la suite.`,
   parts:[
    {q:'a) Calcule <i>I</i>₀ = ∫₀¹ e<sup><i>x</i></sup> d<i>x</i>, arrondi au millième.',lab:'I₀ =',ans:Math.E-1,tol:.002,hint:'Primitive immédiate.',why:'I₀ = [e^x]₀¹ = e − 1 ≈ 1,718.'},
    {q:'b) Avec <i>u</i> = <i>x</i><sup><i>n</i></sup> et <i>v</i>′ = e<sup><i>x</i></sup>, quelle relation obtient-on pour <i>n</i> ≥ 1 ?',opts:['<i>I</i><sub><i>n</i></sub> = e + <i>n</i> <i>I</i><sub><i>n</i>−1</sub>','<i>I</i><sub><i>n</i></sub> = e − <i>n</i> <i>I</i><sub><i>n</i>−1</sub>','<i>I</i><sub><i>n</i></sub> = <i>n</i> e − <i>I</i><sub><i>n</i>−1</sub>','<i>I</i><sub><i>n</i></sub> = e − <i>I</i><sub><i>n</i>−1</sub>/<i>n</i>'],ans:1,hint:'[xⁿ e^x]₀¹ = e, et u′ = n x^(n−1).',why:'Iₙ = [xⁿ e^x]₀¹ − ∫₀¹ n x^(n−1) e^x dx = e − n Iₙ₋₁.'},
    {q:'c) Déduis-en <i>I</i>₂, arrondi au millième.',lab:'I₂ =',ans:Math.E-2,tol:.002,hint:'Calcule d’abord I₁ = e − I₀.',why:'I₁ = e − (e − 1) = 1, puis I₂ = e − 2 · 1 = e − 2 ≈ 0,718.'},
    {q:'d) Puis <i>I</i>₃, arrondi au millième.',lab:'I₃ =',ans:6-2*Math.E,tol:.002,hint:'I₃ = e − 3 I₂.',why:'I₃ = e − 3(e − 2) = 6 − 2e ≈ 0,563.'},
    {q:'e) Pour tout <i>x</i> ∈ [0 ; 1], 0 ≤ <i>x</i><sup><i>n</i></sup> e<sup><i>x</i></sup> ≤ e <i>x</i><sup><i>n</i></sup>. Que peut-on en déduire ?',opts:['<i>I</i><sub><i>n</i></sub> → e','0 ≤ <i>I</i><sub><i>n</i></sub> ≤ e/(<i>n</i> + 1), donc <i>I</i><sub><i>n</i></sub> → 0','<i>I</i><sub><i>n</i></sub> → 1','La suite n’a pas de limite'],ans:1,hint:'Intègre l’encadrement entre 0 et 1 : ∫₀¹ xⁿ dx = 1/(n + 1).',why:'En intégrant : 0 ≤ Iₙ ≤ e ∫₀¹ xⁿ dx = e/(n + 1) → 0. Par les gendarmes, Iₙ → 0 : la fonction xⁿ e^x s’écrase sur [0 ; 1[ quand n grandit.'},
   ],
   sol:'<p><i>I</i>₀ = e − 1. Pour <i>n</i> ≥ 1, par parties avec <i>u</i> = <i>x</i><sup><i>n</i></sup>, <i>v</i>′ = e<sup><i>x</i></sup> : <i>I</i><sub><i>n</i></sub> = [<i>x</i><sup><i>n</i></sup>e<sup><i>x</i></sup>]₀¹ − <i>n</i>∫₀¹ <i>x</i><sup><i>n</i>−1</sup>e<sup><i>x</i></sup> d<i>x</i> = e − <i>n</i><i>I</i><sub><i>n</i>−1</sub>.</p><p>D’où <i>I</i>₁ = 1, <i>I</i>₂ = e − 2 ≈ 0,718, <i>I</i>₃ = 6 − 2e ≈ 0,563, <i>I</i>₄ = 9e − 24 ≈ 0,465… Chaque terme s’obtient en une ligne.</p><p>Comme 0 ≤ <i>x</i><sup><i>n</i></sup>e<sup><i>x</i></sup> ≤ e<i>x</i><sup><i>n</i></sup> sur [0 ; 1], on a 0 ≤ <i>I</i><sub><i>n</i></sub> ≤ e/(<i>n</i> + 1), et <i>I</i><sub><i>n</i></sub> → 0. La relation de récurrence montre alors que <i>n</i><i>I</i><sub><i>n</i>−1</sub> → e : les termes décroissent comme e/<i>n</i>.</p>'},
]},
);

COURS.push(
/* ===================== 3. SUBSTITUTION ET CHANGEMENT DE VARIABLE ===================== */
{subj:'gred',sem:'ana',id:'gred-substitution',h:'Substitution et changement de variable',p:'Reconnaître u′(x) f(u(x)), primitiver par substitution, puis changer de variable dans une intégrale définie en changeant les bornes : la règle de chaîne lue à l’envers.',steps:[
  {h:'Lire la règle de chaîne à l’envers',p:`<p>Comment primitiver 2<i>x</i> cos(<i>x</i>²) ? Ce n’est pas un produit quelconque : le facteur 2<i>x</i> est exactement la dérivée de l’intérieur <i>x</i>². Cette coïncidence est la clé de toute une famille de primitives.</p>
${RAP('<p>Dérivée d’une composée : (<i>F</i>(<i>u</i>(<i>x</i>)))′ = <i>F</i>′(<i>u</i>(<i>x</i>)) · <i>u</i>′(<i>x</i>). Et <i>F</i> est une primitive de <i>f</i> si <i>F</i>′ = <i>f</i>.</p>')}
${THM('<p>Soit <i>u</i> dérivable et <i>F</i> une primitive de <i>f</i> sur un intervalle contenant les valeurs de <i>u</i>. Alors <b>∫ <i>f</i>(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>) d<i>x</i> = <i>F</i>(<i>u</i>(<i>x</i>)) + <i>C</i></b>.</p>')}
${WHY('<p>Il suffit de dériver le membre de droite : (<i>F</i>(<i>u</i>(<i>x</i>)))′ = <i>F</i>′(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>) = <i>f</i>(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>). C’est la règle de chaîne, lue de droite à gauche. Aucun calcul nouveau : la preuve tient en une ligne, et c’est pour cela que la méthode est sûre.</p>')}
${IDEA('<p>Avec les différentielles, tout devient mécanique : on pose <i>u</i> = <i>u</i>(<i>x</i>), donc d<i>u</i> = <i>u</i>′(<i>x</i>) d<i>x</i>, et l’intégrale ∫ <i>f</i>(<i>u</i>) <i>u</i>′(<i>x</i>) d<i>x</i> devient <b>∫ <i>f</i>(<i>u</i>) d<i>u</i></b>, une intégrale dans la variable <i>u</i>. La règle de chaîne garantit que ce remplacement est légitime. C’est la <b>substitution</b>.</p>')}
${EX('<p>∫ 2<i>x</i> cos(<i>x</i>²) d<i>x</i> : <i>u</i> = <i>x</i>², d<i>u</i> = 2<i>x</i> d<i>x</i>. L’intégrale devient ∫ cos <i>u</i> d<i>u</i> = sin <i>u</i> + <i>C</i> = <b>sin(<i>x</i>²) + <i>C</i></b>. Contrôle : (sin(<i>x</i>²))′ = cos(<i>x</i>²) · 2<i>x</i>.</p>')}
${WARN('<p>Le facteur <i>u</i>′ est indispensable. ∫ cos(<i>x</i>²) d<i>x</i> tout seul n’a <b>aucune</b> primitive exprimable avec les fonctions usuelles : sans le 2<i>x</i>, la méthode ne s’applique pas, et aucune autre non plus.</p>')}`,
   note:'On reconnaît la situation en cherchant une fonction « intérieure » dont la dérivée apparaît en facteur, à une constante multiplicative près.'},
  {kind:'Méthode',h:'Primitiver par substitution : poser u, calculer du',
   p:`<p><b>Quand :</b> l’intégrande contient une fonction composée <i>f</i>(<i>u</i>(<i>x</i>)) et, en facteur, la dérivée <i>u</i>′(<i>x</i>) à une constante près. <b>Pourquoi ça marche :</b> ∫ <i>f</i>(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>) d<i>x</i> = <i>F</i>(<i>u</i>(<i>x</i>)) + <i>C</i>, par la règle de chaîne. <b>Comment :</b></p><ol><li>choisis l’intérieur : <i>u</i> = <i>u</i>(<i>x</i>) ;</li><li>calcule d<i>u</i> = <i>u</i>′(<i>x</i>) d<i>x</i>, et exprime le facteur présent avec d<i>u</i> (ajuste la constante : si tu as <i>x</i> d<i>x</i> et d<i>u</i> = 2<i>x</i> d<i>x</i>, alors <i>x</i> d<i>x</i> = d<i>u</i>/2) ;</li><li>écris l’intégrale en <i>u</i> seulement : plus aucun <i>x</i> ne doit rester ;</li><li>primitive en <i>u</i>, puis remplace <i>u</i> par son expression en <i>x</i> ;</li><li>vérifie en dérivant.</li></ol>`,
   demo:{enonce:'Calcule ∫ tan <i>x</i> d<i>x</i> sur un intervalle où cos <i>x</i> ≠ 0.',
    etapes:[{f:`tan <i>x</i> = ${F('sin <i>x</i>','cos <i>x</i>')} : l’intérieur est cos <i>x</i>, et sa dérivée −sin <i>x</i> est présente au signe près.`,w:'On cherche une fonction dont la dérivée apparaît en facteur : c’est le dénominateur.'},
     {f:'<i>u</i> = cos <i>x</i>, d<i>u</i> = −sin <i>x</i> d<i>x</i>, donc sin <i>x</i> d<i>x</i> = −d<i>u</i>.',w:'On ajuste la constante : ici un signe moins.'},
     {f:`∫ tan <i>x</i> d<i>x</i> = ∫ ${F('−d<i>u</i>','<i>u</i>')} = −ln|<i>u</i>| + <i>C</i>`,w:'Plus de x : on primitive 1/u.'},
     {f:'= −ln|cos <i>x</i>| + <i>C</i>.',w:'Retour à la variable x.'},
     {f:'Contrôle : (−ln|cos <i>x</i>|)′ = −(−sin <i>x</i>)/cos <i>x</i> = tan <i>x</i>.',w:'La dérivée de ln|u| est u′/u.'}],
    conclusion:'∫ tan <i>x</i> d<i>x</i> = −ln|cos <i>x</i>| + <i>C</i>. La valeur absolue est nécessaire : cos <i>x</i> peut être négatif, et ln|<i>u</i>| a pour dérivée <i>u</i>′/<i>u</i> dans les deux cas.'},
   note:'Si, après substitution, il reste des x impossibles à exprimer avec u, c’est que la substitution n’est pas la bonne : change de u ou de méthode.'},
  {h:'Un logarithme caché',p:`Calcule ∫₀² ${F('<i>x</i>','1 + <i>x</i>²')} d<i>x</i>, arrondi au millième.`,lab:'I =',ans:Math.log(5)/2,tol:.002,
   why:'u = 1 + x², du = 2x dx, donc x dx = du/2. Primitive : ½ ln(1 + x²). Entre 0 et 2 : ½ ln 5 − 0 ≈ 0,805.'},
  {h:'Les formes à reconnaître',p:`<p>Chaque formule de dérivation composée fournit une « forme » qu’on apprend à reconnaître d’un coup d’œil, sans même écrire la substitution. Le tableau rassemble les plus fréquentes ; <i>u</i> désigne une fonction de <i>x</i> et <i>u</i>′ sa dérivée.</p>
${PROP(tab(['forme','primitive','car'],[['<i>u</i>′ e<sup><i>u</i></sup>','e<sup><i>u</i></sup>','(e<sup><i>u</i></sup>)′ = <i>u</i>′e<sup><i>u</i></sup>'],['<i>u</i>′/<i>u</i>','ln|<i>u</i>|','(ln|<i>u</i>|)′ = <i>u</i>′/<i>u</i>'],['<i>u</i>′ <i>u</i><sup><i>n</i></sup> (<i>n</i> ≠ −1)','<i>u</i><sup><i>n</i>+1</sup>/(<i>n</i> + 1)','(<i>u</i><sup><i>n</i>+1</sup>)′ = (<i>n</i> + 1)<i>u</i>′<i>u</i><sup><i>n</i></sup>'],['<i>u</i>′/√<i>u</i>','2√<i>u</i>','(2√<i>u</i>)′ = <i>u</i>′/√<i>u</i>'],['<i>u</i>′/<i>u</i>²','−1/<i>u</i>','(−1/<i>u</i>)′ = <i>u</i>′/<i>u</i>²'],['<i>u</i>′ cos <i>u</i>','sin <i>u</i>','(sin <i>u</i>)′ = <i>u</i>′cos <i>u</i>'],['<i>u</i>′ sin <i>u</i>','−cos <i>u</i>','(−cos <i>u</i>)′ = <i>u</i>′sin <i>u</i>']]))}
${IDEA('<p>Dans chaque ligne, la colonne « car » est une dérivation composée : la forme n’est rien d’autre que la dérivée de la primitive. Apprendre le tableau, c’est apprendre à voir une dérivée composée là où elle se cache. Le cas <i>u</i> = <i>ax</i> + <i>b</i> (dérivée constante <i>a</i>) est le plus simple : ∫ <i>f</i>(<i>ax</i> + <i>b</i>) d<i>x</i> = <i>F</i>(<i>ax</i> + <i>b</i>)/<i>a</i>.</p>')}
${EX(`<p>∫ ${F('3<i>x</i>²','<i>x</i>³ + 1')} d<i>x</i> = ln|<i>x</i>³ + 1| + <i>C</i> (forme <i>u</i>′/<i>u</i> avec <i>u</i> = <i>x</i>³ + 1). ∫ <i>x</i> e<sup><i>x</i>²</sup> d<i>x</i> = ½ e<sup><i>x</i>²</sup> + <i>C</i> (forme <i>u</i>′e<sup><i>u</i></sup>, il manquait un facteur 2). ∫ cos <i>x</i> sin⁴ <i>x</i> d<i>x</i> = sin⁵ <i>x</i>/5 + <i>C</i> (forme <i>u</i>′<i>u</i>⁴).</p>`)}
${WARN('<p>La constante manquante se corrige, mais pas une fonction manquante : ∫ e<sup><i>x</i>²</sup> d<i>x</i> n’est pas ½ e<sup><i>x</i>²</sup>/<i>x</i>. On ne peut sortir de l’intégrale qu’une <b>constante</b>, jamais une expression en <i>x</i>.</p>')}`,
   note:'Réflexe : avant toute méthode lourde, dérive le candidat « intérieur » (ce qui est sous la racine, dans l’exposant, au dénominateur) et compare au reste de l’intégrande.'},
  {h:'Reconnais la forme',p:`Que vaut ∫ ${F('e<sup>√<i>x</i></sup>','√<i>x</i>')} d<i>x</i> ?`,
   opts:['e<sup>√<i>x</i></sup> + <i>C</i>','2e<sup>√<i>x</i></sup> + <i>C</i>','½ e<sup>√<i>x</i></sup> + <i>C</i>','e<sup>√<i>x</i></sup> · 2√<i>x</i> + <i>C</i>'],ans:1,
   why:'u = √x, du = dx/(2√x), donc dx/√x = 2 du. L’intégrale devient ∫ 2eᵘ du = 2e^√x + C. Contrôle : (2e^√x)′ = 2e^√x · 1/(2√x).'},
  {h:'Ajuste la borne',p:`L’aire colorée vaut ∫₀<sup><i>b</i></sup> ${F('2<i>x</i>','1 + <i>x</i>²')} d<i>x</i> = ln(1 + <i>b</i>²) (forme <i>u</i>′/<i>u</i>). Règle <i>b</i> pour que cette aire vaille exactement ln 5.`,
   params:[{id:'b',l:'b',min:.5,max:3,step:.5,v:1}],
   draw:v=>{ const f=x=>2*x/(1+x*x), P=plane({x:[-.3,3.5],y:[-.2,1.3],h:200,grid:false,lx:1,ly:.5}); P.area(f,0,v.b,{fill:'var(--accent)',fo:.3}).fn(f,{from:0,c:'var(--math)'}).dot(v.b,f(v.b),{c:'var(--spark)',r:5}); return axes(P,[-.3,3.5],[-.2,1.3]).svg(); },
   info:v=>`<i>b</i> = ${fmt(v.b)} : aire = ln(1 + ${fmt(v.b*v.b)}) = ln ${fmt(1+v.b*v.b)} ≈ ${fmt(Math.log(1+v.b*v.b),3)}. Cible : ln 5 ≈ ${fmt(Math.log(5),3)}.`,
   ok:v=>Math.abs(v.b-2)<1e-9,
   why:'ln(1 + b²) = ln 5 ⇔ 1 + b² = 5 ⇔ b = 2 (b > 0). La primitive ln(1 + x²) s’annule en 0, ce qui simplifie le calcul.'},
  {h:'Changement de variable dans une intégrale définie',p:`<p>Pour une intégrale définie, on peut éviter le retour à la variable <i>x</i> : il suffit de transporter les bornes. Deux lectures de la même formule, selon qu’on pose <i>u</i> = <i>u</i>(<i>x</i>) ou <i>x</i> = φ(<i>t</i>).</p>
${THM('<p><b>Formule du changement de variable.</b> Si <i>u</i> est dérivable à dérivée continue sur [<i>a</i> ; <i>b</i>] et <i>f</i> continue sur l’image de [<i>a</i> ; <i>b</i>] : <b>∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>f</i>(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>) d<i>x</i> = ∫<sub><i>u</i>(<i>a</i>)</sub><sup><i>u</i>(<i>b</i>)</sup> <i>f</i>(<i>u</i>) d<i>u</i></b>.</p>')}
${WHY('<p>Soit <i>F</i> une primitive de <i>f</i>. Le membre de gauche vaut [<i>F</i>(<i>u</i>(<i>x</i>))]<sub><i>a</i></sub><sup><i>b</i></sup> = <i>F</i>(<i>u</i>(<i>b</i>)) − <i>F</i>(<i>u</i>(<i>a</i>)) (théorème précédent et théorème fondamental). Le membre de droite vaut [<i>F</i>(<i>u</i>)]<sub><i>u</i>(<i>a</i>)</sub><sup><i>u</i>(<i>b</i>)</sup>, qui est le même nombre.</p>')}
${IDEA('<p><b>Lecture directe</b> : on pose <i>u</i> = <i>u</i>(<i>x</i>), d<i>u</i> = <i>u</i>′ d<i>x</i>, et les bornes <i>x</i> = <i>a</i>, <i>x</i> = <i>b</i> deviennent <i>u</i> = <i>u</i>(<i>a</i>), <i>u</i> = <i>u</i>(<i>b</i>). <b>Lecture inverse</b> : pour calculer ∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>f</i>(<i>x</i>) d<i>x</i>, on <b>remplace</b> <i>x</i> par φ(<i>t</i>), d<i>x</i> par φ′(<i>t</i>) d<i>t</i>, et on choisit α, β avec φ(α) = <i>a</i>, φ(β) = <i>b</i> : ∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>f</i>(<i>x</i>) d<i>x</i> = ∫<sub>α</sub><sup>β</sup> <i>f</i>(φ(<i>t</i>)) φ′(<i>t</i>) d<i>t</i>. Cette lecture sert quand l’intégrande n’a pas la forme <i>f</i>(<i>u</i>)<i>u</i>′, par exemple √(1 − <i>x</i>²).</p>')}
${EX(`<p>∫₀<sup>ln 2</sup> ${F('e<sup><i>x</i></sup>','1 + e<sup><i>x</i></sup>')} d<i>x</i> : <i>u</i> = e<sup><i>x</i></sup>, d<i>u</i> = e<sup><i>x</i></sup> d<i>x</i>, bornes <i>u</i>(0) = 1 et <i>u</i>(ln 2) = 2. L’intégrale devient ∫₁² ${F('d<i>u</i>','1 + <i>u</i>')} = [ln(1 + <i>u</i>)]₁² = ln 3 − ln 2 = ln(3/2) ≈ 0,405.</p>`)}
${WARN('<p>Dès qu’on change de variable, on change <b>les trois</b> : l’intégrande, le d<i>x</i>, et les bornes. Oublier l’un des trois donne un résultat faux. L’alternative est de revenir à <i>x</i> avant d’évaluer, avec les bornes d’origine.</p>')}`,
   note:'Si φ est strictement monotone, les nouvelles bornes sont dans le même ordre (φ croissante) ou dans l’ordre inverse (φ décroissante) : dans ce cas, φ′ < 0 et le signe se compense.'},
  {kind:'Méthode',h:'Poser x = φ(t) : l’exemple du disque',
   p:`<p><b>Quand :</b> l’intégrande contient √(<i>a</i>² − <i>x</i>²), et aucun facteur <i>x</i> ne permet une substitution directe. <b>Pourquoi ça marche :</b> en posant <i>x</i> = <i>a</i> sin <i>t</i> avec <i>t</i> ∈ [−π/2 ; π/2], on a <i>a</i>² − <i>x</i>² = <i>a</i>²(1 − sin² <i>t</i>) = <i>a</i>² cos² <i>t</i>, et cos <i>t</i> ≥ 0 sur cet intervalle : la racine disparaît, √(<i>a</i>² − <i>x</i>²) = <i>a</i> cos <i>t</i>. <b>Comment :</b></p><ol><li>pose <i>x</i> = <i>a</i> sin <i>t</i>, donc d<i>x</i> = <i>a</i> cos <i>t</i> d<i>t</i> ;</li><li>traduis les bornes : <i>x</i> = 0 ↔ <i>t</i> = 0, <i>x</i> = <i>a</i> ↔ <i>t</i> = π/2 ;</li><li>remplace tout, simplifie la racine, intègre en <i>t</i>.</li></ol>
${RAP('<p>Linéarisation : cos² <i>t</i> = (1 + cos 2<i>t</i>)/2 et sin² <i>t</i> = (1 − cos 2<i>t</i>)/2, conséquences de cos 2<i>t</i> = cos² <i>t</i> − sin² <i>t</i> et cos² <i>t</i> + sin² <i>t</i> = 1.</p>')}`,
   demo:{enonce:'Calcule ∫₀¹ √(1 − <i>x</i>²) d<i>x</i>, l’aire d’un quart de disque de rayon 1.',
    etapes:[{f:'<i>x</i> = sin <i>t</i>, d<i>x</i> = cos <i>t</i> d<i>t</i> ; <i>x</i> = 0 ↔ <i>t</i> = 0, <i>x</i> = 1 ↔ <i>t</i> = π/2.',w:'sin est une bijection croissante de [0 ; π/2] sur [0 ; 1] : chaque borne a un unique antécédent.'},
     {f:'√(1 − sin² <i>t</i>) = √(cos² <i>t</i>) = cos <i>t</i>, car cos <i>t</i> ≥ 0 sur [0 ; π/2].',w:'C’est tout l’intérêt : la racine disparaît. Le signe se justifie par le choix de l’intervalle.'},
     {f:'∫₀¹ √(1 − <i>x</i>²) d<i>x</i> = ∫₀<sup>π/2</sup> cos <i>t</i> · cos <i>t</i> d<i>t</i> = ∫₀<sup>π/2</sup> cos² <i>t</i> d<i>t</i>.',w:'On remplace l’intégrande, le dx, et les bornes.'},
     {f:`= ∫₀<sup>π/2</sup> ${F('1 + cos 2<i>t</i>',2)} d<i>t</i> = [${F('<i>t</i>',2)} + ${F('sin 2<i>t</i>',4)}]₀<sup>π/2</sup> = ${F('π',4)}.`,w:'Linéarisation, puis sin π = sin 0 = 0.'}],
    conclusion:'∫₀¹ √(1 − <i>x</i>²) d<i>x</i> = π/4. Le disque complet a donc une aire de 4 · π/4 = <b>π</b> : la formule π<i>r</i>² sort du calcul intégral, et le π vient de la borne π/2.'},
   note:'Géométriquement, t est l’angle au centre : le changement de variable paramètre le quart de cercle par son angle.'},
  {h:'Un demi-disque de rayon 2',p:'Calcule ∫₀² √(4 − <i>x</i>²) d<i>x</i>, arrondi au millième.',lab:'I =',ans:Math.PI,tol:.002,
   why:'x = 2 sin t, dx = 2 cos t dt, bornes 0 et π/2 : ∫₀^(π/2) 2 cos t · 2 cos t dt = 4 ∫₀^(π/2) cos² t dt = 4 · π/4 = π ≈ 3,142. C’est le quart du disque de rayon 2, d’aire 4π.'},
  {kind:'Méthode',h:'Les changements de variable classiques',
   p:`<p><b>Quand :</b> l’intégrande contient une racine ou une somme de carrés que la forme <i>f</i>(<i>u</i>)<i>u</i>′ ne traite pas. <b>Pourquoi ça marche :</b> on choisit φ pour qu’une identité fasse disparaître l’obstacle. <b>Les trois à connaître :</b></p><ul><li><b>√(<i>a</i>² − <i>x</i>²)</b> : <i>x</i> = <i>a</i> sin <i>t</i>, grâce à 1 − sin² <i>t</i> = cos² <i>t</i> ;</li><li><b>1/(<i>a</i>² + <i>x</i>²)</b> ou √(<i>a</i>² + <i>x</i>²) : <i>x</i> = <i>a</i> tan <i>t</i>, <i>t</i> ∈ ]−π/2 ; π/2[, grâce à 1 + tan² <i>t</i> = 1/cos² <i>t</i> ; alors d<i>x</i> = <i>a</i>(1 + tan² <i>t</i>) d<i>t</i> ;</li><li><b>√<i>x</i></b> mélangé à des termes rationnels : <i>u</i> = √<i>x</i>, soit <i>x</i> = <i>u</i>², d<i>x</i> = 2<i>u</i> d<i>u</i> ; la racine devient un polynôme.</li></ul><p><b>Comment :</b> écris <i>x</i> = φ(<i>t</i>) et d<i>x</i> = φ′(<i>t</i>) d<i>t</i>, traduis les bornes en résolvant φ(<i>t</i>) = <i>a</i> et φ(<i>t</i>) = <i>b</i> dans l’intervalle où φ est bijective, remplace, simplifie.</p>`,
   demo:{enonce:`Calcule ∫₀⁴ ${F('d<i>x</i>','1 + √<i>x</i>')}.`,
    etapes:[{f:'<i>u</i> = √<i>x</i>, soit <i>x</i> = <i>u</i>², d<i>x</i> = 2<i>u</i> d<i>u</i> ; <i>x</i> = 0 ↔ <i>u</i> = 0, <i>x</i> = 4 ↔ <i>u</i> = 2.',w:'La racine est l’obstacle : on en fait la nouvelle variable.'},
     {f:`∫₀⁴ ${F('d<i>x</i>','1 + √<i>x</i>')} = ∫₀² ${F('2<i>u</i>','1 + <i>u</i>')} d<i>u</i>`,w:'Plus de racine : une fraction rationnelle simple.'},
     {f:`${F('2<i>u</i>','1 + <i>u</i>')} = 2 − ${F(2,'1 + <i>u</i>')}`,w:'Division : 2u = 2(1 + u) − 2.'},
     {f:'∫₀² (2 − 2/(1 + <i>u</i>)) d<i>u</i> = [2<i>u</i> − 2 ln(1 + <i>u</i>)]₀² = 4 − 2 ln 3.',w:'Primitives immédiates, ln 1 = 0.'}],
    conclusion:'∫₀⁴ d<i>x</i>/(1 + √<i>x</i>) = 4 − 2 ln 3 ≈ 1,803. Le changement <i>u</i> = √<i>x</i> transforme une racine en polynôme, au prix du facteur 2<i>u</i> venu de d<i>x</i>.'},
   note:'Avec x = tan t : ∫₀¹ dx/(1 + x²) = ∫₀^(π/4) (1 + tan² t)/(1 + tan² t) dt = π/4. Cette intégrale reviendra au chapitre suivant sous le nom d’arctan.'},
  {h:'Avec x = tan t',p:`Calcule ∫₀<sup>√3</sup> ${F('d<i>x</i>','1 + <i>x</i>²')} en posant <i>x</i> = tan <i>t</i>. Arrondis au millième.`,lab:'I =',ans:Math.PI/3,tol:.002,
   why:'dx = (1 + tan² t) dt, et 1 + x² = 1 + tan² t : l’intégrande devient 1. Bornes : tan t = 0 ⇔ t = 0, tan t = √3 ⇔ t = π/3. I = π/3 ≈ 1,047.'},
  {h:'Avec u = √x',p:`Calcule ∫₁⁴ ${F('e<sup>√<i>x</i></sup>','√<i>x</i>')} d<i>x</i>, arrondi au millième.`,lab:'I =',ans:2*(Math.exp(2)-Math.E),tol:.003,
   why:'u = √x, du = dx/(2√x), bornes u = 1 et u = 2 : I = ∫₁² 2eᵘ du = 2(e² − e) ≈ 9,342.'},
  {h:'Les pièges du changement de variable',p:`<p>La méthode est mécanique, mais trois oublis reviennent sans cesse. Chacun donne un résultat faux sans qu’aucune alarme ne sonne : il faut les connaître.</p>
${WARN('<p><b>Oublier le d<i>x</i>.</b> Poser <i>x</i> = φ(<i>t</i>) impose d<i>x</i> = φ′(<i>t</i>) d<i>t</i>. Avec <i>x</i> = sin <i>t</i>, écrire ∫ √(1 − <i>x</i>²) d<i>x</i> = ∫ cos <i>t</i> d<i>t</i> oublie le facteur cos <i>t</i> de d<i>x</i> et donne 1 au lieu de π/4.</p>')}
${WARN('<p><b>Oublier les bornes.</b> ∫₁² 2<i>x</i> e<sup><i>x</i>²</sup> d<i>x</i> avec <i>u</i> = <i>x</i>² : les bornes deviennent 1 et 4, pas 1 et 2. Résultat e⁴ − e, et non e² − e. Variante du même piège : revenir à <i>x</i> mais garder les bornes en <i>u</i>.</p>')}
${WARN('<p><b>Oublier la bijection.</b> Pour <i>x</i> = φ(<i>t</i>), il faut que φ parcoure [<i>a</i> ; <i>b</i>] une seule fois, de façon monotone, quand <i>t</i> va de α à β. Sinon les signes se mélangent : avec <i>x</i> = sin <i>t</i> et <i>t</i> de 0 à π, on reviendrait au point de départ et √(cos² <i>t</i>) = |cos <i>t</i>| changerait de signe à π/2. C’est aussi pour cela que √(cos² <i>t</i>) = cos <i>t</i> doit être justifié par l’intervalle choisi.</p>')}
${EX('<p>Calcul correct de ∫₁² 2<i>x</i> e<sup><i>x</i>²</sup> d<i>x</i> : <i>u</i> = <i>x</i>², d<i>u</i> = 2<i>x</i> d<i>x</i>, <i>u</i>(1) = 1, <i>u</i>(2) = 4. Donc ∫₁⁴ e<sup><i>u</i></sup> d<i>u</i> = e⁴ − e ≈ 51,88. En revenant à <i>x</i> : [e<sup><i>x</i>²</sup>]₁² donne le même résultat.</p>')}
${IDEA('<p>Un contrôle rapide : l’intégrale d’une fonction positive est positive, et un changement de variable ne change pas la valeur. Si la nouvelle intégrale a un signe absurde ou une valeur très différente de l’estimation « base × hauteur », un des trois oublis est probable.</p>')}`,
   note:'Dans une primitive (sans bornes), le piège des bornes disparaît, mais il faut impérativement revenir à la variable x à la fin.'},
  {h:'Trouve l’erreur',p:'Un élève calcule ∫₁² 2<i>x</i> e<sup><i>x</i>²</sup> d<i>x</i> en posant <i>u</i> = <i>x</i>² et écrit ∫₁² e<sup><i>u</i></sup> d<i>u</i> = e² − e. Quelle est la bonne valeur ?',
   opts:['e² − e : le calcul est juste','e⁴ − e² : il fallait élever les deux bornes au carré','e⁴ − e : les bornes deviennent <i>u</i>(1) = 1 et <i>u</i>(2) = 4','(e⁴ − e)/2 : il manquait le facteur ½ de d<i>u</i>'],ans:2,
   why:'du = 2x dx est bien présent (pas de facteur ½), mais les bornes doivent être transportées : u(1) = 1 et u(2) = 4. Résultat : e⁴ − e ≈ 51,88.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`${KEEP('<ul><li><b>Substitution</b> : ∫ <i>f</i>(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>) d<i>x</i> = <i>F</i>(<i>u</i>(<i>x</i>)) + <i>C</i>, car (<i>F</i>∘<i>u</i>)′ = <i>f</i>(<i>u</i>) <i>u</i>′. On pose <i>u</i>, d<i>u</i> = <i>u</i>′ d<i>x</i>, on ajuste la constante.</li><li><b>Formes</b> : <i>u</i>′e<sup><i>u</i></sup> → e<sup><i>u</i></sup> ; <i>u</i>′/<i>u</i> → ln|<i>u</i>| ; <i>u</i>′<i>u</i><sup><i>n</i></sup> → <i>u</i><sup><i>n</i>+1</sup>/(<i>n</i> + 1) ; <i>u</i>′/√<i>u</i> → 2√<i>u</i> ; <i>u</i>′ cos <i>u</i> → sin <i>u</i>.</li><li>∫ tan <i>x</i> d<i>x</i> = −ln|cos <i>x</i>| + <i>C</i> ; ∫ <i>x</i>/(1 + <i>x</i>²) d<i>x</i> = ½ ln(1 + <i>x</i>²) + <i>C</i>.</li><li><b>Intégrale définie</b> : ∫<sub><i>a</i></sub><sup><i>b</i></sup> <i>f</i>(<i>u</i>(<i>x</i>)) <i>u</i>′(<i>x</i>) d<i>x</i> = ∫<sub><i>u</i>(<i>a</i>)</sub><sup><i>u</i>(<i>b</i>)</sup> <i>f</i>(<i>u</i>) d<i>u</i> : on change intégrande, d<i>x</i> et bornes.</li><li><b>Lecture inverse</b> <i>x</i> = φ(<i>t</i>), d<i>x</i> = φ′(<i>t</i>) d<i>t</i>, φ bijective sur l’intervalle : √(<i>a</i>² − <i>x</i>²) → <i>x</i> = <i>a</i> sin <i>t</i> ; 1 + <i>x</i>² → <i>x</i> = tan <i>t</i> ; √<i>x</i> → <i>x</i> = <i>u</i>².</li><li>∫₀¹ √(1 − <i>x</i>²) d<i>x</i> = π/4 : l’aire du disque unité vaut π.</li><li><b>Pièges</b> : oublier le d<i>x</i>, oublier les bornes, oublier la bijection (et le signe de la racine).</li></ul>')}`,
   note:'Substitution et intégration par parties sont les deux seules techniques générales : la première défait une composée, la seconde défait un produit.'},
  {kind:'Problème',h:'L’aire d’une ellipse',
   p:`L’ellipse d’équation <i>x</i>²/<i>a</i>² + <i>y</i>²/<i>b</i>² = 1, avec <i>a</i> = 3 et <i>b</i> = 2, est le cercle de rayon 1 étiré d’un facteur 3 horizontalement et 2 verticalement. Sa moitié supérieure est la courbe <i>y</i> = <i>b</i>√(1 − <i>x</i>²/<i>a</i>²) pour <i>x</i> ∈ [−<i>a</i> ; <i>a</i>]. Par symétrie, l’aire totale vaut 4 fois l’aire du quart situé dans le premier quadrant. On la calcule par le changement de variable <i>x</i> = <i>a</i> sin <i>t</i>.`,
   fig:(()=>{ const P=plane({x:[-4,4],y:[-3,3],h:240,lab:1}); P.area(x=>2*Math.sqrt(Math.max(0,1-x*x/9)),0,3,{fill:'var(--accent)',fo:.3}).curve(t=>3*Math.cos(t),t=>2*Math.sin(t),0,2*Math.PI,{c:'var(--math)'}).circ(0,0,1,{c:'var(--muted)',w:1.5,dash:true}).dot(3,0,{r:4,l:'a',dy:16}).dot(0,2,{r:4,l:'b',dx:-16}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle intégrale donne l’aire du quart d’ellipse dans le premier quadrant ?',opts:['∫₀³ √(1 − <i>x</i>²/9) d<i>x</i>','∫₀² 2√(1 − <i>x</i>²/9) d<i>x</i>','∫₀³ 2√(1 − <i>x</i>²/9) d<i>x</i>','∫₀³ 2√(1 − <i>x</i>²/4) d<i>x</i>'],ans:2,hint:'La hauteur en x est y = b√(1 − x²/a²), et x va de 0 à a.',why:'Aire = ∫₀^a y dx = ∫₀³ 2√(1 − x²/9) dx.'},
    {q:'b) On pose <i>x</i> = 3 sin <i>t</i>. Que deviennent d<i>x</i> et les bornes ?',opts:['d<i>x</i> = 3 cos <i>t</i> d<i>t</i>, <i>t</i> de 0 à π/2','d<i>x</i> = cos <i>t</i> d<i>t</i>, <i>t</i> de 0 à 3','d<i>x</i> = 3 cos <i>t</i> d<i>t</i>, <i>t</i> de 0 à π','d<i>x</i> = 3 sin <i>t</i> d<i>t</i>, <i>t</i> de 0 à π/2'],ans:0,hint:'Dérive 3 sin t, puis résous 3 sin t = 0 et 3 sin t = 3 dans [−π/2 ; π/2].',why:'dx = 3 cos t dt ; sin t = 0 donne t = 0 et sin t = 1 donne t = π/2.'},
    {q:'c) Calcule ∫₀³ √(1 − <i>x</i>²/9) d<i>x</i>, arrondi au millième.',lab:'J =',ans:3*Math.PI/4,tol:.002,hint:'Après substitution : ∫₀^(π/2) cos t · 3 cos t dt = 3 ∫₀^(π/2) cos² t dt.',why:'√(1 − sin² t) = cos t, donc J = 3 ∫₀^(π/2) cos² t dt = 3 · π/4 = 3π/4 ≈ 2,356.'},
    {q:'d) Quelle est l’aire totale de l’ellipse ? Arrondis au centième.',lab:'aire =',ans:6*Math.PI,tol:.01,hint:'Quart d’aire = 2 · J, puis multiplie par 4.',why:'Quart : 2 · 3π/4 = 3π/2. Total : 4 · 3π/2 = 6π ≈ 18,85, c’est-à-dire πab.'},
   ],
   sol:'<p>L’aire du quart d’ellipse est ∫₀³ 2√(1 − <i>x</i>²/9) d<i>x</i>. Avec <i>x</i> = 3 sin <i>t</i>, d<i>x</i> = 3 cos <i>t</i> d<i>t</i>, <i>t</i> ∈ [0 ; π/2], et √(1 − sin² <i>t</i>) = cos <i>t</i> ≥ 0 : l’intégrale devient 6∫₀<sup>π/2</sup> cos² <i>t</i> d<i>t</i> = 6 · π/4 = 3π/2.</p><p>L’aire totale vaut 4 · 3π/2 = 6π ≈ 18,85. En gardant <i>a</i> et <i>b</i> quelconques, le même calcul donne 4 · <i>ab</i> · π/4 = <b>π<i>ab</i></b> : étirer le disque unité par <i>a</i> et <i>b</i> multiplie son aire π par <i>ab</i>, ce que le changement de variable rend visible.</p>'},
  {kind:'Problème',h:'Une intégrale sans primitive, par symétrie',
   p:`On veut calculer <i>I</i> = ∫₀<sup>π/2</sup> ${F('sin <i>x</i>','sin <i>x</i> + cos <i>x</i>')} d<i>x</i>. Aucune primitive simple n’est en vue. L’idée : le changement de variable <i>x</i> = π/2 − <i>t</i> échange sin et cos, puisque sin(π/2 − <i>t</i>) = cos <i>t</i> et cos(π/2 − <i>t</i>) = sin <i>t</i>. On compare alors <i>I</i> à <i>J</i> = ∫₀<sup>π/2</sup> ${F('cos <i>x</i>','sin <i>x</i> + cos <i>x</i>')} d<i>x</i>.`,
   fig:(()=>{ const f=x=>Math.sin(x)/(Math.sin(x)+Math.cos(x)), P=plane({x:[-.2,1.8],y:[-.2,1.2],h:200,grid:false,lx:.5,ly:.5}); P.area(f,0,Math.PI/2,{fill:'var(--accent)',fo:.3}).fn(f,{from:0,to:Math.PI/2,c:'var(--math)'}).fn(x=>1-f(x),{from:0,to:Math.PI/2,c:'var(--spark)',w:2,dash:true}).text(Math.PI/2,0,'π/2',{a:'middle',dy:14,c:'var(--muted)',s:11}); return axes(P,[-.2,1.8],[-.2,1.2]).svg(); })(),
   parts:[
    {q:'a) Avec <i>x</i> = π/2 − <i>t</i>, que deviennent d<i>x</i> et les bornes ?',opts:['d<i>x</i> = d<i>t</i>, <i>t</i> de 0 à π/2','d<i>x</i> = −d<i>t</i>, <i>t</i> de π/2 à 0','d<i>x</i> = −d<i>t</i>, <i>t</i> de 0 à π/2','d<i>x</i> = (π/2) d<i>t</i>, <i>t</i> de 0 à 1'],ans:1,hint:'Dérive π/2 − t, puis cherche t pour x = 0 et pour x = π/2.',why:'dx = −dt ; x = 0 ⇔ t = π/2 et x = π/2 ⇔ t = 0. Les bornes s’échangent et le signe moins les remet dans l’ordre.'},
    {q:'b) Que vaut alors <i>I</i> ?',opts:['<i>I</i> = −<i>J</i>','<i>I</i> = <i>J</i>','<i>I</i> = π/2 − <i>J</i>','<i>I</i> = 2<i>J</i>'],ans:1,hint:'Remplace sin x par cos t et cos x par sin t, puis remets les bornes dans l’ordre.',why:'I = ∫_(π/2)^0 cos t/(cos t + sin t) · (−dt) = ∫₀^(π/2) cos t/(sin t + cos t) dt = J.'},
    {q:'c) Calcule <i>I</i> + <i>J</i>, arrondi au millième.',lab:'I + J =',ans:Math.PI/2,tol:.002,hint:'Additionne les deux intégrandes : le numérateur devient sin x + cos x.',why:'I + J = ∫₀^(π/2) (sin x + cos x)/(sin x + cos x) dx = ∫₀^(π/2) 1 dx = π/2.'},
    {q:'d) Déduis-en <i>I</i>, arrondi au millième.',lab:'I =',ans:Math.PI/4,tol:.002,hint:'I = J et I + J = π/2.',why:'2I = π/2, donc I = π/4 ≈ 0,785.'},
   ],
   sol:'<p>Posons <i>x</i> = π/2 − <i>t</i> : d<i>x</i> = −d<i>t</i>, et les bornes 0, π/2 deviennent π/2, 0. Comme sin(π/2 − <i>t</i>) = cos <i>t</i> et cos(π/2 − <i>t</i>) = sin <i>t</i>, on obtient <i>I</i> = ∫<sub>π/2</sub><sup>0</sup> cos <i>t</i>/(cos <i>t</i> + sin <i>t</i>) (−d<i>t</i>) = ∫₀<sup>π/2</sup> cos <i>t</i>/(sin <i>t</i> + cos <i>t</i>) d<i>t</i> = <i>J</i>.</p><p>Par ailleurs <i>I</i> + <i>J</i> = ∫₀<sup>π/2</sup> 1 d<i>x</i> = π/2, puisque les numérateurs s’ajoutent pour donner le dénominateur. Donc <i>I</i> = <i>J</i> = π/4.</p><p>On n’a jamais écrit de primitive : le changement de variable a servi à exploiter une symétrie. La figure le montre : la courbe de <i>I</i> et celle de <i>J</i> (en pointillé) sont symétriques par rapport à <i>x</i> = π/4 et se complètent à 1.</p>'},
]},
);

COURS.push(
/* ===================== 4. FONCTIONS TRIGONOMÉTRIQUES RÉCIPROQUES ===================== */
{subj:'gred',sem:'ana',id:'gred-trigo-reciproques',h:'Fonctions trigonométriques réciproques',p:'Pourquoi restreindre sin, cos et tan, puis arcsin, arccos, arctan : domaines, graphes, valeurs, identités, dérivées démontrées et les primitives qui en découlent.',steps:[
  {h:'Pourquoi sin n’a pas de réciproque sur ℝ',p:`<p>On veut « défaire » le sinus : connaissant sin <i>x</i> = 0,5, retrouver <i>x</i>. Mais il y a une infinité de réponses (π/6, 5π/6, π/6 + 2π…). Une fonction ne peut rendre qu’une seule valeur : il faut d’abord choisir.</p>
${RAP('<p>Une application <i>f</i> : <i>A</i> → <i>B</i> a une <b>réciproque</b> <i>f</i>⁻¹ : <i>B</i> → <i>A</i> si et seulement si elle est <b>bijective</b> : chaque élément de <i>B</i> a exactement un antécédent. Alors <i>f</i>⁻¹(<i>y</i>) est cet unique antécédent, et <i>f</i>(<i>f</i>⁻¹(<i>y</i>)) = <i>y</i>, <i>f</i>⁻¹(<i>f</i>(<i>x</i>)) = <i>x</i>.</p>')}
${IDEA('<p>sin n’est pas injective sur ℝ : la droite horizontale <i>y</i> = 0,5 coupe la sinusoïde une infinité de fois. Le remède est de <b>restreindre</b> le domaine à un intervalle où sin est strictement monotone et prend <b>toutes</b> ses valeurs de −1 à 1. Le choix le plus simple, et le plus symétrique autour de 0, est [−π/2 ; π/2].</p>')}
${PROP('<p>Sur [−π/2 ; π/2], sin est continue et strictement croissante (sa dérivée cos est positive, nulle seulement aux bords), avec sin(−π/2) = −1 et sin(π/2) = 1. C’est donc une <b>bijection de [−π/2 ; π/2] sur [−1 ; 1]</b>.</p>')}
${WHY('<p>Strictement croissante ⇒ injective : deux réels distincts ont des images distinctes. Continue sur un intervalle fermé, elle prend toutes les valeurs entre ses extrémités −1 et 1 (théorème des valeurs intermédiaires) ⇒ surjective sur [−1 ; 1]. Injective et surjective : bijective.</p>')}
${EX('<p>Dans [−π/2 ; π/2], l’équation sin <i>x</i> = 0,5 a une seule solution, π/6. Les autres solutions dans ℝ (5π/6, −7π/6…) sont hors de la fenêtre choisie. Pour cos, qui est paire, il faut une fenêtre différente : [0 ; π]. Pour tan : ]−π/2 ; π/2[.</p>')}
<p>Déplace la hauteur <i>y</i> : la sinusoïde complète est coupée plusieurs fois, l’arc coloré une seule fois.</p>`,
   params:[{id:'y',l:'y',min:-1,max:1,step:.1,v:.5}],
   draw:v=>{ const P=plane({x:[-7,7],y:[-1.6,1.6],h:200,grid:false,lx:0,ly:1}); P.fn(Math.sin,{c:'var(--muted)',w:2}).fn(Math.sin,{from:-Math.PI/2,to:Math.PI/2,c:'var(--math)',w:4}).seg(-7,v.y,7,v.y,{c:'var(--spark)',w:1.5,dash:true});
     const a=Math.asin(v.y); for(let k=-2;k<=2;k++){ const x1=a+2*k*Math.PI, x2=Math.PI-a+2*k*Math.PI; if(Math.abs(x1)<7) P.dot(x1,v.y,{r:4,c:k===0?'var(--bad)':'var(--muted)'}); if(Math.abs(x2)<7) P.dot(x2,v.y,{r:4,c:'var(--muted)'}); }
     P.text(-Math.PI/2,0,'−π/2',{a:'middle',dy:14,c:'var(--muted)',s:10}).text(Math.PI/2,0,'π/2',{a:'middle',dy:14,c:'var(--muted)',s:10}); return P.svg(); },
   info:v=>`<i>y</i> = ${fmt(v.y)} : une infinité de solutions dans ℝ, une seule dans [−π/2 ; π/2] : <i>x</i> ≈ ${fmt(Math.asin(v.y),3)} rad.`},
  {h:'La fonction arcsin',p:`<p>La restriction de sin à [−π/2 ; π/2] étant bijective, elle possède une réciproque. On lui donne un nom.</p>
${DEF('<p><b>arcsin</b> : [−1 ; 1] → [−π/2 ; π/2] est la réciproque de sin restreint à [−π/2 ; π/2]. Pour <i>y</i> ∈ [−1 ; 1], <b>arcsin <i>y</i> est l’unique <i>x</i> ∈ [−π/2 ; π/2] tel que sin <i>x</i> = <i>y</i></b>. On lit « arc sinus » : l’arc (l’angle en radians) dont le sinus vaut <i>y</i>.</p>')}
${PROP('<p>sin(arcsin <i>y</i>) = <i>y</i> pour tout <i>y</i> ∈ [−1 ; 1] ; arcsin(sin <i>x</i>) = <i>x</i> <b>seulement</b> pour <i>x</i> ∈ [−π/2 ; π/2]. arcsin est impaire, continue, strictement croissante, et son graphe est le symétrique de celui de sin par rapport à la droite <i>y</i> = <i>x</i>.</p>')}
${WHY('<p>Les deux premières égalités sont la définition d’une réciproque, avec la restriction de domaine. La symétrie des graphes : (<i>a</i> ; <i>b</i>) est sur le graphe de sin ⇔ (<i>b</i> ; <i>a</i>) est sur celui de arcsin. L’imparité : si sin <i>x</i> = <i>y</i> avec <i>x</i> ∈ [−π/2 ; π/2], alors sin(−<i>x</i>) = −<i>y</i> avec −<i>x</i> dans le même intervalle, donc arcsin(−<i>y</i>) = −<i>x</i>.</p>')}
${EX(tab(['<i>y</i>','0','1/2','√2/2','√3/2','1'],[['arcsin <i>y</i>','0','π/6','π/4','π/3','π/2']])+'<p>Et par imparité, arcsin(−1/2) = −π/6. Attention : arcsin 2 n’existe pas, 2 n’est le sinus d’aucun réel.</p>')}
${WARN('<p>arcsin(sin(5π/6)) n’est pas 5π/6 : 5π/6 ∉ [−π/2 ; π/2]. On a sin(5π/6) = 1/2, donc arcsin(sin(5π/6)) = arcsin(1/2) = π/6. En général, arcsin(sin <i>x</i>) est l’angle de [−π/2 ; π/2] qui a le même sinus que <i>x</i>.</p>')}`,
   fig:(()=>{ const P=plane({x:[-2,2],y:[-2,2],h:280,lab:1}); P.seg(-2,-2,2,2,{c:'var(--muted)',w:1,dash:true}).fn(Math.sin,{from:-Math.PI/2,to:Math.PI/2,c:'var(--muted)',w:2.5}).fn(x=>Math.asin(x),{from:-1,to:1,c:'var(--math)',n:400}).dot(1,Math.PI/2,{r:4,l:'(1 ; π/2)',dx:-70,dy:-8}).dot(.5,Math.PI/6,{r:4,c:'var(--spark)',l:'(½ ; π/6)',dx:8,dy:4}).text(1.5,.9,'sin',{c:'var(--muted)'}).text(.25,1.5,'arcsin',{c:'var(--math)'}); return P.svg(); })()},
  {h:'Un arcsin de sinus',p:'Calcule arcsin(sin(5π/6)), en radians, arrondi au millième.',lab:'=',ans:Math.PI/6,tol:.002,
   why:'sin(5π/6) = 1/2, et l’angle de [−π/2 ; π/2] dont le sinus vaut 1/2 est π/6 ≈ 0,524. Ce n’est pas 5π/6, qui sort de l’intervalle.'},
  {h:'arccos et arctan',p:`<p>Même construction pour le cosinus et la tangente, avec une fenêtre adaptée à chacun : il faut un intervalle où la fonction est strictement monotone et atteint toutes ses valeurs.</p>
${DEF('<p><b>arccos</b> : [−1 ; 1] → [0 ; π] est la réciproque de cos restreint à [0 ; π] : arccos <i>y</i> est l’unique <i>x</i> ∈ [0 ; π] tel que cos <i>x</i> = <i>y</i>. <b>arctan</b> : ℝ → ]−π/2 ; π/2[ est la réciproque de tan restreint à ]−π/2 ; π/2[ : arctan <i>y</i> est l’unique <i>x</i> ∈ ]−π/2 ; π/2[ tel que tan <i>x</i> = <i>y</i>.</p>')}
${WHY('<p>Sur [0 ; π], cos est continue, strictement décroissante (dérivée −sin ≤ 0), de 1 à −1 : bijection sur [−1 ; 1]. Sur ]−π/2 ; π/2[, tan est continue, strictement croissante (dérivée 1 + tan² &gt; 0), tend vers −∞ en −π/2 et vers +∞ en π/2 : bijection sur ℝ tout entier. C’est pourquoi arctan est définie <b>partout</b>, contrairement à arcsin et arccos.</p>')}
${PROP('<p>arccos est décroissante, et arccos(−<i>y</i>) = π − arccos <i>y</i>. arctan est impaire, croissante, et <b>lim<sub><i>y</i>→+∞</sub> arctan <i>y</i> = π/2</b>, lim<sub><i>y</i>→−∞</sub> arctan <i>y</i> = −π/2 : son graphe a deux asymptotes horizontales. Les asymptotes verticales de tan deviennent horizontales par symétrie.</p>')}
${EX(tab(['<i>y</i>','0','1/2','√2/2','√3/2','1'],[['arccos <i>y</i>','π/2','π/3','π/4','π/6','0']])+tab(['<i>y</i>','0','1/√3','1','√3'],[['arctan <i>y</i>','0','π/6','π/4','π/3']])+'<p>arccos(−1/2) = π − π/3 = 2π/3 ; arctan(−1) = −π/4.</p>')}
<p>Déplace <i>y</i> : arctan <i>y</i> se lit sur la courbe, toujours entre −π/2 et π/2.</p>`,
   params:[{id:'y',l:'y',min:-6,max:6,step:.5,v:1}],
   draw:v=>{ const P=plane({x:[-6.5,6.5],y:[-2,2],h:200,grid:false,lx:2,ly:1}); P.seg(-6.5,Math.PI/2,6.5,Math.PI/2,{c:'var(--muted)',w:1,dash:true}).seg(-6.5,-Math.PI/2,6.5,-Math.PI/2,{c:'var(--muted)',w:1,dash:true}).fn(Math.atan,{c:'var(--math)'}).seg(v.y,0,v.y,Math.atan(v.y),{c:'var(--spark)',w:2,dash:true}).dot(v.y,Math.atan(v.y),{c:'var(--spark)'}).text(-6.3,Math.PI/2,'π/2',{dy:-5,c:'var(--muted)',s:11}).text(-6.3,-Math.PI/2,'−π/2',{dy:14,c:'var(--muted)',s:11}); return axes(P,[-6.5,6.5],[-2,2]).svg(); },
   info:v=>`arctan(${fmt(v.y)}) ≈ ${fmt(Math.atan(v.y),3)} rad ≈ ${fmt(Math.atan(v.y)*180/Math.PI,1)}°. Contrôle : tan(${fmt(Math.atan(v.y),3)}) ≈ ${fmt(Math.tan(Math.atan(v.y)),2)}.`},
  {h:'Un arccos négatif',p:'Que vaut arccos(−1/2) ?',
   opts:['−π/3','2π/3','π/3','5π/6'],ans:1,
   why:'On cherche x ∈ [0 ; π] avec cos x = −1/2 : c’est 2π/3. −π/3 a le bon cosinus mais sort de [0 ; π] ; π/3 donne +1/2.'},
  {h:'L’identité arcsin x + arccos x = π/2',p:`<p>Les tables de valeurs suggèrent une régularité : arcsin(1/2) = π/6 et arccos(1/2) = π/3, dont la somme est π/2 ; de même π/4 + π/4, π/3 + π/6. Ce n’est pas un hasard.</p>
${THM('<p>Pour tout <i>x</i> ∈ [−1 ; 1] : <b>arcsin <i>x</i> + arccos <i>x</i> = π/2</b>.</p>')}
${WHY('<p>Pose θ = arcsin <i>x</i>, donc θ ∈ [−π/2 ; π/2] et sin θ = <i>x</i>. Considère π/2 − θ : il appartient à [0 ; π] (si θ va de −π/2 à π/2, alors π/2 − θ va de π à 0), et cos(π/2 − θ) = sin θ = <i>x</i>. Or arccos <i>x</i> est, par définition, <b>l’unique</b> élément de [0 ; π] dont le cosinus vaut <i>x</i>. Donc arccos <i>x</i> = π/2 − θ = π/2 − arcsin <i>x</i>.</p>')}
${IDEA('<p>Dans un triangle rectangle d’hypoténuse 1 et de côté <i>x</i>, l’angle opposé à <i>x</i> vaut arcsin <i>x</i> et l’angle adjacent vaut arccos <i>x</i> ; les deux angles aigus sont complémentaires. La preuve ci-dessus ne fait que rendre cet argument valable aussi pour <i>x</i> négatif, où il n’y a plus de triangle.</p>')}
${EX('<p>arccos(0,3) = π/2 − arcsin(0,3) ≈ 1,5708 − 0,3047 = 1,2661. Une calculatrice qui n’aurait que arcsin suffit donc pour arccos. Autre conséquence : arcsin et arccos ont des dérivées opposées, ce qu’on vérifiera plus loin.</p>')}
${WARN('<p>Pas d’analogue simple pour arctan avec arcsin. En revanche, pour <i>x</i> &gt; 0 : arctan <i>x</i> + arctan(1/<i>x</i>) = π/2 (l’angle et son complémentaire dans un triangle rectangle de côtés 1 et <i>x</i>). Pour <i>x</i> &lt; 0, la somme vaut −π/2.</p>')}`,
   fig:(()=>{ const P=plane({x:[-.3,1.4],y:[-.3,1.1],h:220,grid:false,axes:false}); const x=.6, c=Math.sqrt(1-x*x); P.poly([[0,0],[c,0],[c,x]],{fill:'var(--accent)',fo:.2,c:'var(--ink)',w:2}).text(c/2,0,'√(1 − x²)',{a:'middle',dy:16,s:11}).text(c,x/2,'x',{dx:8,s:12}).text(c/2,x/2,'1',{dx:-14,dy:-4,s:12}).text(.12,.03,'arcsin x',{s:11,c:'var(--math)'}).text(c-.03,x-.03,'arccos x',{a:'end',dy:-10,s:11,c:'var(--spark)'}); return P.svg(); })()},
  {kind:'Méthode',h:'Calculer cos(arcsin x), tan(arccos x) et les composées croisées',
   p:`<p><b>Quand :</b> on doit évaluer une fonction trigonométrique d’un arc-quelque-chose, comme cos(arcsin(3/5)) ou sin(arctan 2), sans calculatrice. <b>Pourquoi ça marche :</b> l’arc θ est un angle dont on connaît <b>une</b> ligne trigonométrique ; les identités cos² θ + sin² θ = 1 et 1 + tan² θ = 1/cos² θ donnent les autres, au signe près. Le <b>signe</b> se lit sur l’intervalle de définition : θ = arcsin <i>x</i> ou arctan <i>x</i> est dans [−π/2 ; π/2], où cos θ ≥ 0 ; θ = arccos <i>x</i> est dans [0 ; π], où sin θ ≥ 0. <b>Comment :</b></p><ol><li>pose θ = arc…(<i>x</i>) et écris ce que tu sais : sin θ = <i>x</i>, ou cos θ = <i>x</i>, ou tan θ = <i>x</i> ;</li><li>utilise l’identité pour exprimer la ligne demandée ;</li><li>choisis le signe avec l’intervalle de θ.</li></ol>`,
   demo:{enonce:'Calcule cos(arcsin(3/5)) puis sin(arctan 2).',
    etapes:[{f:'θ = arcsin(3/5) : sin θ = 3/5 et θ ∈ [−π/2 ; π/2].',w:'On nomme l’angle et on note l’intervalle.'},
     {f:'cos² θ = 1 − 9/25 = 16/25, et cos θ ≥ 0 sur [−π/2 ; π/2], donc cos θ = 4/5.',w:'Identité fondamentale, puis signe.'},
     {f:'φ = arctan 2 : tan φ = 2 et φ ∈ ]−π/2 ; π/2[, donc cos φ &gt; 0.',w:'Deuxième calcul, même démarche.'},
     {f:`1/cos² φ = 1 + tan² φ = 5, donc cos φ = 1/√5 et sin φ = tan φ · cos φ = 2/√5.`,w:'On passe par cos, puis sin = tan × cos.'}],
    conclusion:'cos(arcsin(3/5)) = 4/5 et sin(arctan 2) = 2/√5 ≈ 0,894. En général : <b>cos(arcsin <i>x</i>) = √(1 − <i>x</i>²)</b>, <b>sin(arccos <i>x</i>) = √(1 − <i>x</i>²)</b>, <b>cos(arctan <i>x</i>) = 1/√(1 + <i>x</i>²)</b>. Ces trois formules serviront pour les dérivées.'},
   note:'Le triangle rectangle de côtés 3, 4, 5 illustre le premier calcul : l’angle dont le sinus vaut 3/5 a pour cosinus 4/5.'},
  {h:'Une tangente d’arcsin',p:'Calcule tan(arcsin(5/13)) (valeur exacte, écrite en décimal arrondie au millième).',lab:'=',ans:5/12,tol:.002,
   why:'θ = arcsin(5/13) : sin θ = 5/13, cos θ = √(1 − 25/169) = 12/13 (positif), donc tan θ = 5/12 ≈ 0,417. Triangle 5, 12, 13.'},
  {h:'Dériver une fonction réciproque',p:`<p>Pour dériver arcsin, on n’a pas de formule explicite : seulement la relation sin(arcsin <i>x</i>) = <i>x</i>. Il faut un théorème général sur la dérivée d’une réciproque.</p>
${THM('<p>Soit <i>f</i> une bijection continue et strictement monotone d’un intervalle <i>I</i> sur un intervalle <i>J</i>, dérivable en <i>x</i>₀ ∈ <i>I</i> avec <b><i>f</i>′(<i>x</i>₀) ≠ 0</b>. Alors <i>f</i>⁻¹ est dérivable en <i>y</i>₀ = <i>f</i>(<i>x</i>₀) et <b>(<i>f</i>⁻¹)′(<i>y</i>₀) = 1/<i>f</i>′(<i>x</i>₀) = 1/<i>f</i>′(<i>f</i>⁻¹(<i>y</i>₀))</b>.</p>')}
${WHY('<p>Idée : le taux d’accroissement de <i>f</i>⁻¹ entre <i>y</i>₀ et <i>y</i> est (<i>x</i> − <i>x</i>₀)/(<i>y</i> − <i>y</i>₀) avec <i>x</i> = <i>f</i>⁻¹(<i>y</i>), c’est-à-dire l’<b>inverse</b> du taux de <i>f</i> entre <i>x</i>₀ et <i>x</i>. Quand <i>y</i> → <i>y</i>₀, <i>x</i> → <i>x</i>₀ (une bijection monotone continue a une réciproque continue), donc le taux de <i>f</i> tend vers <i>f</i>′(<i>x</i>₀) ≠ 0 et son inverse vers 1/<i>f</i>′(<i>x</i>₀). Version rapide, une fois la dérivabilité acquise : on dérive <i>f</i>(<i>f</i>⁻¹(<i>y</i>)) = <i>y</i>, ce qui donne <i>f</i>′(<i>f</i>⁻¹(<i>y</i>)) · (<i>f</i>⁻¹)′(<i>y</i>) = 1.</p>')}
${IDEA('<p>Les graphes de <i>f</i> et <i>f</i>⁻¹ sont symétriques par rapport à <i>y</i> = <i>x</i>. Cette symétrie échange abscisses et ordonnées, donc transforme une pente <i>p</i> en pente 1/<i>p</i>. Une tangente horizontale (<i>p</i> = 0) devient verticale : c’est le cas exclu <i>f</i>′(<i>x</i>₀) = 0.</p>')}
${EX('<p><i>f</i>(<i>x</i>) = e<sup><i>x</i></sup>, <i>f</i>⁻¹ = ln : (ln)′(<i>y</i>) = 1/e<sup>ln <i>y</i></sup> = 1/<i>y</i>. On retrouve la dérivée de ln. <b>Contre-exemple</b> : <i>f</i>(<i>x</i>) = <i>x</i>³ est bijective sur ℝ mais <i>f</i>′(0) = 0 ; sa réciproque <i>y</i> ↦ ∛<i>y</i> n’est pas dérivable en 0 (tangente verticale), bien qu’elle y soit continue.</p>')}`,
   note:'En notation de Leibniz, le théorème s’écrit dx/dy = 1/(dy/dx) : une des raisons du succès de cette notation.'},
  {h:'Dérivées de arcsin, arccos, arctan',p:`<p>On applique le théorème précédent aux trois restrictions, en éliminant θ grâce aux composées calculées dans la méthode.</p>
${THM(`<p>Sur ]−1 ; 1[ : <b>(arcsin <i>x</i>)′ = ${F(1,'√(1 − <i>x</i>²)')}</b> et <b>(arccos <i>x</i>)′ = −${F(1,'√(1 − <i>x</i>²)')}</b>. Sur ℝ : <b>(arctan <i>x</i>)′ = ${F(1,'1 + <i>x</i>²')}</b>.</p>`)}
${WHY('<p><b>arcsin</b> : θ = arcsin <i>x</i>, <i>f</i> = sin, <i>f</i>′(θ) = cos θ, non nul pour θ ∈ ]−π/2 ; π/2[. Donc (arcsin)′(<i>x</i>) = 1/cos θ = 1/√(1 − sin² θ) = 1/√(1 − <i>x</i>²), la racine positive car cos θ &gt; 0. <b>arccos</b> : <i>f</i>′(θ) = −sin θ avec sin θ &gt; 0 sur ]0 ; π[, d’où le signe moins et la même racine. <b>arctan</b> : <i>f</i>′(θ) = 1 + tan² θ = 1 + <i>x</i>², jamais nul, d’où 1/(1 + <i>x</i>²) sur ℝ entier.</p>')}
${IDEA('<p>Aux bornes <i>x</i> = ±1, cos θ = 0 : le théorème ne s’applique pas, et en effet arcsin et arccos ont des tangentes <b>verticales</b> en ±1, images des tangentes horizontales de sin en ±π/2. arctan, elle, est dérivable partout et sa dérivée 1/(1 + <i>x</i>²) tend vers 0 à l’infini : la courbe s’aplatit vers ses asymptotes. On retrouve aussi (arcsin + arccos)′ = 0, cohérent avec la somme constante π/2.</p>')}
${EX('<p>Pente de arcsin en 0 : 1 (comme sin). En <i>x</i> = 0,8 : 1/√(1 − 0,64) = 1/0,6 ≈ 1,667. Pente de arctan en 0 : 1 ; en <i>x</i> = 2 : 1/5.</p>')}
<p>Déplace <i>x</i> et observe la tangente à arcsin : sa pente croît sans borne quand <i>x</i> s’approche de ±1.</p>`,
   params:[{id:'x',l:'x',min:-.9,max:.9,step:.1,v:0}],
   draw:v=>{ const P=plane({x:[-1.5,1.5],y:[-1.8,1.8],h:260,grid:false,lx:.5,ly:.5}); const p=1/Math.sqrt(1-v.x*v.x), y0=Math.asin(v.x); P.fn(Math.asin,{from:-1,to:1,c:'var(--math)',n:400}).fn(x=>y0+p*(x-v.x),{c:'var(--spark)',w:2,dash:true}).dot(v.x,y0,{c:'var(--spark)'}); return axes(P,[-1.5,1.5],[-1.8,1.8]).svg(); },
   info:v=>`<i>x</i> = ${fmt(v.x)} : (arcsin)′(<i>x</i>) = 1/√(1 − ${fmt(v.x*v.x)}) ≈ ${fmt(1/Math.sqrt(1-v.x*v.x),3)}.`},
  {kind:'Méthode',h:'Dériver une composée avec arctan ou arcsin, et prouver une identité',
   p:`<p><b>Quand :</b> une fonction contient arctan(<i>u</i>(<i>x</i>)) ou arcsin(<i>u</i>(<i>x</i>)), ou quand on veut prouver qu’une expression en arctan est constante. <b>Pourquoi ça marche :</b> règle de chaîne : <b>(arctan <i>u</i>)′ = <i>u</i>′/(1 + <i>u</i>²)</b>, <b>(arcsin <i>u</i>)′ = <i>u</i>′/√(1 − <i>u</i>²)</b>. Et une fonction de dérivée nulle sur un intervalle y est constante : pour prouver une identité, on dérive, on trouve 0, on évalue en un point. <b>Comment :</b></p><ol><li>identifie <i>u</i> et calcule <i>u</i>′ ;</li><li>applique la formule, simplifie ;</li><li>pour une identité : dérive les deux membres, montre que la différence a une dérivée nulle, puis calcule sa valeur en un point commode.</li></ol>`,
   demo:{enonce:'Dérive <i>f</i>(<i>x</i>) = arctan(2<i>x</i>), puis montre que <i>g</i>(<i>x</i>) = arctan <i>x</i> + arctan(1/<i>x</i>) est constante sur ]0 ; +∞[ et donne sa valeur.',
    etapes:[{f:`<i>u</i> = 2<i>x</i>, <i>u</i>′ = 2 : <i>f</i>′(<i>x</i>) = ${F(2,'1 + 4<i>x</i>²')}.`,w:'Règle de chaîne avec (arctan u)′ = u′/(1 + u²).'},
     {f:`(arctan(1/<i>x</i>))′ = ${F('−1/<i>x</i>²','1 + 1/<i>x</i>²')} = ${F('−1','<i>x</i>² + 1')}.`,w:'u = 1/x, u′ = −1/x² ; on multiplie haut et bas par x².'},
     {f:`<i>g</i>′(<i>x</i>) = ${F(1,'1 + <i>x</i>²')} − ${F(1,'1 + <i>x</i>²')} = 0 sur ]0 ; +∞[.`,w:'La dérivée est nulle sur un intervalle : g est constante dessus.'},
     {f:'<i>g</i>(1) = arctan 1 + arctan 1 = π/4 + π/4 = π/2.',w:'On évalue en un point où tout est connu.'}],
    conclusion:'<i>f</i>′(<i>x</i>) = 2/(1 + 4<i>x</i>²), et <b>arctan <i>x</i> + arctan(1/<i>x</i>) = π/2 pour <i>x</i> &gt; 0</b>. Sur ]−∞ ; 0[, le même calcul donne la constante <i>g</i>(−1) = −π/2 : l’intervalle compte, car <i>g</i> n’est pas définie en 0.'},
   note:'Ce procédé « dérivée nulle puis un point » est le moyen standard de prouver une identité entre fonctions réciproques.'},
  {h:'Dérivée en un point',p:'Soit <i>f</i>(<i>x</i>) = arcsin(<i>x</i>/2). Calcule <i>f</i>′(1), arrondi au millième.',lab:'f′(1) =',ans:1/Math.sqrt(3),tol:.002,
   why:'u = x/2, u′ = 1/2 : f′(x) = (1/2)/√(1 − x²/4). En x = 1 : (1/2)/√(3/4) = (1/2)/(√3/2) = 1/√3 ≈ 0,577.'},
  {h:'Les primitives qui en découlent',p:`<p>Chaque dérivée nouvelle est une primitive nouvelle lue à l’envers. Deux intégrandes très fréquentes, qu’aucune autre technique ne traite directement, trouvent ainsi leur primitive.</p>
${THM(`<p><b>∫ ${F('d<i>x</i>','√(1 − <i>x</i>²)')} = arcsin <i>x</i> + <i>C</i></b> sur ]−1 ; 1[, et <b>∫ ${F('d<i>x</i>','1 + <i>x</i>²')} = arctan <i>x</i> + <i>C</i></b> sur ℝ. Plus généralement, pour <i>a</i> &gt; 0 : <b>∫ ${F('d<i>x</i>','√(<i>a</i>² − <i>x</i>²)')} = arcsin ${F('<i>x</i>','<i>a</i>')} + <i>C</i></b> et <b>∫ ${F('d<i>x</i>','<i>a</i>² + <i>x</i>²')} = ${F(1,'<i>a</i>')} arctan ${F('<i>x</i>','<i>a</i>')} + <i>C</i></b>.</p>`)}
${WHY(`<p>Les deux premières sont les dérivées du théorème précédent. Pour les formes en <i>a</i>, on dérive le candidat : (arcsin(<i>x</i>/<i>a</i>))′ = (1/<i>a</i>)/√(1 − <i>x</i>²/<i>a</i>²) = 1/√(<i>a</i>² − <i>x</i>²) ; et ((1/<i>a</i>) arctan(<i>x</i>/<i>a</i>))′ = (1/<i>a</i>)(1/<i>a</i>)/(1 + <i>x</i>²/<i>a</i>²) = 1/(<i>a</i>² + <i>x</i>²). Le changement de variable <i>x</i> = <i>a</i> tan <i>t</i> du chapitre précédent donne le même résultat : avec <i>x</i> = tan <i>t</i>, ∫ d<i>x</i>/(1 + <i>x</i>²) = ∫ d<i>t</i> = <i>t</i> = arctan <i>x</i>.</p>`)}
${EX(`<p>∫₀¹ ${F('d<i>x</i>','1 + <i>x</i>²')} = arctan 1 − arctan 0 = π/4. ∫₀<sup>1/2</sup> ${F('d<i>x</i>','√(1 − <i>x</i>²)')} = arcsin(1/2) = π/6. ∫₀³ ${F('d<i>x</i>','9 + <i>x</i>²')} = (1/3) arctan 1 = π/12.</p>`)}
${WARN(`<p>Ne confonds pas ∫ d<i>x</i>/(1 + <i>x</i>²) = arctan <i>x</i> avec ∫ <i>x</i> d<i>x</i>/(1 + <i>x</i>²) = ½ ln(1 + <i>x</i>²) : le facteur <i>x</i> au numérateur change tout (forme <i>u</i>′/<i>u</i>). De même 1/√(1 − <i>x</i>²) donne arcsin, mais <i>x</i>/√(1 − <i>x</i>²) donne −√(1 − <i>x</i>²).</p>`)}`,
   note:'La première formule explique le π/4 obtenu pour l’aire du quart de disque : les deux calculs passent par le même angle.'},
  {h:'Une intégrale en arctan',p:`Calcule ∫₀² ${F('d<i>x</i>','4 + <i>x</i>²')}, arrondi au millième.`,lab:'I =',ans:Math.PI/8,tol:.002,
   why:'a = 2 : primitive (1/2) arctan(x/2). Entre 0 et 2 : (1/2)(arctan 1 − arctan 0) = π/8 ≈ 0,393.'},
  {h:'Le piège arcsin(sin x)',p:'Que vaut arcsin(sin 4), où 4 est en radians ?',
   opts:['4','π − 4','4 − π','4 − 2π'],ans:1,
   why:'4 ∈ [π/2 ; 3π/2] (environ [1,57 ; 4,71]), hors de [−π/2 ; π/2]. L’angle de [−π/2 ; π/2] qui a le même sinus que 4 est π − 4 ≈ −0,858 (car sin(π − x) = sin x). Contrôle : sin 4 ≈ −0,757 et sin(π − 4) ≈ −0,757.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`${KEEP('<ul><li>Une réciproque exige une bijection : on <b>restreint</b> sin à [−π/2 ; π/2], cos à [0 ; π], tan à ]−π/2 ; π/2[.</li><li><b>arcsin</b> : [−1 ; 1] → [−π/2 ; π/2], impaire, croissante. <b>arccos</b> : [−1 ; 1] → [0 ; π], décroissante. <b>arctan</b> : ℝ → ]−π/2 ; π/2[, impaire, asymptotes ±π/2.</li><li>sin(arcsin <i>x</i>) = <i>x</i> toujours ; arcsin(sin <i>x</i>) = <i>x</i> <b>seulement</b> si <i>x</i> ∈ [−π/2 ; π/2].</li><li>Valeurs : arcsin(1/2) = π/6, arccos(1/2) = π/3, arctan 1 = π/4, arctan √3 = π/3.</li><li><b>arcsin <i>x</i> + arccos <i>x</i> = π/2</b> ; arctan <i>x</i> + arctan(1/<i>x</i>) = π/2 pour <i>x</i> &gt; 0.</li><li>cos(arcsin <i>x</i>) = √(1 − <i>x</i>²), cos(arctan <i>x</i>) = 1/√(1 + <i>x</i>²) : identité + signe donné par l’intervalle.</li><li>(<i>f</i>⁻¹)′(<i>y</i>) = 1/<i>f</i>′(<i>f</i>⁻¹(<i>y</i>)) si <i>f</i>′ ≠ 0. D’où (arcsin)′ = 1/√(1 − <i>x</i>²), (arccos)′ = −1/√(1 − <i>x</i>²), (arctan)′ = 1/(1 + <i>x</i>²).</li><li>Primitives : ∫ d<i>x</i>/√(<i>a</i>² − <i>x</i>²) = arcsin(<i>x</i>/<i>a</i>), ∫ d<i>x</i>/(<i>a</i>² + <i>x</i>²) = (1/<i>a</i>) arctan(<i>x</i>/<i>a</i>).</li></ul>')}`,
   note:'Pour prouver une identité entre arcs : dériver, trouver 0, évaluer en un point. Pour calculer une composée : nommer l’angle, identité, signe.'},
  {kind:'Problème',h:'Sous quel angle voit-on le tableau ?',
   p:`Un tableau de 2 m de haut est accroché à un mur, son bord inférieur à 1 m au-dessus du niveau des yeux. Un visiteur se place à la distance <i>x</i> &gt; 0 du mur. Le bord inférieur est vu sous l’angle arctan(1/<i>x</i>) au-dessus de l’horizontale, le bord supérieur sous l’angle arctan(3/<i>x</i>). L’angle sous lequel le tableau est vu vaut donc θ(<i>x</i>) = arctan(3/<i>x</i>) − arctan(1/<i>x</i>). On cherche où se placer pour que cet angle soit maximal.`,
   fig:(()=>{ const P=plane({x:[-.5,4.5],y:[-.5,3.6],h:240,grid:false,axes:false}); P.seg(0,-.5,0,3.6,{c:'var(--ink)',w:3}).seg(0,0,4.5,0,{c:'var(--muted)',w:1,dash:true}).seg(0,1,0,3,{c:'var(--math)',w:8}).seg(2,0,0,1,{c:'var(--spark)',w:1.5}).seg(2,0,0,3,{c:'var(--spark)',w:1.5}).dot(2,0,{l:'œil',dy:16}).text(2,0,'x',{a:'middle',dx:-32,dy:14,s:11,c:'var(--muted)'}).text(0,2,'2 m',{dx:8,s:11}).text(0,.5,'1 m',{dx:8,s:11}).text(1.4,.55,'θ',{c:'var(--spark)',s:13}); return P.svg(); })(),
   parts:[
    {q:'a) Calcule θ(2) en radians, arrondi au millième.',lab:'θ(2) =',ans:Math.atan(1.5)-Math.atan(.5),tol:.002,hint:'arctan(1,5) − arctan(0,5) à la calculatrice.',why:'θ(2) = arctan(1,5) − arctan(0,5) ≈ 0,983 − 0,464 = 0,519 rad, soit environ 29,7°.'},
    {q:'b) Quelle est la dérivée θ′(<i>x</i>) ?',opts:[F(3,'1 + 9<i>x</i>²')+' − '+F(1,'1 + <i>x</i>²'),F('−3','<i>x</i>² + 9')+' + '+F(1,'<i>x</i>² + 1'),F(1,'<i>x</i>² + 9')+' − '+F(1,'<i>x</i>² + 1'),F('−3','<i>x</i>²')+' + '+F(1,'<i>x</i>²')],ans:1,hint:'(arctan u)′ = u′/(1 + u²) avec u = 3/x puis u = 1/x ; multiplie haut et bas par x².',why:'(arctan(3/x))′ = (−3/x²)/(1 + 9/x²) = −3/(x² + 9) et (arctan(1/x))′ = −1/(x² + 1). Donc θ′ = −3/(x² + 9) + 1/(x² + 1).'},
    {q:'c) Pour quelle distance <i>x</i> l’angle est-il maximal ? Arrondis au millième.',lab:'x =',unit:'m',ans:Math.sqrt(3),tol:.002,hint:'Résous θ′(x) = 0 : mets au même dénominateur.',why:'θ′ = 0 ⇔ x² + 9 = 3(x² + 1) ⇔ 2x² = 6 ⇔ x = √3 ≈ 1,732 m. θ′ > 0 avant, < 0 après : c’est un maximum.'},
    {q:'d) Quel est l’angle maximal, en radians ? Arrondis au millième.',lab:'θ max =',ans:Math.PI/6,tol:.002,hint:'3/√3 = √3 et 1/√3 : deux valeurs remarquables de arctan.',why:'θ(√3) = arctan √3 − arctan(1/√3) = π/3 − π/6 = π/6 ≈ 0,524 rad, soit exactement 30°.'},
   ],
   sol:'<p>θ(<i>x</i>) = arctan(3/<i>x</i>) − arctan(1/<i>x</i>). Par la règle de chaîne, θ′(<i>x</i>) = −3/(<i>x</i>² + 9) + 1/(<i>x</i>² + 1) = (−3<i>x</i>² − 3 + <i>x</i>² + 9)/((<i>x</i>² + 9)(<i>x</i>² + 1)) = (6 − 2<i>x</i>²)/((<i>x</i>² + 9)(<i>x</i>² + 1)).</p><p>θ′ s’annule en <i>x</i> = √3, positive avant et négative après : l’angle est maximal à √3 ≈ 1,73 m du mur, et vaut π/3 − π/6 = π/6, soit 30°. À 2 m, on n’a que 29,7° ; de très près ou de très loin, l’angle tend vers 0 (les deux arctan tendent vers π/2, puis vers 0).</p><p>Remarque : √3 = √(1 · 3) est la moyenne géométrique des hauteurs des deux bords. C’est un résultat général.</p>'},
  {kind:'Problème',h:'π/4 comme somme d’arctangentes',
   p:`On veut prouver des égalités comme <b>arctan(1/2) + arctan(1/3) = π/4</b>, utiles autrefois pour calculer les décimales de π. L’outil est la formule d’addition tan(<i>a</i> + <i>b</i>) = (tan <i>a</i> + tan <i>b</i>)/(1 − tan <i>a</i> tan <i>b</i>), jointe au fait que la tangente détermine l’angle dans ]−π/2 ; π/2[. On applique la même idée à la formule de Machin, 4 arctan(1/5) − arctan(1/239) = π/4.`,
   parts:[
    {q:'a) Soit <i>s</i> = arctan(1/2) + arctan(1/3). Calcule tan <i>s</i>.',lab:'tan s =',ans:1,hint:'Formule d’addition avec tan a = 1/2 et tan b = 1/3.',why:'tan s = (1/2 + 1/3)/(1 − 1/6) = (5/6)/(5/6) = 1.'},
    {q:'b) Pourquoi peut-on conclure que <i>s</i> = π/4 ?',opts:['Parce que tan <i>s</i> = 1 implique toujours <i>s</i> = π/4','Parce que <i>s</i> ∈ ]0 ; π/2[ (somme de deux arctan de nombres positifs, chacun &lt; π/4) et que tan est injective sur cet intervalle','Parce que arctan(1/2) = π/8 et arctan(1/3) = π/8','On ne peut pas : <i>s</i> pourrait valoir 5π/4'],ans:1,hint:'tan s = 1 a une infinité de solutions dans ℝ ; il faut localiser s.',why:'0 < arctan(1/2) < arctan 1 = π/4 et de même pour 1/3, donc 0 < s < π/2. Dans ]−π/2 ; π/2[, un seul angle a pour tangente 1 : π/4. Et arctan(1/2) ≈ 0,464 ≠ π/8 ≈ 0,393.'},
    {q:'c) Soit α = arctan(1/5). Calcule tan 2α (valeur exacte en décimal arrondie au millième).',lab:'tan 2α =',ans:5/12,tol:.002,hint:'tan 2α = 2 tan α/(1 − tan² α).',why:'tan 2α = (2/5)/(1 − 1/25) = (2/5)/(24/25) = 10/24 = 5/12 ≈ 0,417.'},
    {q:'d) Calcule tan 4α, arrondi au millième.',lab:'tan 4α =',ans:120/119,tol:.002,hint:'Applique encore la formule de duplication à 2α.',why:'tan 4α = (2 · 5/12)/(1 − 25/144) = (5/6)/(119/144) = (5/6)(144/119) = 120/119 ≈ 1,008. Un peu plus que 1 : 4α dépasse légèrement π/4, d’où la correction par arctan(1/239).'},
   ],
   sol:'<p>Avec <i>a</i> = arctan(1/2) et <i>b</i> = arctan(1/3) : tan(<i>a</i> + <i>b</i>) = (1/2 + 1/3)/(1 − 1/6) = 1. Comme 0 &lt; <i>a</i>, <i>b</i> &lt; π/4, la somme est dans ]0 ; π/2[, où tan est injective : <i>a</i> + <i>b</i> = π/4.</p><p>Pour Machin, α = arctan(1/5) donne tan 2α = 5/12 puis tan 4α = 120/119. Alors tan(4α − arctan(1/239)) = (120/119 − 1/239)/(1 + 120/(119 · 239)) = (120 · 239 − 119)/(119 · 239 + 120) = 28 561/28 561 = 1. Comme 4α ≈ 0,790 et arctan(1/239) ≈ 0,004, la différence est dans ]0 ; π/2[ : elle vaut π/4.</p><p>L’intérêt : arctan <i>x</i> se calcule très vite pour <i>x</i> petit (par une série), et ces formules ramènent π à de tels arctan.</p>'},
]},
);

COURS.push(
/* ===================== 5. FONCTIONS HYPERBOLIQUES ET LEURS RÉCIPROQUES ===================== */
{subj:'gred',sem:'ana',id:'gred-hyperboliques',h:'Fonctions hyperboliques et leurs réciproques',p:'ch, sh et th construites à partir de eˣ, l’identité ch² − sh² = 1 et l’hyperbole, les formules d’addition, puis argsh, argch, argth avec leurs expressions logarithmiques et leurs dérivées.',steps:[
  {h:'Partie paire et partie impaire de eˣ',p:`<p>Toute fonction <i>f</i> définie sur ℝ se décompose d’une seule façon en une fonction paire plus une fonction impaire : <i>p</i>(<i>x</i>) = (<i>f</i>(<i>x</i>) + <i>f</i>(−<i>x</i>))/2 et <i>i</i>(<i>x</i>) = (<i>f</i>(<i>x</i>) − <i>f</i>(−<i>x</i>))/2. Appliquée à l’exponentielle, cette décomposition produit deux fonctions assez importantes pour recevoir un nom.</p>
${DEF(`<p>Pour <i>x</i> ∈ ℝ : <b>ch <i>x</i> = ${F(E('<i>x</i>')+' + '+E('−<i>x</i>'),2)}</b> (<b>cosinus hyperbolique</b>), <b>sh <i>x</i> = ${F(E('<i>x</i>')+' − '+E('−<i>x</i>'),2)}</b> (<b>sinus hyperbolique</b>) et <b>th <i>x</i> = ${F('sh <i>x</i>','ch <i>x</i>')}</b> (<b>tangente hyperbolique</b>).</p>`)}
${IDEA(`<p>ch est la partie paire de e<sup><i>x</i></sup>, sh sa partie impaire, et <b>ch <i>x</i> + sh <i>x</i> = e<sup><i>x</i></sup></b>, ch <i>x</i> − sh <i>x</i> = e<sup>−<i>x</i></sup>. Les noms viennent de la ressemblance avec cos et sin, qu’on va découvrir propriété après propriété : mêmes parités, dérivées voisines, formules d’addition presque identiques, et un rôle analogue vis-à-vis de l’hyperbole au lieu du cercle.</p>`)}
${WHY('<p>ch(−<i>x</i>) = (e<sup>−<i>x</i></sup> + e<sup><i>x</i></sup>)/2 = ch <i>x</i> : paire. sh(−<i>x</i>) = (e<sup>−<i>x</i></sup> − e<sup><i>x</i></sup>)/2 = −sh <i>x</i> : impaire. th est impaire comme quotient d’une impaire par une paire. ch <i>x</i> &gt; 0 toujours (somme de deux exponentielles), donc th est définie sur ℝ.</p>')}
${EX('<p>ch 0 = (1 + 1)/2 = 1, sh 0 = 0, th 0 = 0. Pour <i>x</i> = ln 2 : e<sup><i>x</i></sup> = 2, e<sup>−<i>x</i></sup> = 1/2, donc ch(ln 2) = (2 + 1/2)/2 = 5/4, sh(ln 2) = (2 − 1/2)/2 = 3/4, th(ln 2) = 3/5. Pour <i>x</i> grand, e<sup>−<i>x</i></sup> est négligeable : ch <i>x</i> ≈ sh <i>x</i> ≈ e<sup><i>x</i></sup>/2.</p>')}
<p>Sur la figure, e<sup><i>x</i></sup> et e<sup>−<i>x</i></sup> sont en pointillé ; ch est leur moyenne, sh leur demi-différence.</p>`,
   params:[{id:'x',l:'x',min:-2,max:2,step:.25,v:1}],
   draw:v=>{ const P=plane({x:[-2.5,2.5],y:[-4,5],h:300,lab:1}); P.fn(Math.exp,{c:'var(--muted)',w:1.5,dash:true}).fn(x=>Math.exp(-x),{c:'var(--muted)',w:1.5,dash:true}).fn(ch,{c:'var(--math)'}).fn(sh,{c:'var(--spark)'}).seg(v.x,Math.exp(-v.x),v.x,Math.exp(v.x),{c:'var(--muted)',w:1.5}).dot(v.x,ch(v.x),{c:'var(--math)',l:'ch'}).dot(v.x,sh(v.x),{c:'var(--spark)',l:'sh',dy:16}); return axes(P,[-2.5,2.5],[-4,5]).svg(); },
   info:v=>`<i>x</i> = ${fmt(v.x)} : e<sup><i>x</i></sup> ≈ ${fmt(Math.exp(v.x),3)}, e<sup>−<i>x</i></sup> ≈ ${fmt(Math.exp(-v.x),3)}, ch <i>x</i> ≈ ${fmt(ch(v.x),3)} (moyenne), sh <i>x</i> ≈ ${fmt(sh(v.x),3)} (demi-différence).`},
  {h:'L’identité ch² − sh² = 1 et l’hyperbole',p:`<p>cos et sin vérifient cos² + sin² = 1, ce qui place le point (cos <i>t</i> ; sin <i>t</i>) sur le cercle unité. Que donne la même combinaison pour ch et sh ?</p>
${THM('<p>Pour tout <i>x</i> réel : <b>ch² <i>x</i> − sh² <i>x</i> = 1</b>. En conséquence, ch <i>x</i> ≥ 1, |sh <i>x</i>| &lt; ch <i>x</i>, |th <i>x</i>| &lt; 1 et <b>1 − th² <i>x</i> = 1/ch² <i>x</i></b>.</p>')}
${WHY('<p>Pose <i>a</i> = e<sup><i>x</i></sup> et <i>b</i> = e<sup>−<i>x</i></sup>, de sorte que <i>ab</i> = 1. Alors ch² − sh² = ((<i>a</i> + <i>b</i>)² − (<i>a</i> − <i>b</i>)²)/4 = 4<i>ab</i>/4 = 1, par l’identité (<i>a</i> + <i>b</i>)² − (<i>a</i> − <i>b</i>)² = 4<i>ab</i>. Ensuite ch² = 1 + sh² ≥ 1 et ch &gt; 0 donnent ch ≥ 1 ; en divisant ch² − sh² = 1 par ch², on obtient 1 − th² = 1/ch².</p>')}
${IDEA('<p>Le point <i>M</i>(<i>t</i>) = (ch <i>t</i> ; sh <i>t</i>) vérifie <i>x</i>² − <i>y</i>² = 1 : il parcourt la branche droite (<i>x</i> ≥ 1) de l’<b>hyperbole</b> <i>x</i>² − <i>y</i>² = 1, comme (cos <i>t</i> ; sin <i>t</i>) parcourt le cercle <i>x</i>² + <i>y</i>² = 1. D’où le nom « hyperbolique ». Quand <i>t</i> → ±∞, <i>M</i> s’approche des asymptotes <i>y</i> = ±<i>x</i>, puisque sh <i>t</i>/ch <i>t</i> = th <i>t</i> → ±1.</p>')}
${EX('<p>En <i>t</i> = ln 2 : ch = 5/4, sh = 3/4, et (5/4)² − (3/4)² = (25 − 9)/16 = 1. Le point (5/4 ; 3/4) est sur l’hyperbole. Si ch <i>x</i> = 13/5 et <i>x</i> &gt; 0, alors sh² <i>x</i> = 169/25 − 1 = 144/25 et sh <i>x</i> = 12/5 (positif car <i>x</i> &gt; 0).</p>')}
${WARN('<p>Le paramètre <i>t</i> n’est pas un angle au sens du cercle : l’angle polaire du point <i>M</i>(<i>t</i>) n’est pas <i>t</i>. En revanche <i>t</i>/2 est l’aire du secteur hyperbolique balayé depuis (1 ; 0), exactement comme <i>t</i>/2 est l’aire du secteur circulaire d’angle <i>t</i>. Le problème de fin de chapitre le démontre.</p>')}`,
   params:[{id:'t',l:'t',min:-1.8,max:1.8,step:.2,v:.8}],
   draw:v=>{ const P=plane({x:[-1,4],y:[-3,3],h:280,lab:1}); P.seg(-1,-1,3,3,{c:'var(--muted)',w:1,dash:true}).seg(-1,1,3,-3,{c:'var(--muted)',w:1,dash:true}).circ(0,0,1,{c:'var(--muted)',w:1.5}).curve(ch,sh,-2.1,2.1,{c:'var(--math)'}).arrow(0,0,ch(v.t),sh(v.t),{c:'var(--accent)',w:2.5}).dot(ch(v.t),sh(v.t),{l:'(ch t ; sh t)'}).dot(1,0,{r:4,c:'var(--muted)'}); return axes(P,[-1,4],[-3,3]).svg(); },
   info:v=>`<i>t</i> = ${fmt(v.t)} : ch² − sh² = ${fmt(ch(v.t)**2,3)} − ${fmt(sh(v.t)**2,3)} = ${fmt(ch(v.t)**2-sh(v.t)**2,3)}. th <i>t</i> = ${fmt(th(v.t),3)}, pente du vecteur.`},
  {h:'De ch à th',p:'On sait que ch <i>x</i> = 13/5 et <i>x</i> &gt; 0. Calcule th <i>x</i>, arrondi au millième.',lab:'th x =',ans:12/13,tol:.002,
   why:'sh² x = ch² x − 1 = 169/25 − 25/25 = 144/25, et sh x = 12/5 car x > 0. Donc th x = (12/5)/(13/5) = 12/13 ≈ 0,923.'},
  {h:'Dérivées et variations',p:`<p>Les dérivées se calculent terme à terme à partir des exponentielles. Elles ressemblent à celles de cos et sin, à un signe près, et ce signe change tout le comportement.</p>
${THM(`<p><b>(sh <i>x</i>)′ = ch <i>x</i></b>, <b>(ch <i>x</i>)′ = sh <i>x</i></b>, <b>(th <i>x</i>)′ = ${F(1,'ch² <i>x</i>')} = 1 − th² <i>x</i></b>.</p>`)}
${WHY('<p>(e<sup><i>x</i></sup>)′ = e<sup><i>x</i></sup> et (e<sup>−<i>x</i></sup>)′ = −e<sup>−<i>x</i></sup>. Donc (sh)′ = (e<sup><i>x</i></sup> + e<sup>−<i>x</i></sup>)/2 = ch et (ch)′ = (e<sup><i>x</i></sup> − e<sup>−<i>x</i></sup>)/2 = sh : pas de signe moins, contrairement à (cos)′ = −sin. Pour th, règle du quotient : (sh′ ch − sh ch′)/ch² = (ch² − sh²)/ch² = 1/ch², et 1/ch² = 1 − th² par l’identité fondamentale.</p>')}
${PROP('<p><b>sh</b> : sh′ = ch &gt; 0, donc sh est strictement croissante sur ℝ, de −∞ à +∞ ; c’est une bijection de ℝ sur ℝ, nulle en 0. <b>ch</b> : ch′ = sh, négative puis positive, donc ch décroît sur ]−∞ ; 0], croît sur [0 ; +∞[, minimum ch 0 = 1. <b>th</b> : th′ &gt; 0, strictement croissante, et <b>lim<sub>±∞</sub> th <i>x</i> = ±1</b> : deux asymptotes horizontales.</p>')}
${WHY('<p>Pour la limite de th : th <i>x</i> = (e<sup><i>x</i></sup> − e<sup>−<i>x</i></sup>)/(e<sup><i>x</i></sup> + e<sup>−<i>x</i></sup>) = (1 − e<sup>−2<i>x</i></sup>)/(1 + e<sup>−2<i>x</i></sup>) en divisant par e<sup><i>x</i></sup> ; quand <i>x</i> → +∞, e<sup>−2<i>x</i></sup> → 0 et th <i>x</i> → 1. Par imparité, th <i>x</i> → −1 en −∞. Les limites de sh et ch en +∞ sont +∞, car e<sup><i>x</i></sup>/2 l’emporte sur e<sup>−<i>x</i></sup>/2.</p>')}
${EX('<p>Pente de sh en 0 : ch 0 = 1, comme sin. Pente de th en 0 : 1 − 0 = 1. Dérivée de ln(ch <i>x</i>) : sh <i>x</i>/ch <i>x</i> = th <i>x</i> ; donc ∫ th <i>x</i> d<i>x</i> = ln(ch <i>x</i>) + <i>C</i>, sans valeur absolue car ch &gt; 0.</p>')}`,
   fig:(()=>{ const P=plane({x:[-3,3],y:[-2.5,3.5],h:280,lab:1}); P.seg(-3,1,3,1,{c:'var(--muted)',w:1,dash:true}).seg(-3,-1,3,-1,{c:'var(--muted)',w:1,dash:true}).fn(ch,{c:'var(--math)'}).fn(sh,{c:'var(--spark)'}).fn(th,{c:'var(--accent)'}).text(1.3,2.9,'ch',{c:'var(--math)'}).text(2.1,1.8,'sh',{c:'var(--spark)'}).text(-2.9,-1,'th',{dy:14,c:'var(--accent)'}); return axes(P,[-3,3],[-2.5,3.5]).svg(); })()},
  {h:'Une dérivée logarithmique',p:'Quelle est la dérivée de <i>f</i>(<i>x</i>) = ln(ch(3<i>x</i>)) ?',
   opts:['3 th(3<i>x</i>)','th(3<i>x</i>)/3','3 sh(3<i>x</i>)','1/ch(3<i>x</i>)'],ans:0,
   why:'(ln u)′ = u′/u avec u = ch(3x), u′ = 3 sh(3x). Donc f′ = 3 sh(3x)/ch(3x) = 3 th(3x).'},
  {h:'Formules d’addition',p:`<p>Les formules de cos(<i>a</i> + <i>b</i>) et sin(<i>a</i> + <i>b</i>) ont des analogues hyperboliques, qu’on démontre en quelques lignes avec les exponentielles, sans aucune géométrie.</p>
${THM('<p><b>ch(<i>a</i> + <i>b</i>) = ch <i>a</i> ch <i>b</i> + sh <i>a</i> sh <i>b</i></b>, <b>sh(<i>a</i> + <i>b</i>) = sh <i>a</i> ch <i>b</i> + ch <i>a</i> sh <i>b</i></b>, <b>th(<i>a</i> + <i>b</i>) = (th <i>a</i> + th <i>b</i>)/(1 + th <i>a</i> th <i>b</i>)</b>. Cas particuliers : <b>ch 2<i>a</i> = ch² <i>a</i> + sh² <i>a</i> = 2ch² <i>a</i> − 1 = 1 + 2sh² <i>a</i></b>, <b>sh 2<i>a</i> = 2 sh <i>a</i> ch <i>a</i></b>.</p>')}
${WHY('<p>Preuve de la première. Avec <i>A</i> = e<sup><i>a</i></sup>, <i>B</i> = e<sup><i>b</i></sup> : 4 ch <i>a</i> ch <i>b</i> = (<i>A</i> + 1/<i>A</i>)(<i>B</i> + 1/<i>B</i>) = <i>AB</i> + <i>A</i>/<i>B</i> + <i>B</i>/<i>A</i> + 1/(<i>AB</i>) et 4 sh <i>a</i> sh <i>b</i> = (<i>A</i> − 1/<i>A</i>)(<i>B</i> − 1/<i>B</i>) = <i>AB</i> − <i>A</i>/<i>B</i> − <i>B</i>/<i>A</i> + 1/(<i>AB</i>). La somme vaut 2<i>AB</i> + 2/(<i>AB</i>) = 2(e<sup><i>a</i>+<i>b</i></sup> + e<sup>−(<i>a</i>+<i>b</i>)</sup>) = 4 ch(<i>a</i> + <i>b</i>). On divise par 4. La formule pour sh se prouve de même ; celle de th s’en déduit en divisant sh(<i>a</i> + <i>b</i>) par ch(<i>a</i> + <i>b</i>), puis haut et bas par ch <i>a</i> ch <i>b</i>. Les doubles : poser <i>b</i> = <i>a</i>, puis utiliser ch² − sh² = 1.</p>')}
${IDEA('<p>Par rapport aux formules trigonométriques, un seul signe change : cos(<i>a</i> + <i>b</i>) = cos <i>a</i> cos <i>b</i> <b>−</b> sin <i>a</i> sin <i>b</i>, mais ch(<i>a</i> + <i>b</i>) = ch <i>a</i> ch <i>b</i> <b>+</b> sh <i>a</i> sh <i>b</i>. Règle pratique : dans une identité trigonométrique, remplacer cos par ch et sin par sh, puis changer le signe de chaque produit de <b>deux</b> sinus. Ainsi cos² + sin² = 1 devient ch² − sh² = 1.</p>')}
${EX('<p>ch(2 ln 2) = 2ch²(ln 2) − 1 = 2 · 25/16 − 1 = 34/16 = 17/8. Contrôle direct : e<sup>2 ln 2</sup> = 4, donc ch(2 ln 2) = (4 + 1/4)/2 = 17/8. De même sh(2 ln 2) = 2 · (3/4)(5/4) = 15/8 = (4 − 1/4)/2.</p>')}`,
   note:'Les formules de linéarisation en découlent : ch² a = (1 + ch 2a)/2 et sh² a = (ch 2a − 1)/2. Elles servent pour ∫ ch² et ∫ sh².'},
  {kind:'Méthode',h:'Résoudre une équation hyperbolique en revenant aux exponentielles',
   p:`<p><b>Quand :</b> une équation fait intervenir sh <i>x</i>, ch <i>x</i> ou th <i>x</i> (sh <i>x</i> = 2, ch <i>x</i> = 3, th <i>x</i> = 3/5), ou mélange e<sup><i>x</i></sup> et e<sup>−<i>x</i></sup>. <b>Pourquoi ça marche :</b> avec <b><i>u</i> = e<sup><i>x</i></sup> &gt; 0</b>, on a e<sup>−<i>x</i></sup> = 1/<i>u</i> ; en multipliant par <i>u</i>, l’équation devient une équation du second degré en <i>u</i>, dont on ne garde que les racines <b>strictement positives</b>, puis <i>x</i> = ln <i>u</i>. Pour th, il est plus simple de poser <i>u</i> = e<sup>2<i>x</i></sup> : th <i>x</i> = (<i>u</i> − 1)/(<i>u</i> + 1). <b>Comment :</b></p><ol><li>remplace sh, ch, th par leur définition, puis e<sup><i>x</i></sup> par <i>u</i> et e<sup>−<i>x</i></sup> par 1/<i>u</i> ;</li><li>multiplie par <i>u</i> (ou 2<i>u</i>) pour obtenir un trinôme ;</li><li>résous, élimine les racines ≤ 0, reviens à <i>x</i> = ln <i>u</i>.</li></ol>`,
   demo:{enonce:'Résous sh <i>x</i> = 2.',
    etapes:[{f:'(e<sup><i>x</i></sup> − e<sup>−<i>x</i></sup>)/2 = 2, soit <i>u</i> − 1/<i>u</i> = 4 avec <i>u</i> = e<sup><i>x</i></sup> &gt; 0.',w:'On revient à la définition et on pose u.'},
     {f:'<i>u</i>² − 4<i>u</i> − 1 = 0.',w:'Multiplication par u ≠ 0.'},
     {f:'Δ = 16 + 4 = 20, <i>u</i> = (4 ± 2√5)/2 = 2 ± √5.',w:'Trinôme du second degré.'},
     {f:'2 − √5 &lt; 0 est à rejeter ; reste <i>u</i> = 2 + √5, donc <i>x</i> = ln(2 + √5) ≈ 1,444.',w:'Une exponentielle est strictement positive. On revient à x par le logarithme.'},
     {f:'Contrôle : e<sup><i>x</i></sup> = 2 + √5 ≈ 4,236, e<sup>−<i>x</i></sup> = 1/(2 + √5) = √5 − 2 ≈ 0,236, et (4,236 − 0,236)/2 = 2.',w:'(2 + √5)(√5 − 2) = 5 − 4 = 1, donc les deux exponentielles sont bien inverses.'}],
    conclusion:'sh <i>x</i> = 2 a l’unique solution <i>x</i> = ln(2 + √5). Pour sh <i>x</i> = <i>y</i> quelconque, le même calcul donnera <i>x</i> = ln(<i>y</i> + √(<i>y</i>² + 1)) : c’est la fonction argsh, étudiée juste après.'},
   note:'ch x = a a deux solutions opposées si a > 1 (ch est paire), une seule si a = 1, aucune si a < 1. th x = a a une solution si |a| < 1, aucune sinon.'},
  {h:'Résoudre th x = 3/5',p:'Résous th <i>x</i> = 3/5. Donne <i>x</i> arrondi au millième.',lab:'x =',ans:Math.log(2),tol:.002,
   why:'th x = (u − 1)/(u + 1) avec u = e^(2x). (u − 1)/(u + 1) = 3/5 ⇔ 5u − 5 = 3u + 3 ⇔ u = 4. Donc 2x = ln 4 et x = ln 2 ≈ 0,693. Contrôle : th(ln 2) = (3/4)/(5/4) = 3/5.'},
  {h:'argsh : la réciproque de sh',p:`<p>sh est une bijection continue strictement croissante de ℝ sur ℝ. Elle a donc une réciproque, définie partout, et la méthode précédente permet de l’exprimer avec un logarithme.</p>
${DEF('<p><b>argsh</b> : ℝ → ℝ (« argument sinus hyperbolique ») est la réciproque de sh : argsh <i>y</i> est l’unique réel <i>x</i> tel que sh <i>x</i> = <i>y</i>.</p>')}
${THM(`<p>Pour tout <i>x</i> réel : <b>argsh <i>x</i> = ln(<i>x</i> + √(<i>x</i>² + 1))</b>, et <b>(argsh <i>x</i>)′ = ${F(1,'√(<i>x</i>² + 1)')}</b>.</p>`)}
${WHY('<p><b>Expression</b> : sh <i>y</i> = <i>x</i> ⇔ e<sup><i>y</i></sup> − e<sup>−<i>y</i></sup> = 2<i>x</i> ⇔ <i>u</i>² − 2<i>x</i><i>u</i> − 1 = 0 avec <i>u</i> = e<sup><i>y</i></sup>. Les racines sont <i>x</i> ± √(<i>x</i>² + 1) ; comme √(<i>x</i>² + 1) &gt; |<i>x</i>|, la racine <i>x</i> − √(<i>x</i>² + 1) est négative, à rejeter. Donc e<sup><i>y</i></sup> = <i>x</i> + √(<i>x</i>² + 1) et <i>y</i> = ln(<i>x</i> + √(<i>x</i>² + 1)). <b>Dérivée</b>, par le théorème de la réciproque : (argsh)′(<i>x</i>) = 1/sh′(<i>y</i>) = 1/ch <i>y</i> = 1/√(1 + sh² <i>y</i>) = 1/√(1 + <i>x</i>²), la racine positive car ch &gt; 0. On peut aussi dériver le logarithme directement et retrouver le même résultat, avec plus de calculs.</p>')}
${IDEA('<p>Le mot « argument » rappelle que <i>x</i> n’est pas un angle : argsh <i>y</i> est le paramètre <i>t</i> du point (ch <i>t</i> ; sh <i>t</i>) de l’hyperbole dont l’ordonnée vaut <i>y</i>. La formule logarithmique n’a pas d’analogue réel pour arcsin : c’est une différence profonde entre les deux familles, qui s’explique avec les nombres complexes.</p>')}
${EX('<p>argsh(3/4) = ln(3/4 + √(9/16 + 1)) = ln(3/4 + 5/4) = ln 2, cohérent avec sh(ln 2) = 3/4. argsh 2 = ln(2 + √5) ≈ 1,444, la solution trouvée à la méthode précédente. argsh 0 = ln 1 = 0, et argsh est impaire comme sh.</p>')}`,
   fig:(()=>{ const P=plane({x:[-3,3],y:[-3,3],h:280,lab:1}); P.seg(-3,-3,3,3,{c:'var(--muted)',w:1,dash:true}).fn(sh,{c:'var(--spark)'}).fn(asinh,{c:'var(--math)'}).text(1.5,2.6,'sh',{c:'var(--spark)'}).text(2.2,1.1,'argsh',{c:'var(--math)'}); return axes(P,[-3,3],[-3,3]).svg(); })(),
   note:'Les graphes de sh et argsh sont symétriques par rapport à la droite y = x, comme toute fonction et sa réciproque.'},
  {h:'argch et argth',p:`<p>ch n’est pas injective sur ℝ (elle est paire) : comme pour cos, on la restreint. th est injective mais ne prend que les valeurs de ]−1 ; 1[ : sa réciproque n’est définie que là.</p>
${DEF('<p><b>argch</b> : [1 ; +∞[ → [0 ; +∞[ est la réciproque de ch restreint à [0 ; +∞[ : argch <i>y</i> est l’unique <i>x</i> ≥ 0 tel que ch <i>x</i> = <i>y</i>. <b>argth</b> : ]−1 ; 1[ → ℝ est la réciproque de th : argth <i>y</i> est l’unique réel <i>x</i> tel que th <i>x</i> = <i>y</i>.</p>')}
${THM(`<p>Pour <i>x</i> ≥ 1 : <b>argch <i>x</i> = ln(<i>x</i> + √(<i>x</i>² − 1))</b>, et pour <i>x</i> &gt; 1 : <b>(argch <i>x</i>)′ = ${F(1,'√(<i>x</i>² − 1)')}</b>. Pour |<i>x</i>| &lt; 1 : <b>argth <i>x</i> = ½ ln ${F('1 + <i>x</i>','1 − <i>x</i>')}</b> et <b>(argth <i>x</i>)′ = ${F(1,'1 − <i>x</i>²')}</b>.</p>`)}
${WHY('<p><b>argch</b> : ch <i>y</i> = <i>x</i> avec <i>y</i> ≥ 0 ⇔ <i>u</i>² − 2<i>xu</i> + 1 = 0 avec <i>u</i> = e<sup><i>y</i></sup> ≥ 1. Les racines <i>x</i> ± √(<i>x</i>² − 1) ont pour produit 1 ; celle qui est ≥ 1 est <i>x</i> + √(<i>x</i>² − 1). Dérivée : 1/ch′(<i>y</i>) = 1/sh <i>y</i> = 1/√(ch² <i>y</i> − 1) = 1/√(<i>x</i>² − 1), racine positive car <i>y</i> &gt; 0 ⇒ sh <i>y</i> &gt; 0. <b>argth</b> : th <i>y</i> = <i>x</i> ⇔ (e<sup>2<i>y</i></sup> − 1)/(e<sup>2<i>y</i></sup> + 1) = <i>x</i> ⇔ e<sup>2<i>y</i></sup> = (1 + <i>x</i>)/(1 − <i>x</i>), d’où <i>y</i>. Dérivée : 1/th′(<i>y</i>) = 1/(1 − th² <i>y</i>) = 1/(1 − <i>x</i>²).</p>')}
${EX('<p>argch(5/4) = ln(5/4 + √(25/16 − 1)) = ln(5/4 + 3/4) = ln 2, cohérent avec ch(ln 2) = 5/4. argth(3/5) = ½ ln((8/5)/(2/5)) = ½ ln 4 = ln 2, la solution de th <i>x</i> = 3/5 trouvée plus haut. argch 1 = 0.</p>')}
${WARN('<p>argch n’est pas dérivable en 1 : la tangente y est verticale, image de la tangente horizontale de ch en 0 (ch′(0) = sh 0 = 0). Et l’autre racine ln(<i>x</i> − √(<i>x</i>² − 1)) = −argch <i>x</i> correspond à la branche <i>y</i> ≤ 0 qu’on a écartée.</p>')}`,
   fig:(()=>{ const P=plane({x:[-1.5,4],y:[-2.5,2.5],h:260,lab:1}); P.seg(1,-2.5,1,2.5,{c:'var(--muted)',w:1,dash:true}).seg(-1,-2.5,-1,2.5,{c:'var(--muted)',w:1,dash:true}).fn(x=>x>=1?acosh(x):NaN,{from:1,c:'var(--math)'}).fn(x=>Math.abs(x)<1?atanh(x):NaN,{from:-.999,to:.999,c:'var(--accent)',n:400}).text(3.9,acosh(3.9),'argch',{a:'end',dy:-8,c:'var(--math)'}).text(-.9,1.6,'argth',{c:'var(--accent)'}); return axes(P,[-1.5,4],[-2.5,2.5]).svg(); })()},
  {kind:'Méthode',h:'Primitiver avec argsh, argch et argth',
   p:`<p><b>Quand :</b> l’intégrande est 1/√(<i>x</i>² + <i>a</i>²), 1/√(<i>x</i>² − <i>a</i>²) ou 1/(<i>a</i>² − <i>x</i>²), les cousines hyperboliques de 1/√(<i>a</i>² − <i>x</i>²) et 1/(<i>a</i>² + <i>x</i>²). <b>Pourquoi ça marche :</b> ce sont les dérivées des réciproques hyperboliques : <b>∫ d<i>x</i>/√(<i>x</i>² + 1) = argsh <i>x</i> + <i>C</i></b>, <b>∫ d<i>x</i>/√(<i>x</i>² − 1) = argch <i>x</i> + <i>C</i></b> (<i>x</i> &gt; 1), <b>∫ d<i>x</i>/(1 − <i>x</i>²) = argth <i>x</i> + <i>C</i></b> (|<i>x</i>| &lt; 1). Avec <i>a</i> : ∫ d<i>x</i>/√(<i>x</i>² + <i>a</i>²) = argsh(<i>x</i>/<i>a</i>) + <i>C</i>. Le changement de variable <i>x</i> = <i>a</i> sh <i>t</i> donne le même résultat, car √(<i>a</i>² sh² <i>t</i> + <i>a</i>²) = <i>a</i> ch <i>t</i> et d<i>x</i> = <i>a</i> ch <i>t</i> d<i>t</i> : l’intégrande devient 1. <b>Comment :</b></p><ol><li>reconnais la forme et le coefficient <i>a</i> (mets-le en évidence si besoin : √(4<i>x</i>² + 9) = 2√(<i>x</i>² + 9/4)) ;</li><li>écris la primitive, puis évalue ; pour une valeur exacte, remplace argsh ou argch par son logarithme.</li></ol>`,
   demo:{enonce:`Calcule ∫₀² ${F('d<i>x</i>','√(<i>x</i>² + 4)')} par la formule, puis retrouve-le avec <i>x</i> = 2 sh <i>t</i>.`,
    etapes:[{f:'<i>a</i> = 2 : une primitive est argsh(<i>x</i>/2).',w:'Forme 1/√(x² + a²). Contrôle : (argsh(x/2))′ = (1/2)/√(x²/4 + 1) = 1/√(x² + 4).'},
     {f:'∫₀² d<i>x</i>/√(<i>x</i>² + 4) = argsh 1 − argsh 0 = ln(1 + √2) ≈ 0,881.',w:'argsh 1 = ln(1 + √(1 + 1)) par la formule logarithmique.'},
     {f:'Autre voie : <i>x</i> = 2 sh <i>t</i>, d<i>x</i> = 2 ch <i>t</i> d<i>t</i>, √(<i>x</i>² + 4) = √(4 sh² <i>t</i> + 4) = 2 ch <i>t</i>.',w:'1 + sh² = ch², et ch > 0 : la racine disparaît sans discussion de signe.'},
     {f:'Bornes : <i>x</i> = 0 ↔ <i>t</i> = 0 ; <i>x</i> = 2 ↔ sh <i>t</i> = 1 ↔ <i>t</i> = argsh 1. L’intégrale devient ∫₀<sup>argsh 1</sup> d<i>t</i> = argsh 1.',w:'Le changement de variable rend l’intégrande égal à 1 : c’est exactement ce que fait x = a sin t pour √(a² − x²).'}],
    conclusion:'∫₀² d<i>x</i>/√(<i>x</i>² + 4) = argsh 1 = ln(1 + √2) ≈ 0,881. Pour √(<i>x</i>² + <i>a</i>²), penser à <i>x</i> = <i>a</i> sh <i>t</i> ; pour √(<i>x</i>² − <i>a</i>²), à <i>x</i> = <i>a</i> ch <i>t</i>.'},
   note:'Le même changement x = a sh t permet de calculer ∫ √(x² + a²) dx, qui devient a² ∫ ch² t dt, linéarisable.'},
  {h:'Une intégrale en argth',p:`Calcule ∫₀<sup>1/2</sup> ${F('d<i>x</i>','1 − <i>x</i>²')}, arrondi au millième.`,lab:'I =',ans:Math.log(3)/2,tol:.002,
   why:'Primitive argth x. I = argth(1/2) − 0 = ½ ln((1 + 1/2)/(1 − 1/2)) = ½ ln 3 ≈ 0,549.'},
  {h:'Laquelle est fausse ?',p:'Une seule de ces égalités est fausse. Laquelle ?',
   opts:['argsh(−<i>x</i>) = −argsh <i>x</i> pour tout <i>x</i>','argth <i>x</i> = ½ ln((1 + <i>x</i>)/(1 − <i>x</i>)) pour |<i>x</i>| &lt; 1','argch <i>x</i> = ln(<i>x</i> − √(<i>x</i>² − 1)) pour <i>x</i> ≥ 1','(argth <i>x</i>)′ = 1/(1 − <i>x</i>²) pour |<i>x</i>| &lt; 1'],ans:2,
   why:'ln(x − √(x² − 1)) est négatif ou nul (l’argument est entre 0 et 1) : c’est −argch x, la racine rejetée. La bonne formule est argch x = ln(x + √(x² − 1)). Les trois autres sont vraies.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`${KEEP('<ul><li><b>ch <i>x</i></b> = (e<sup><i>x</i></sup> + e<sup>−<i>x</i></sup>)/2 (paire, ≥ 1), <b>sh <i>x</i></b> = (e<sup><i>x</i></sup> − e<sup>−<i>x</i></sup>)/2 (impaire, bijection ℝ → ℝ), <b>th</b> = sh/ch (impaire, valeurs dans ]−1 ; 1[). ch + sh = e<sup><i>x</i></sup>.</li><li><b>ch² − sh² = 1</b> : le point (ch <i>t</i> ; sh <i>t</i>) parcourt l’hyperbole <i>x</i>² − <i>y</i>² = 1. Et 1 − th² = 1/ch².</li><li>Dérivées : sh′ = ch, ch′ = sh, th′ = 1/ch² = 1 − th². Pas de signe moins.</li><li>Addition : ch(<i>a</i> + <i>b</i>) = ch <i>a</i> ch <i>b</i> + sh <i>a</i> sh <i>b</i>, sh(<i>a</i> + <i>b</i>) = sh <i>a</i> ch <i>b</i> + ch <i>a</i> sh <i>b</i> ; ch 2<i>a</i> = 2ch² <i>a</i> − 1 = 1 + 2sh² <i>a</i>, sh 2<i>a</i> = 2 sh <i>a</i> ch <i>a</i>.</li><li>Équations : poser <i>u</i> = e<sup><i>x</i></sup> &gt; 0, trinôme, garder <i>u</i> &gt; 0, <i>x</i> = ln <i>u</i>.</li><li><b>argsh <i>x</i> = ln(<i>x</i> + √(<i>x</i>² + 1))</b> sur ℝ ; <b>argch <i>x</i> = ln(<i>x</i> + √(<i>x</i>² − 1))</b> sur [1 ; +∞[ ; <b>argth <i>x</i> = ½ ln((1 + <i>x</i>)/(1 − <i>x</i>))</b> sur ]−1 ; 1[.</li><li>Dérivées : (argsh)′ = 1/√(<i>x</i>² + 1), (argch)′ = 1/√(<i>x</i>² − 1), (argth)′ = 1/(1 − <i>x</i>²) ; d’où les primitives correspondantes, et le changement <i>x</i> = <i>a</i> sh <i>t</i> pour √(<i>x</i>² + <i>a</i>²).</li></ul>')}`,
   note:'Trigonométrie : cercle, cos² + sin² = 1, arcs. Hyperbolique : hyperbole, ch² − sh² = 1, arguments logarithmiques. Les formules se correspondent à un signe près sur les produits de deux sinus.'},
  {kind:'Problème',h:'L’aire du secteur hyperbolique',
   p:`Sur le cercle unité, le paramètre <i>t</i> du point (cos <i>t</i> ; sin <i>t</i>) vaut deux fois l’aire du secteur balayé depuis (1 ; 0). On veut montrer que c’est pareil pour l’hyperbole : l’aire <i>A</i>(<i>t</i>) du secteur délimité par l’origine, le point (1 ; 0) et le point <i>M</i> = (ch <i>t</i> ; sh <i>t</i>) de l’hyperbole <i>x</i>² − <i>y</i>² = 1 vaut <i>t</i>/2, pour <i>t</i> &gt; 0. L’aire du secteur est celle du triangle <i>OHM</i> (où <i>H</i> = (ch <i>t</i> ; 0)) moins l’aire sous l’arc d’hyperbole entre <i>x</i> = 1 et <i>x</i> = ch <i>t</i>, où l’hyperbole a pour équation <i>y</i> = √(<i>x</i>² − 1).`,
   fig:(()=>{ const t=1, P=plane({x:[-.3,2.2],y:[-.3,1.6],h:240,grid:false,lx:1,ly:1}); const pts=[[0,0]]; for(let i=0;i<=40;i++){ const u=t*i/40; pts.push([ch(u),sh(u)]); } P.poly(pts,{fill:'var(--accent)',fo:.3,c:null}).area(x=>Math.sqrt(Math.max(0,x*x-1)),1,ch(t),{fill:'var(--spark)',fo:.3}).curve(ch,sh,-1.3,1.3,{c:'var(--math)'}).seg(0,0,ch(t),sh(t),{c:'var(--ink)',w:2}).seg(ch(t),0,ch(t),sh(t),{c:'var(--ink)',w:2,dash:true}).dot(ch(t),sh(t),{l:'M',dy:-8}).dot(1,0,{r:4,l:'(1 ; 0)',dy:16,dx:-20}).dot(ch(t),0,{r:4,l:'H',dy:16}); return P.svg(); })(),
   parts:[
    {q:'a) Pour <i>t</i> = 1, quelle est l’aire du triangle <i>OHM</i> ? Arrondis au millième.',lab:'aire =',ans:.5*ch(1)*sh(1),tol:.002,hint:'Base ch 1, hauteur sh 1.',why:'½ ch 1 · sh 1 ≈ ½ · 1,543 · 1,175 ≈ 0,907.'},
    {q:'b) Pour calculer ∫₁<sup>ch <i>t</i></sup> √(<i>x</i>² − 1) d<i>x</i>, quel changement de variable fait disparaître la racine ?',opts:['<i>x</i> = sin <i>u</i>, car 1 − sin² <i>u</i> = cos² <i>u</i>','<i>x</i> = ch <i>u</i>, car ch² <i>u</i> − 1 = sh² <i>u</i> et d<i>x</i> = sh <i>u</i> d<i>u</i>','<i>x</i> = sh <i>u</i>, car sh² <i>u</i> − 1 = ch² <i>u</i>','<i>x</i> = tan <i>u</i>, car 1 + tan² <i>u</i> = 1/cos² <i>u</i>'],ans:1,hint:'On veut x² − 1 égal à un carré parfait ; quelle identité hyperbolique a la forme (…)² − 1 = (…)² ?',why:'Avec x = ch u (u ≥ 0), √(x² − 1) = √(sh² u) = sh u (sh u ≥ 0), dx = sh u du, et les bornes deviennent u = 0 et u = t. L’intégrale devient ∫₀ᵗ sh² u du.'},
    {q:'c) Calcule ∫₀¹ sh² <i>u</i> d<i>u</i>, arrondi au millième.',lab:'=',ans:(sh(1)*ch(1)-1)/2,tol:.002,hint:'Linéarise : sh² u = (ch 2u − 1)/2, et ∫ ch 2u du = sh 2u/2.',why:'∫₀ᵗ (ch 2u − 1)/2 du = [sh 2u/4 − u/2]₀ᵗ = sh 2t/4 − t/2 = (sh t ch t − t)/2. Pour t = 1 : (1,175 · 1,543 − 1)/2 ≈ 0,407.'},
    {q:'d) Déduis-en l’aire <i>A</i>(1) du secteur hyperbolique.',lab:'A(1) =',ans:.5,tol:.002,hint:'Triangle moins aire sous l’arc.',why:'A(1) = ½ ch 1 sh 1 − (sh 1 ch 1 − 1)/2 = 1/2. En général A(t) = ½ ch t sh t − (sh t ch t − t)/2 = t/2.'},
   ],
   sol:'<p>Le triangle <i>OHM</i> a pour aire ½ ch <i>t</i> sh <i>t</i>. L’aire sous l’arc est ∫₁<sup>ch <i>t</i></sup> √(<i>x</i>² − 1) d<i>x</i> ; avec <i>x</i> = ch <i>u</i>, d<i>x</i> = sh <i>u</i> d<i>u</i>, √(ch² <i>u</i> − 1) = sh <i>u</i> (car <i>u</i> ≥ 0), bornes 0 et <i>t</i> : elle vaut ∫₀<sup><i>t</i></sup> sh² <i>u</i> d<i>u</i> = ∫₀<sup><i>t</i></sup> (ch 2<i>u</i> − 1)/2 d<i>u</i> = sh 2<i>t</i>/4 − <i>t</i>/2 = (sh <i>t</i> ch <i>t</i> − <i>t</i>)/2.</p><p>Donc <i>A</i>(<i>t</i>) = ½ ch <i>t</i> sh <i>t</i> − ½ sh <i>t</i> ch <i>t</i> + <i>t</i>/2 = <b><i>t</i>/2</b>. Le paramètre hyperbolique est le double d’une aire, exactement comme l’angle au centre pour le cercle : c’est la vraie raison du parallèle entre (cos, sin) et (ch, sh), et de l’appellation « argument ».</p>'},
  {kind:'Problème',h:'La longueur d’un arc de parabole',
   p:`La longueur de la courbe <i>y</i> = <i>f</i>(<i>x</i>) entre <i>x</i> = 0 et <i>x</i> = 1 est donnée par <i>L</i> = ∫₀¹ √(1 + <i>f</i>′(<i>x</i>)²) d<i>x</i> (on additionne les petites hypoténuses √(d<i>x</i>² + d<i>y</i>²)). On l’applique à la parabole <i>f</i>(<i>x</i>) = <i>x</i>²/2, pour laquelle <i>L</i> = ∫₀¹ √(1 + <i>x</i>²) d<i>x</i>. La racine √(1 + <i>x</i>²) appelle le changement de variable <i>x</i> = sh <i>t</i>.`,
   fig:(()=>{ const P=plane({x:[-.3,1.4],y:[-.2,.8],h:180,grid:false,lx:.5,ly:.5}); P.fn(x=>x*x/2,{from:0,to:1,c:'var(--math)',w:4}).fn(x=>x*x/2,{from:-.3,to:1.4,c:'var(--muted)',w:1.5,dash:true}).dot(1,.5,{r:4,l:'(1 ; ½)',dy:-8}).dot(0,0,{r:4}); return axes(P,[-.3,1.4],[-.2,.8]).svg(); })(),
   parts:[
    {q:'a) Avec <i>x</i> = sh <i>t</i>, la borne <i>x</i> = 1 devient <i>t</i> = argsh 1. Calcule cette valeur, arrondie au millième.',lab:'argsh 1 =',ans:Math.log(1+Math.SQRT2),tol:.002,hint:'argsh x = ln(x + √(x² + 1)).',why:'argsh 1 = ln(1 + √2) ≈ 0,881.'},
    {q:'b) Que devient l’intégrale ∫₀¹ √(1 + <i>x</i>²) d<i>x</i> ?',opts:['∫₀<sup>argsh 1</sup> ch <i>t</i> d<i>t</i>','∫₀<sup>argsh 1</sup> ch² <i>t</i> d<i>t</i>','∫₀<sup>argsh 1</sup> sh <i>t</i> ch <i>t</i> d<i>t</i>','∫₀¹ ch² <i>t</i> d<i>t</i>'],ans:1,hint:'√(1 + sh² t) = ch t, et dx = ch t dt.',why:'√(1 + sh² t) = ch t (ch > 0), dx = ch t dt : l’intégrande devient ch t · ch t = ch² t, et les bornes deviennent 0 et argsh 1.'},
    {q:'c) Avec ch² <i>t</i> = (1 + ch 2<i>t</i>)/2, une primitive de ch² <i>t</i> est <i>t</i>/2 + sh 2<i>t</i>/4. Calcule sh(2 argsh 1), arrondi au millième.',lab:'=',ans:2*Math.SQRT2,tol:.002,hint:'sh 2a = 2 sh a ch a, avec sh a = 1 et ch a = √(1 + sh² a).',why:'Pour a = argsh 1 : sh a = 1, ch a = √2, donc sh 2a = 2 · 1 · √2 = 2√2 ≈ 2,828.'},
    {q:'d) Quelle est la longueur <i>L</i> de l’arc ? Arrondis au millième.',lab:'L =',ans:(Math.SQRT2+Math.log(1+Math.SQRT2))/2,tol:.002,hint:'L = argsh 1/2 + sh(2 argsh 1)/4.',why:'L = ln(1 + √2)/2 + 2√2/4 = (√2 + ln(1 + √2))/2 ≈ (1,414 + 0,881)/2 ≈ 1,148. Un peu plus que la corde, de longueur √(1 + 1/4) ≈ 1,118.'},
   ],
   sol:'<p><i>f</i>′(<i>x</i>) = <i>x</i>, donc <i>L</i> = ∫₀¹ √(1 + <i>x</i>²) d<i>x</i>. Avec <i>x</i> = sh <i>t</i> : d<i>x</i> = ch <i>t</i> d<i>t</i>, √(1 + sh² <i>t</i>) = ch <i>t</i>, et <i>t</i> va de 0 à <i>T</i> = argsh 1 = ln(1 + √2). Donc <i>L</i> = ∫₀<sup><i>T</i></sup> ch² <i>t</i> d<i>t</i> = [<i>t</i>/2 + sh 2<i>t</i>/4]₀<sup><i>T</i></sup>.</p><p>En <i>T</i> : sh <i>T</i> = 1, ch <i>T</i> = √2, sh 2<i>T</i> = 2√2. D’où <i>L</i> = ln(1 + √2)/2 + √2/2 = (√2 + ln(1 + √2))/2 ≈ 1,148.</p><p>En revenant à <i>x</i> : sh 2<i>t</i>/4 = sh <i>t</i> ch <i>t</i>/2 = <i>x</i>√(1 + <i>x</i>²)/2, ce qui donne la primitive générale ∫ √(1 + <i>x</i>²) d<i>x</i> = (<i>x</i>√(1 + <i>x</i>²) + argsh <i>x</i>)/2 + <i>C</i>, à comparer avec (<i>x</i>√(1 − <i>x</i>²) + arcsin <i>x</i>)/2 pour √(1 − <i>x</i>²).</p>'},
]},
);
})();
